const a={"les-n5-u09-01":{pedagogical_framework:{what:{summary:"Pola perbandingan komparatif dua objek: [A] のほうが [B] より [Sifat] です, dan pertanyaan pilihan どちら (dochira).",canDo:"Bisa membandingkan harga, kecepatan, atau kenyamanan dua pilihan transportasi/barang.",targetPatterns:["[A] のほうが [B] より [Sifat] です","[A] と [B] と どちらが [Sifat] ですか","どちらも [Afirmatif/Negatif]"],coreVocabSample:["どちら","のほうが","より","はやい","やすい","ちかい"]},sensei_context:{sceneIntro:"Budi dan Tanaka mendiskusikan sarana transportasi tercepat menuju bandara Narita. Kereta vs Bus ekspres.",dailyMission:"Mampu menggunakan pola komparasi [A] のほうが [B] より untuk memberikan rekomendasi berbasis perbandingan.",whyOrder:"Setelah bisa mendeskripsikan sifat satu benda, sekarang kita naik level dengan membandingkan dua opsi berbeda!"},cultural_notes:{title:"Kesantunan Kata Tanya Pilihan どちら (Dochira)",etiquette:"Dalam ragam formal/sopan, selalu gunakan どちら (dochira) alih-alih どっち (dotchi). Dotchi hanya untuk teman sebaya kasual.",taboos:"Jangan terbalik susunannya! [A] のほうが adalah pihak yang MENANG sifatnya (lebih cepat/murah)."},pronunciation_tips:{title:"Intonasi Kalimat Komparasi",moraNote:'Beri penekanan lembut pada "no hou ga" untuk menegaskan subjek yang lebih unggul.',soundTip:'Katakan "densha no hou ga hayai desu" secara teratur.'},common_pitfalls:[{title:'Terbalik Menempatkan "No Hou Ga" dan "Yori"',caseScenario:"Ingin bilang kereta lebih cepat dari bus, tapi salah taruh.",pitfallWarning:'"バス の ほう が でんしゃ より はやい です。" (Artinya jadi: bus lebih cepat)',rightSolution:'"でんしゃ の ほう が バス より はやい です。" (Kereta lebih cepat dari bus)',explanation:'Pihak yang memegang keunggulan sifat SELALU ditempeli "のほうが".'},{title:'Menggunakan Kata Tanya "Dore" untuk 2 Pilihan',caseScenario:"Memakai dore saat memilih antara 2 benda.",pitfallWarning:'"でんしゃ と バス と どれ が はやい ですか。" (Salah)',rightSolution:'"でんしゃ と バス と どちら が はやい ですか。" (Benar)',explanation:"Untuk DUA pilihan wajib memakai どちら (dochira). どれ hanya untuk TIGA pilihan atau lebih."}],who_and_when:{situational_context:"Memilih rute bepergian, membandingkan barang belanjaan, memesan menu.",social_relations:"Ragam sopan standar (Teineigo) yang sangat tepat di kantor maupun ruang publik.",when_not_to_use:"Jangan pakai dotchi kepada supervisor kerja."},scenario:{title:"Memilih Transportasi ke Bandara Narita",setting:"Meja kerja kantor, konsultasi perjalanan dinas, pukul 15.00",narrative:"Tanaka menanyakan kepada Budi apakah lebih memilih naik kereta bandara atau bus ekspres."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"ブディさん、成田空港【なりたくうこう】まで 電車【でんしゃ】と バスと どちらが 速【はや】いですか。",furigana:"ブディさん、成田空港まで 電車と バスと どちらが 速いですか。",romaji:"Budi-san, Narita kuukou made densha to basu to dochira ga hayai desu ka.",idText:"Budi-san, sampai Bandara Narita antara kereta dan bus mana yang lebih cepat?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"電車【でんしゃ】のほうが バスより 速【はや】いです。１時間【いちじかん】で 着【つ】きます。",furigana:"電車のほうが バスより 速いです。１時間で 着きます。",romaji:"Densha no hou ga basu yori hayai desu. Ichijikan de tsukimasu.",idText:"Kereta lebih cepat daripada bus. Tiba dalam waktu satu jam."},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"運賃【うんちん】は どちらが 安【やす】いですか。",furigana:"運賃は どちらが 安いですか。",romaji:"Unchin wa dochira ga yasui desu ka.",idText:"Ongkosnya mana yang lebih murah?"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"バスのほうが 電車【でんしゃ】より 安【やす】いです。１０００円【せんえん】安【やす】いです。",furigana:"バスのほうが 電車より 安いです。１０００円安いです。",romaji:"Basu no hou ga densha yori yasui desu. Sen-en yasui desu.",idText:"Bus lebih murah daripada kereta. Lebih murah 1000 yen."},{id:"d5",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"時間【じかん】が 大切【たいせつ】なら、電車のほうが いいですね。",furigana:"時間が 大切なら、電車のほうが いいですね。",romaji:"Jikan ga taisetsu nara, densha no hou ga ii desu ne.",idText:"Kalau waktu yang utama, kereta lebih baik ya."},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、私【わたし】も 電車【でんしゃ】のほうが 好【す】きです。渋滞【じゅうたい】が ありません。",furigana:"はい、私も 電車のほうが 好きです。渋滞が ありません。",romaji:"Hai, watashi mo densha no hou ga suki desu. Juutai ga arimasen.",idText:"Iya, saya juga lebih suka kereta. Tidak ada macet."},{id:"d7",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"じゃあ、成田エクスプレスで 行【い】きましょう！切符【きっぷ】を 手配【てはい】します。",furigana:"じゃあ、成田エクスプレスで 行きましょう！切符を 手配します。",romaji:"Jaa, Narita Ekusupuresu de ikimashou! Kippu o tehai shimasu.",idText:"Kalau begitu mari kita naik Narita Express! Saya pesankan tiketnya."},{id:"d8",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"ありがとうございます！よろしく お願【ねが】いします。",furigana:"ありがとうございます！よろしくお願いします。",romaji:"Arigatou gozaimasu! Yoroshiku onegaishimasu.",idText:"Terima kasih banyak! Mohon bantuannya."}],vocab_breakdown:[{id:"vg-n5-01023",word:"今",reading:"いま",romaji:"ima",meaning:"sekarang",pos:"adverb",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"今のアナウンスは何だったのですか。",furigana:"今のアナウンスは何だったのですか。",romaji:"",idText:"What did the announcement just say?"}},{id:"vg-n5-01111",word:"月曜日",reading:"げつようび",romaji:"getsuyoubi",meaning:"Senin",pos:"adverb",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"月曜日までにここに来ています。",furigana:"月曜日までにここに来ています。",romaji:"",idText:"I'll be here by Monday."}},{id:"vg-n5-01176",word:"たいへん",reading:"たいへん",romaji:"taihen",meaning:"sangat",pos:"adverb",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"それはたいへんなショックでした。",furigana:"それはたいへんなショックでした。",romaji:"",idText:"It was such a shock."}},{id:"vg-n5-01183",word:"たぶん",reading:"たぶん",romaji:"tabun",meaning:"mungkin",pos:"adverb",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"君にはたぶんみんなわかっていることでしょう。",furigana:"君にはたぶんみんなわかっていることでしょう。",romaji:"",idText:"I expect you know all about it."}},{id:"vg-n5-01210",word:"どうぞ",reading:"どうぞ",romaji:"douzo",meaning:"silakan / tolong",pos:"adverb",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"写真をどうぞ見せて下さい。",furigana:"写真をどうぞ見せて下さい。",romaji:"",idText:"Tolong show me your picture."}},{id:"vg-n5-01217",word:"土曜日",reading:"どようび",romaji:"doyoubi",meaning:"Sabtu",pos:"adverb",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"私は土曜日からここにいます。",furigana:"私は土曜日からここにいます。",romaji:"",idText:"I've been here since Saturday."}},{id:"vg-n5-01291",word:"もう",reading:"もう",romaji:"mou",meaning:"sudah",pos:"adverb",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"もう～、なにやってんだよ。",furigana:"もう～、なにやってんだよ。",romaji:"",idText:"Jeez, what're you up to?"}},{id:"vg-n5-01292",word:"もう一度",reading:"もういちど",romaji:"mouichido",meaning:"lagi / kembali",pos:"adverb",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"もう一度ゆっくりお話しください。",furigana:"もう一度ゆっくりお話しください。",romaji:"",idText:"Could you please repeat it slowly?"}},{id:"vg-n5-01293",word:"木曜日",reading:"もくようび",romaji:"mokuyoubi",meaning:"Kamis",pos:"adverb",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"やあ、フレッド。木曜日にバドミントンはどう。",furigana:"やあ、フレッド。木曜日にバドミントンはどう。",romaji:"",idText:"Hi, Fred, how about badminton on Thursday?"}},{id:"vg-n5-01295",word:"もっと",reading:"もっと",romaji:"motto",meaning:"lebih",pos:"adverb",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"父がもっと長生きしていたらなあ。",furigana:"父がもっと長生きしていたらなあ。",romaji:"",idText:"I wish my father had lived longer."}}],explanations:[{id:"exp-1",grammarId:"gn5-00021",title:"Pola: より (perbandingan)",formula:"N + より",meaning:"lebih dari / dibanding",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"より (perbandingan)",idText:"lebih dari / dibanding"}],examples:[{jp:"でんしゃはバスよりはやいです。",romaji:"",idText:"Kereta lebih cepat dari bus."},{jp:"きのうよりきょうのほうがさむいです。",romaji:"",idText:"Hari ini lebih dingin dari kemarin."}]},{id:"exp-2",grammarId:"gn5-00057",title:"Pola: AはBより〜",formula:"A + は + B + より + Adj/Adv",meaning:"A lebih ... daripada B",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"AはBより〜",idText:"A lebih ... daripada B"}],examples:[{jp:"でんしゃはバスよりはやいです。",romaji:"",idText:"Kereta lebih cepat dari bus."},{jp:"このかばんはあのかばんよりやすいです。",romaji:"",idText:"Tas ini lebih murah dari tas itu."}]},{id:"exp-3",grammarId:"gn5-00058",title:"Pola: 〜の方が〜より",formula:"A + の方が + B + より + Adj",meaning:"... lebih ... dibandingkan ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜の方が〜より",idText:"... lebih ... dibandingkan ..."}],examples:[{jp:"バスよりでんしゃのほうがはやいです。",romaji:"",idText:"Kereta lebih cepat daripada bus."},{jp:"なつよりふゆのほうがすきです。",romaji:"",idText:"Lebih suka musim dingin daripada musim panas."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:"Langkah 1 (Konsep Kata): Pilihlah kata tanya perbandingan 2 pilihan.",sentencePrompt:"Kata tanya untuk membandingkan 2 pilihan adalah:",options:["どちら (dochira)","どれ (dore)","だれ (dare)","どこ (doko)"],correctAnswer:"どちら (dochira)",explanation:'"どちら (dochira)" dipakai khusus untuk perbandingan DUA opsi. どれ untuk 3 opsi atau lebih.',diagnosticFeedback:{"どれ (dore)":"Salah: どれ hanya digunakan untuk 3 pilihan atau lebih.","だれ (dare)":"Salah: だれ menanyakan orang (siapa).","どこ (doko)":"Salah: どこ menanyakan lokasi (di mana)."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Isian Rumus Komparasi): Lengkapilah kalimat perbandingan bahwa kereta lebih cepat daripada bus.",sentencePrompt:"電車【でんしゃ】のほうが バス _____ 速【はや】いです。",options:["より","から","まで","と"],correctAnswer:"より",explanation:'Partikel pembanding "daripada" adalah より (yori): 電車のほうが バスより 速いです.',diagnosticFeedback:{から:'Salah: から berarti "dari" titik awal.',まで:'Salah: まで berarti "sampai" titik akhir.',と:'Salah: と berarti "dan/dengan".'}},{id:"drill-3",type:"reorder",instruction:"Langkah 3 (Susun Kalimat): Urutkan kalimat komparasi harga berikut.",sentencePrompt:"Susunan kalimat yang tepat:",options:["バスのほうが 電車【でんしゃ】より 安【やす】いです","電車【でんしゃ】より バスのほうが 安【やす】いです","安【やす】いです バスのほうが 電車【でんしゃ】より","バスのほうが より電車【よりでんしゃ】 安【やす】いです"],correctAnswer:"バスのほうが 電車【でんしゃ】より 安【やす】いです",explanation:"Objek pemenang (バスのほうが) + Objek pembanding (電車より) + Sifat (安いです).",diagnosticFeedback:{"電車【でんしゃ】より バスのほうが 安【やす】いです":"Secara gramatikal bisa dipahami tapi susunan standar meletakkan no hou ga di depan.","安【やす】いです バスのほうが 電車【でんしゃ】より":"Jebakan: Kata sifat di awal kalimat.","バスのほうが より電車【よりでんしゃ】 安【やす】いです":"Jebakan: Partikel より ditaruh di depan kata benda."},tokens:["バスのほうが","電車【でんしゃ】より","安【やす】いです"],correctOrder:["0","1","2"]},{id:"drill-4",type:"trap_detect",instruction:'Langkah 4 (Deteksi Jebakan): Manakah perbandingan yang menyatakan "kopi lebih enak dari teh"?',sentencePrompt:"Pilihlah kalimat yang benar:",options:["コーヒーのほうが お茶【ちゃ】より おいしいです。","お茶【ちゃ】のほうが コーヒーより おいしいです。","コーヒーより お茶【ちゃ】のほうが おいしいです。","コーヒーが お茶【ちゃ】より のほうがおいしいです。"],correctAnswer:"コーヒーのほうが お茶【ちゃ】より おいしいです。",explanation:"Pihak yang lebih enak (kopi) wajib ditempeli のほうが.",diagnosticFeedback:{"お茶【ちゃ】のほうが コーヒーより おいしいです。":"Jebakan terbalik: Artinya teh lebih enak dari kopi.","コーヒーより お茶【ちゃ】のほうが おいしいです。":"Jebakan terbalik: Artinya teh yang lebih enak.","コーヒーが お茶【ちゃ】より のほうがおいしいです。":"Jebakan: Tata bahasa berantakan."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Saat ditanya "電車と バスと どちらが 速いですか", jawaban yang tepat adalah:',sentencePrompt:"Pilihlah jawaban komparatif yang lengkap:",options:["電車【でんしゃ】のほうが 速【はや】いです。","はい、速【はや】いです。","どちらも だめです。","バスは さようなら。"],correctAnswer:"電車【でんしゃ】のほうが 速【はや】いです。",explanation:"Menjawab pertanyaan dochira dengan menyebutkan pilihan pemenang diikuti のほうが.",diagnosticFeedback:{"はい、速【はや】いです。":"Tidak menjawab pilihan perbandingan antara kereta atau bus.","どちらも だめです。":"Terlalu negatif tanpa memberikan informasi kecepatan.","バスは さようなら。":"Sayounara tidak nyambung dalam konteks ini."}}],can_do_challenge:{statement:"Bisa membandingkan harga atau kecepatan dua alat transportasi.",situation:"Memilih rute transportasi dinas bersama atasan.",promptTask:"Katakan bahwa kereta lebih cepat daripada bus, tapi bus lebih murah!",modelAnswer:"電車【でんしゃ】のほうが 速【はや】いですが、バスのほうが 安【やす】いです。",modelAnswerId:"Kereta lebih cepat, tetapi bus lebih murah.",culturalEtiquette:"Gunakan dochira saat bertanya dan no hou ga untuk pihak yang unggul.",skillUnlocked:["Menguasai struktur perbandingan komparatif A no hou ga B yori","Membedakan kata tanya dochira dan dore"]},pocket_summary:{keyFormula:"[A] のほうが [B] より [Sifat] です",coreWords:["どちら","のほうが","より","はやい"],coreWarning:'Pihak yang menang sifatnya selalu ditempeli "のほうが". Pertanyaan 2 opsi memakai "どちら".',quickDialogue:"A: どちらが 速いですか。 → B: 電車のほうが 速いです。"}},"les-n5-u09-02":{pedagogical_framework:{what:{summary:"Pola superlatif [Kelompok] のなかで [Kata Tanya] が いちばん [Sifat] ですか, dan menyatakan yang paling unggul dengan 一番 (ichiban).",canDo:"Bisa menyatakan musim yang paling disukai, makanan paling lezat, atau kota terindah di Jepang.",targetPatterns:["[Kelompok] のなかで [Kata Tanya] が いちばん [Sifat] ですか","[Opsi] が いちばん [Sifat] です"],coreVocabSample:["いちばん","のなかで","きせつ","スポーツ","すき","すし"]},sensei_context:{sceneIntro:"Di ruang istirahat, Kenji dan Sakura mengobrol tentang 4 musim di Jepang dan menanyakan musim apa yang paling disukai Budi.",dailyMission:"Gunakan frasa のなかで untuk menetapkan ruang lingkup, dan いちばん untuk menyatakan derajat superlatif.",whyOrder:"Setelah membandingkan dua opsi (Lesson 1), sekarang kita membandingkan dalam kelompok jamak untuk mencari yang nomor 1!"},cultural_notes:{title:"Kepekaan Terhadap 4 Musim di Jepang (四季 - Shiki)",etiquette:"Orang Jepang sangat mencintai perubahan musim (musim semi sakura, musim gugur momiji). Membicarakan musim favorit adalah topik obrolan ramah yang sangat disukai.",taboos:"Kata tanya disesuaikan dengan jenis kelompoknya: benda memakai 何 (nani), waktu memakai いつ (itsu), tempat memakai どこ (doko), orang memakai だれ (dare)."},pronunciation_tips:{title:"Pelafalan Kata 一番 (Ichiban)",moraNote:"Kata 一番 (i-chi-ba-n) memiliki 4 mora dengan mora nasal n di akhir.",soundTip:'Katakan "haru ga ichiban suki desu" dengan nada hangat ceria.'},common_pitfalls:[{title:"Salah Memilih Kata Tanya pada Pola Superlatif",caseScenario:'Menggunakan "doko" padahal kelompoknya adalah musim.',pitfallWarning:'"きせつ の なかで どこ が いちばん すきですか。" (Salah)',rightSolution:'"きせつ の なかで いつ が いちばん すきですか。" (Benar - Waktu)',explanation:"Musim adalah kategori waktu, wajib memakai いつ (itsu), bukan どこ (doko)."},{title:'Menggunakan "Yori" pada Kalimat Superlatif',caseScenario:"Mencampuradukkan yori ke dalam kalimat ichiban.",pitfallWarning:'"ぜんぶ より すし が いちばん です。" (Rancu)',rightSolution:'"日本料理【にほんりょうり】のなかで 寿司【すし】が いちばん 好【す】きです。" (Baku)',explanation:'Superlatif ruang lingkup memakai "のなかで", bukan "yori".'}],who_and_when:{situational_context:"Mengobrol santai perkenalan minat, diskusi kuliner favorit, obrolan cuaca.",social_relations:"Sangat lazim dan ramah di antara rekan kerja atau kenalan baru.",when_not_to_use:"Hindari memakai bahasa terlalu kaku saat mengobrol tentang makanan favorit."},scenario:{title:"Mendiskusikan Musim dan Makanan Favorit di Jepang",setting:"Ruang istirahat staf, waktu santai sore, pukul 17.00",narrative:"Kenji dan Sakura menanyakan pengalaman Budi merasakan musim di Jepang dan apa yang paling ia sukai."}},dialogue:[{id:"d1",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"ブディ、日本【にほん】の 季節【きせつ】のなかで いつが いちばん 好【す】き？",furigana:"ブディ、日本の 季節のなかで いつが いちばん 好き？",romaji:"Budi, Nihon no kisetsu no naka de itsu ga ichiban suki?",idText:"Budi, di antara musim-musim di Jepang, kapan yang paling kamu sukai?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"私【わたし】は 春【はる】が いちばん 好【す】きです。桜【さくら】が とても きれいですから。",furigana:"私は 春が いちばん 好きです。桜が とても きれいですから。",romaji:"Watashi wa haru ga ichiban suki desu. Sakura ga totemo kirei desu kara.",idText:"Saya paling suka musim semi. Karena bunga sakuranya sangat cantik."},{id:"d3",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"春【はる】は 暖【あたた】かくて いいですよね。日本料理【にほんりょうり】では 何【なに】が いちばん 好【す】きですか。",furigana:"春は 暖かくて いいですよね。日本料理では 何が いちばん 好きですか。",romaji:"Haru wa atatakakute ii desu yo ne. Nihon ryouri de wa nani ga ichiban suki desu ka.",idText:"Musim semi hangat dan menyenangkan ya. Kalau masakan Jepang apa yang paling kamu suka?"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"料理【りょうり】のなかで 寿司【すし】が いちばん 好【す】きです。サーモンが 大好【だいす】きです。",furigana:"料理のなかで 寿司が いちばん 好きです。サーモンが 大好きです。",romaji:"Ryouri no naka de sushi ga ichiban suki desu. Sa-mon ga daisuki desu.",idText:"Di antara semua masakan, saya paling suka sushi. Saya suka sekali salmon."},{id:"d5",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"スポーツのなかでは 何【なに】が いちばん 得意【とくい】？",furigana:"スポーツのなかでは 何が いちばん 得意？",romaji:"Supo-tsu no naka de wa nani ga ichiban tokui?",idText:"Di antara olahraga apa yang paling kamu kuasai?"},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"サッカーが いちばん 得意【とくい】です。高校【こうこう】の とき やっていました。",furigana:"サッカーが いちばん 得意です。高校の とき やっていました。",romaji:"Sakkaa ga ichiban tokui desu. Koukou no toki yatte imashita.",idText:"Saya paling bisa sepak bola. Waktu SMA saya sering main."},{id:"d7",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"今度【こんど】 会社【かいしゃ】の フットサル大会【たいかい】が ありますよ。ぜひ 出【で】てくださいね！",furigana:"今度 会社の フットサル大会が ありますよ。ぜひ 出てくださいね！",romaji:"Kondo kaisha no futtosaru taikai ga arimasu yo. Zehi dete kudasai ne!",idText:"Lain kali ada turnamen futsal kantor lho. Wajib ikut ya!"},{id:"d8",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい！全力【ぜんりょく】で 頑張【がんば】ります！",furigana:"はい！全力で 頑張ります！",romaji:"Hai! Zenryoku de gambarimasu!",idText:"Baik! Saya akan bersemangat sepenuh tenaga!"}],vocab_breakdown:[{id:"vg-n5-00875",word:"戸",reading:"と",romaji:"to",meaning:"pintu geser tradisional, pintu daun",pos:"noun",nuance:"Secara khusus mengacu pada daun pintu atau pintu geser khas rumah tradisional Jepang (seperti fusuma atau shouji, atau pintu luar kayu). Berbeda dengan ドア (doa) yang merujuk pada pintu berengsel gaya barat modern. Sering digunakan dalam frasa 戸を閉める (menutup pintu) atau 雨戸 (amado / daun pintu pelindung badai).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"外から冷たい風が入るので、戸をしっかり閉めてください。",furigana:"外から冷たい風が入るので、戸をしっかり閉めてください。",romaji:"",idText:"Karena angin dingin masuk dari luar, tolong tutup pintunya rapat-rapat."}},{id:"vg-n5-00885",word:"どっち",reading:"どっち",romaji:"dotchi",meaning:"yang mana (dari dua hal); arah mana (kasual)",pos:"noun",nuance:"Bentuk lisan santai/kasual dari どちら. Digunakan saat memilih antara dua opsi di antara teman akrab atau keluarga. Jangan dipakai kepada atasan atau orang baru dikenal.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"赤と青、どっちがいい？",furigana:"赤と青、どっちがいい？",romaji:"",idText:"Merah dan biru, menurutmu bagusan yang mana?"}},{id:"vg-n5-00888",word:"どの",reading:"どの",romaji:"dono",meaning:"yang mana (diikuti kata benda)",pos:"noun",nuance:"Kata penunjuk tanya (rentaishi) yang tidak bisa berdiri sendiri melainkan wajib langsung diikuti oleh kata benda, seperti どの本 (buku yang mana) atau どの部屋 (kamar yang mana). Berbeda dengan どれ yang dapat berdiri sendiri tanpa kata benda.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"どの傘があなたのですか。",furigana:"どの傘があなたのですか。",romaji:"",idText:"Payung yang mana yang merupakan milikmu?"}},{id:"vg-n5-00890",word:"どれ",reading:"どれ",romaji:"dore",meaning:"yang mana (di antara tiga atau lebih)",pos:"noun",nuance:"Pronomina tanya mandiri dalam seri これ, それ, あれ, どれ. Dipakai untuk menanyakan pilihan satu benda di antara tiga pilihan atau lebih. Jika hanya ada dua pilihan, gunakan どちら atau どっち.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"あなたのカバンはどれですか。",furigana:"あなたのカバンはどれですか。",romaji:"",idText:"Tas milikmu yang mana?"}},{id:"vg-n5-00891",word:"どんな",reading:"どんな",romaji:"donna",meaning:"seperti apa, macam apa, bagaimana",pos:"noun",nuance:"Digunakan sebelum kata benda (どんな＋名詞) untuk menanyakan sifat, karakteristik, atau tipe barang/orang yang dimaksud (contoh: どんな人 / orang seperti apa, どんな音楽 / musik macam apa).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"日本でどんなスポーツが人気ですか。",furigana:"日本でどんなスポーツが人気ですか。",romaji:"",idText:"Olahraga macam apa yang populer di Jepang?"}},{id:"vg-n5-00904",word:"ネクタイ",reading:"ネクタイ",romaji:"nekutai",meaning:"dasi",pos:"noun",nuance:"Kata serapan dari 'necktie'. Untuk kata kerja memakai dasi, digunakan partikel を dan kata kerja する (ネクタイをする) atau 締める (ネクタイをしめる).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"父の誕生日に青いネクタイをあげました。",furigana:"父の誕生日に青いネクタイをあげました。",romaji:"",idText:"Saya memberi hadiah dasi biru pada hari ulang tahun ayah."}},{id:"vg-n5-00934",word:"服",reading:"ふく",romaji:"fuku",meaning:"pakaian, baju",pos:"noun",nuance:"Istilah umum untuk pakaian gaya barat sehari-hari. Berbeda dengan pakaian tradisional Jepang yang disebut '和服' (wafuku) atau '着物' (kimono). Kata kerja untuk mengenakan pakaian tubuh bagian atas adalah '着る' (kiru) dan untuk melepas pakaian adalah '脱ぐ' (nugu).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"デパートで新しい服を買いました。",furigana:"デパートで新しい服を買いました。",romaji:"",idText:"Saya membeli pakaian baru di toserba (department store)."}},{id:"vg-n5-01010",word:"雨",reading:"あめ",romaji:"ame",meaning:"hujan",pos:"noun",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"木のおかげで雨にぬれずにすんだ。",furigana:"木のおかげで雨にぬれずにすんだ。",romaji:"",idText:"Pohon-pohon itu melindungi saya dari air hujan."}},{id:"vg-n5-01030",word:"上",reading:"うえ",romaji:"ue",meaning:"di atas",pos:"noun",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"テーブルの上にリンゴがあります。",furigana:"テーブルの上にリンゴがあります。",romaji:"",idText:"Ada an apple on the table."}},{id:"vg-n5-01068",word:"かぎ",reading:"かぎ",romaji:"kagi",meaning:"kunci",pos:"noun",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"車のカギをなくしちゃった。",furigana:"車のカギをなくしちゃった。",romaji:"",idText:"I've lost my car key."}}],explanations:[{id:"exp-1",grammarId:"gn5-00059",title:"Pola: AはBほど〜ない",formula:"A + は + B + ほど + Adj/Adv + ない",meaning:"A tidak se... B",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"AはBほど〜ない",idText:"A tidak se... B"}],examples:[{jp:"きょうはきのうほどさむくないです。",romaji:"",idText:"Hari ini tidak sedingin kemarin."},{jp:"このしけんはまえのしけんほどむずかしくなかった。",romaji:"",idText:"Ujian ini tidak sesulit ujian yang lalu."}]},{id:"exp-2",grammarId:"gn5-00060",title:"Pola: 〜が一番",formula:"N + が + 一番 + Adj",meaning:"... paling ... / yang terbaik",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜が一番",idText:"... paling ... / yang terbaik"}],examples:[{jp:"くだものの中で、りんごが一番すきです。",romaji:"",idText:"Di antara buah-buahan, saya paling suka apel."},{jp:"このクラスで彼女が一番じょうずです。",romaji:"",idText:"Di kelas ini, dia yang paling pandai."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Kata): Pilihlah arti kata "いちばん (ichiban)".',sentencePrompt:'Kata "いちばん" dalam kalimat perbandingan berarti:',options:["Paling / Nomor satu","Sedikit demi sedikit","Kadang-kadang","Sama sekali tidak"],correctAnswer:"Paling / Nomor satu",explanation:'"いちばん (ichiban)" berarti paling / ter- / nomor satu (superlatif).',diagnosticFeedback:{"Sedikit demi sedikit":"Salah: Sedikit demi sedikit adalah だんだん (dandan).","Kadang-kadang":"Salah: Kadang-kadang adalah ときどき (tokidoki).","Sama sekali tidak":"Salah: Sama sekali tidak adalah ぜんぜん (zenzen)."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Isian Ruang Lingkup): Pilihlah partikel penanda ruang lingkup kelompok superlatif.",sentencePrompt:"１年【いちねん】_____ 春【はる】が いちばん 好【す】きです。",options:["のなかで","より","から","まで"],correctAnswer:"のなかで",explanation:'Ruang lingkup kelompok superlatif ditandai dengan "のなかで": 1年のなかで (di antara 1 tahun).',diagnosticFeedback:{より:"Salah: より digunakan untuk perbandingan 2 hal, bukan ruang lingkup kelompok.",から:"Salah: から menandai titik awal waktu/tempat.",まで:"Salah: まで menandai batas akhir."}},{id:"drill-3",type:"reorder",instruction:"Langkah 3 (Susun Kalimat): Urutkan kalimat superlatif berikut secara tepat.",sentencePrompt:"Susunan kalimat yang tepat:",options:["果物【くだもの】のなかで リンゴが いちばん 好【す】きです","リンゴが 果物【くだもの】のなかで 好【す】きです いちばん","いちばん 好【す】きです 果物【くだもの】のなかで リンゴが","果物【くだもの】より リンゴが いちばん 好【す】きです"],correctAnswer:"果物【くだもの】のなかで リンゴが いちばん 好【す】きです",explanation:"Ruang lingkup (果物のなかで) + Pilihan (リンゴが) + Superlatif (いちばん 好きです).",diagnosticFeedback:{"リンゴが 果物【くだもの】のなかで 好【す】きです いちばん":"Jebakan: Kata ichiban terlempar ke akhir.","いちばん 好【す】きです 果物【くだもの】のなかで リンゴが":"Jebakan: Predikat di depan kalimat.","果物【くだもの】より リンゴが いちばん 好【す】きです":"Jebakan: Salah memakai より untuk ruang lingkup."},tokens:["果物【くだもの】のなかで","リンゴが","いちばん","好【す】きです"],correctOrder:["0","1","2","3"]},{id:"drill-4",type:"trap_detect",instruction:"Langkah 4 (Deteksi Jebakan): Pilihlah kalimat tanya superlatif untuk kategori waktu (musim) yang benar.",sentencePrompt:"Manakah pertanyaan musim favorit yang tepat?",options:["季節【きせつ】のなかで いつが いちばん 好【す】きですか。","季節【きせつ】のなかで どこが いちばん 好【す】きですか。","季節【きせつ】のなかで だれが いちばん 好【す】きですか。","季節【きせつ】のなかで どれが いちばん 好【す】きですか。"],correctAnswer:"季節【きせつ】のなかで いつが いちばん 好【す】きですか。",explanation:"Musim adalah kategori waktu, sehingga kata tanya wajib memakai いつ (kapan).",diagnosticFeedback:{"季節【きせつ】のなかで どこが いちばん 好【す】きですか。":"Jebakan: どこ menanyakan tempat.","季節【きせつ】のなかで だれが いちばん 好【す】きですか。":"Jebakan: だれ menanyakan orang.","季節【きせつ】のなかで どれが いちばん 好【す】きですか。":"Kurang tepat: Kategori musim di waktu lebih lazim memakai いつ."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Saat ditanya "日本料理のなかで 何が いちばん 好きですか", jawaban superlatif yang tepat adalah:',sentencePrompt:"Pilihlah jawaban yang menyatakan makanan paling disukai:",options:["寿司【すし】が いちばん 好【す】きです。","はい、好【す】きです。","何【なに】も 食【た】べません。","どちらも 好【す】きです。"],correctAnswer:"寿司【すし】が いちばん 好【す】きです。",explanation:'Menyebutkan makanan spesifik diikuti "が いちばん 好きです".',diagnosticFeedback:{"はい、好【す】きです。":"Tidak menjawab makanan apa yang paling disukai.","何【なに】も 食【た】べません。":"Terlalu negatif dan tidak menjawab preferensi.","どちらも 好【す】きです。":"Dochira mo hanya untuk 2 pilihan, sedangkan di sini ditanya masakan secara umum."}}],can_do_challenge:{statement:"Bisa menyatakan musim paling disukai dan makanan favorit di Jepang.",situation:"Mengobrol santai seputar kuliner dan musim bersama rekan kantor.",promptTask:"Katakan bahwa di antara masakan Jepang, kamu paling suka sushi!",modelAnswer:"日本料理【にほんりょうり】のなかで 寿司【すし】が いちばん 好【す】きです。",modelAnswerId:"Di antara masakan Jepang, saya paling suka sushi.",culturalEtiquette:"Gunakan partikel が setelah benda favorit dan akhiri dengan いちばん 好きです.",skillUnlocked:["Menguasai pola kalimat superlatif no naka de ... ichiban","Menyesuaikan kata tanya sesuai kategori"]},pocket_summary:{keyFormula:"[Kelompok] のなかで [Subjek] が いちばん [Sifat] です",coreWords:["いちばん","のなかで","きせつ","すし"],coreWarning:"Gunakan kata tanya yang tepat (いつ untuk waktu, なに untuk benda, どこ untuk tempat).",quickDialogue:"A: いつが いちばん 好きですか。 → B: 春が いちばん 好きです。"}}},n={"les-n5-u10-01":{pedagogical_framework:{what:{summary:"Konjugasi verba bentuk-te (て形), perangkaian aksi berurutan [V1-te] [V2-te] [V3-masu], dan urutan kronologis pasti [V-te] から.",canDo:"Bisa mengurutkan langkah kerja harian dari awal persiapan hingga tuntas.",targetPatterns:["[Verba 1-te]、[Verba 2-te]、[Verba 3]","[Verba-te] から (setelah / baru kemudian)","[Verba-te] も (walaupun)"],coreVocabSample:["おきて","あさごはん","てをあらって","かいしゃへいって","しごとをします"]},sensei_context:{sceneIntro:"Di area pabrik dan bengkel kerja, SOP keselamatan menuntut urutan kerja teratur. Tanaka-senpai menjelaskan langkah persiapan shift kerja.",dailyMission:"Mampu menghubungkan 2–3 tindakan menggunakan bentuk-te dan menegaskan urutan syarat dengan 〜てから.",whyOrder:'Proses perubahan bentuk-te adalah "jantung" morfologi bahasa Jepang. Menguasai bentuk-te membuka 30+ pola tata bahasa tingkat lanjut!'},cultural_notes:{title:"Konsep Urutan Kerja Standar (SOP & 5S) di Pabrik Jepang",etiquette:'Langkah kerja tidak boleh dilompati. "Te o aratte kara" (setelah cuci tangan baru masuk ruang steril) adalah disiplin mutlak.',taboos:'Jangan menggunakan kata sambung "soshite" berulang-ulang di setiap kalimat. Gunakan bentuk-te untuk merangkai aksi secara alami!'},pronunciation_tips:{title:"Irama Perubahan Bentuk-Te Golongan 1",moraNote:"Lagu hafalan bentuk-te: i-chi-ri -> tte, mi-bi-ni -> nde, ki -> ite, gi -> ide, shi -> shite.",soundTip:'Konsonan rangkap (sokuon) pada "tatte", "katte", "matte" harus ditahan 1 mora hening sebelum bunyi te.'},common_pitfalls:[{title:'Memakai "Soshite" Berulang Kali Seperti Bahasa Indonesia',caseScenario:'Mengatakan: "Bangun, lalu makan, lalu cuci muka, lalu pergi".',pitfallWarning:'"おきます、そして たべます、そして いきます。" (Kaku & Janggal)',rightSolution:'"おきて、ごはんを たべて、会社【かいしゃ】へ 行【い】きます。" (Alami & Runtut)',explanation:"Bentuk-te berfungsi sebagai kata hubung internal yang jauh lebih luwes dibanding soshite."},{title:"Salah Menentukan Tenses pada Bentuk-Te",caseScenario:"Mencoba mengubah bentuk-te menjadi bentuk lampau di tengah kalimat.",pitfallWarning:'"おきた、ごはんを たべました。" (Salah)',rightSolution:'"おきて、ごはんを たべました。" (Benar)',explanation:"Kala waktu (lampau/bukan lampau) HANYA ditentukan oleh kata kerja penutup di paling akhir kalimat."}],who_and_when:{situational_context:"Menjelaskan rutinitas kerja harian, menceritakan kegiatan akhir pekan, membacakan SOP.",social_relations:"Sangat lazim dan esensial dalam komunikasi kerja operasional sehari-hari.",when_not_to_use:"Jangan memakai bentuk-te menggantung tanpa verba penutup saat berbicara formal."},scenario:{title:"Penjelasan Standar Operasional Pagi di Bengkel",setting:"Area loker dan wastafel pabrik, pukul 08.30",narrative:"Tanaka-senpai menginstruksikan rangkaian persiapan keselamatan kerja sebelum mesin dihidupkan."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"ブディさん、作業【さぎょう】の 前【まえ】の 手順【てじゅん】を 覚【おぼ】えていますか。",furigana:"ブディさん、作業の 前の 手順を 覚えていますか。",romaji:"Budi-san, sagyou no mae no tejun o oboete imasu ka.",idText:"Budi-san, apakah ingat langkah-langkah sebelum mulai kerja?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい！まず 作業服【さぎょうふく】を 着【き】て、手【て】を 洗【あら】います。",furigana:"はい！まず 作業服を 着て、手を 洗います。",romaji:"Hai! Mazu sagyoufuku o kite, te o araimasu.",idText:"Iya! Pertama memakai pakaian kerja, lalu mencuci tangan."},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"その あとは どうしますか。",furigana:"その あとは どうしますか。",romaji:"Sono ato wa dou shimasu ka.",idText:"Setelah itu bagaimana?"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"手【て】を 洗【あら】ってから、安全靴【あんぜんぐつ】を 履【は】いて、朝礼【ちょうれい】へ 行【い】きます。",furigana:"手を 洗ってから、安全靴を 履いて、朝礼へ 行きます。",romaji:"Te o aratte kara, anzengutsu o haite, chourei e ikimasu.",idText:"Setelah mencuci tangan, baru memakai sepatu keselamatan, lalu pergi ke apel pagi."},{id:"d5",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"素晴【すば】らしいですね！準備【じゅんび】が しっかり できています。",furigana:"素晴らしいですね！準備が しっかり できています。",romaji:"Subarashii desu ne! Junbi ga shikkari dekite imasu.",idText:"Luar biasa ya! Persiapannya sudah mantap terlaksana."},{id:"d6",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"安全第一【あんぜんだいいち】ですから、手順【てじゅん】を 守【まも】ってくださいね。",furigana:"安全第一ですから、手順を 守ってくださいね。",romaji:"Anzen daiichi desu kara, tejun o mamotte kudasai ne.",idText:"Karena keselamatan adalah nomor satu, patuhi urutan prosedurnya ya."},{id:"d7",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、毎日【まいにち】確認【かくにん】して 作業【さぎょう】を 始【はじ】めます！",furigana:"はい、毎日確認して 作業を 始めます！",romaji:"Hai, mainichi kakunin shite sagyou o hajimemasu!",idText:"Baik, setiap hari saya periksa dulu baru memulai pekerjaan!"},{id:"d8",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"よし、今日も 怪我【けが】のないように 頑張【がんば】ろう！",furigana:"よし、今日も 怪我のないように 頑張ろう！",romaji:"Yoshi, kyou mo kega no nai you ni gambarou!",idText:"Bagus, hari ini mari kita semangat tanpa ada cedera ya!"}],vocab_breakdown:[{id:"vg-n5-00006",word:"洗う",reading:"あらう",romaji:"arau",meaning:"mencuci",pos:"verb-u",nuance:"Refers specifically to washing with water or a liquid. Not used for 'washing' a car using a rag without water, for example.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"手を洗ってください。",furigana:"手を洗ってください。",romaji:"",idText:"Tolong cuci tangan."}},{id:"vg-n5-00010",word:"来る",reading:"くる",romaji:"kuru",meaning:"datang",pos:"verb-kuru",nuance:"Irregular verb. Keigo: いらっしゃる (sonkei), 参る (kenjo).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"友達が来ました。",furigana:"友達が来ました。",romaji:"",idText:"Teman datang."}},{id:"vg-n5-00017",word:"つける",reading:"つける",romaji:"tsukeru",meaning:"menyalakan; menempelkan",pos:"verb-ru",nuance:"話す = berbicara (transitif). 話す vs 言う: 話す = berdialog, 言う = menyatakan.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"エアコンをつけてください。",furigana:"エアコンをつけてください。",romaji:"",idText:"Tolong nyalakan AC."}},{id:"vg-n5-00029",word:"入る",reading:"はいる",romaji:"hairu",meaning:"masuk",pos:"verb-u",nuance:"Godan meski berakhiran る.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"部屋に入りました。",furigana:"部屋に入りました。",romaji:"",idText:"Saya masuk ke kamar."}},{id:"vg-n5-00032",word:"見る",reading:"みる",romaji:"miru",meaning:"melihat; menonton",pos:"verb-ru",nuance:"Keigo: ご覧になる (sonkei), 拝見する (kenjo).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"映画を見ました。",furigana:"映画を見ました。",romaji:"",idText:"Saya menonton film."}},{id:"vg-n5-00043",word:"歌う",reading:"うたう",romaji:"utau",meaning:"bernyanyi",pos:"verb-u",nuance:"くれる = memberi (ke saya/pihak saya). Berbeda dari あげる: perspektif penerima.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"カラオケで歌いました。",furigana:"カラオケで歌いました。",romaji:"",idText:"Saya bernyanyi di karaoke."}},{id:"vg-n5-00047",word:"始まる",reading:"はじまる",romaji:"hajimaru",meaning:"dimulai",pos:"verb-u",nuance:"Intransitif. Transitif: 始める.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"映画が始まりました。",furigana:"映画が始まりました。",romaji:"",idText:"Filmnya mulai."}},{id:"vg-n5-00050",word:"もらう",reading:"もらう",romaji:"morau",meaning:"menerima (dari orang lain)",pos:"verb-u",nuance:"Keigo: いただく (kenjo). Berlawanan perspektif dengan あげる/くれる.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"プレゼントをもらいました。",furigana:"プレゼントをもらいました。",romaji:"",idText:"Saya menerima hadiah."}},{id:"vg-n5-00055",word:"見せる",reading:"みせる",romaji:"miseru",meaning:"memperlihatkan",pos:"verb-ru",nuance:'知る = tahu/mengetahui. Perhatian: 知っています (bukan 知ります) untuk state "sedang tahu".',particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"パスポートを見せてください。",furigana:"パスポートを見せてください。",romaji:"",idText:"Tolong tunjukkan paspornya."}},{id:"vg-n5-00056",word:"生まれる",reading:"うまれる",romaji:"umareru",meaning:"lahir",pos:"verb-ru",nuance:"思う = berpikir/merasa (opini). Lebih subjektif dari 考える (kangaeru) = memikirkan secara aktif.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"東京で生まれました。",furigana:"東京で生まれました。",romaji:"",idText:"Saya lahir di Tokyo."}}],explanations:[{id:"exp-1",grammarId:"gn5-00094",title:"Pola: V-て、V-て、〜 (urutan kegiatan)",formula:"V1-て + V2-て + ... + V(kalimat akhir)",meaning:"melakukan V1, lalu V2, lalu ... (menyatakan urutan tindakan berurutan)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"V-て、V-て、〜 (urutan kegiatan)",idText:"melakukan V1, lalu V2, lalu ... (menyatakan urutan tindakan berurutan)"}],examples:[{jp:"起きて、シャワーを浴びて、朝ごはんを食べました。",romaji:"",idText:"Bangun, mandi, lalu makan sarapan."},{jp:"京都に行って、お寺を見て、おいしいものを食べました。",romaji:"",idText:"Pergi ke Kyoto, melihat kuil, dan makan makanan enak."},{jp:"宿題をして、ゲームをします。",romaji:"",idText:"Kerjakan PR dulu, baru main game."}]},{id:"exp-2",grammarId:"gn5-00033",title:"Pola: 〜てから",formula:"Vて + から + V2",meaning:"setelah melakukan ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜てから",idText:"setelah melakukan ..."}],examples:[{jp:"てをあらってからたべます。",romaji:"",idText:"Cuci tangan dulu baru makan."},{jp:"しゅくだいをしてから、あそびましょう。",romaji:"",idText:"Setelah PR selesai, mari bermain."}]},{id:"exp-3",grammarId:"gn5-00081",title:"Pola: V-方",formula:"V(ます-stem) + 方",meaning:"cara melakukan V",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"V-方",idText:"cara melakukan V"}],examples:[{jp:"この漢字の読み方を教えてください。",romaji:"",idText:"Tolong ajari saya cara membaca kanji ini."},{jp:"パスタの作り方を知っていますか？",romaji:"",idText:"Apakah kamu tahu cara membuat pasta?"},{jp:"ごみの捨て方がわかりません。",romaji:"",idText:"Saya tidak tahu cara membuang sampah."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Kata): Pilihlah arti kata "手順 (てじゅん)".',sentencePrompt:'Kata "手順" dalam konteks kerja berarti:',options:["Langkah / Prosedur kerja","Upah lembur","Jam istirahat","Surat izin sakit"],correctAnswer:"Langkah / Prosedur kerja",explanation:'"手順 (てじゅん)" berarti langkah atau prosedur operasional.',diagnosticFeedback:{"Upah lembur":"Salah: Upah lembur adalah 残業手当 (zangyou teate).","Jam istirahat":"Salah: Jam istirahat adalah 休憩時間 (kyuukei jikan).","Surat izin sakit":"Salah: Surat izin adalah 診断書 (shindansho)."}},{id:"drill-2",type:"cloze",instruction:'Langkah 2 (Isian Urutan Waktu): Pilihlah pola yang bermakna "setelah mencuci tangan, baru kemudian...".',sentencePrompt:"手【て】を 洗【あら】っ _____、部屋【へや】へ 入【はい】ります。",options:["てから","てまで","てより","てまえに"],correctAnswer:"てから",explanation:"[Verba-te] + から menyatakan bahwa aksi kedua baru dilakukan setelah aksi pertama tuntas.",diagnosticFeedback:{てまで:"Salah: Tidak ada kombinasi gramatikal te-made.",てより:"Salah: より tidak menempel pada bentuk-te.",てまえに:"Salah: まえに didahului bentuk kamus (arau mae ni), bukan bentuk-te."}},{id:"drill-3",type:"reorder",instruction:"Langkah 3 (Susun Kalimat): Urutkan rangkaian aksi pagi berikut secara kronologis.",sentencePrompt:"Susunan kalimat berurutan yang tepat:",options:["起【お】きて、ごはんを 食【た】べて、会社【かいしゃ】へ 行【い】きます","会社【かいしゃ】へ 行【い】きます 起【お】きて、ごはんを 食【た】べて","起【お】きます、ごはんを 食【た】べて、会社【かいしゃ】へ 行【い】きて","起【お】きて、ごはんを 食【た】べます、会社【かいしゃ】へ 行【い】きます"],correctAnswer:"起【お】きて、ごはんを 食【た】べて、会社【かいしゃ】へ 行【い】きます",explanation:"Aksi 1 (起きて) + Aksi 2 (食べて) + Aksi Penutup (行きます).",diagnosticFeedback:{"会社【かいしゃ】へ 行【い】きます 起【お】きて、ごはんを 食【た】べて":"Jebakan: Aksi terakhir ditaruh di awal.","起【お】きます、ごはんを 食【た】べて、会社【かいしゃ】へ 行【い】きて":"Jebakan: Kalimat berakhir menggantung dengan bentuk-te.","起【お】きて、ごはんを 食【た】べます、会社【かいしゃ】へ 行【い】きます":"Jebakan: Menggunakan masu di tengah rangkaian."},tokens:["起【お】きて、ごはんを","食【た】べて、会社【かいしゃ】へ","行【い】きます"],correctOrder:["0","1","2"]},{id:"drill-4",type:"trap_detect",instruction:"Langkah 4 (Deteksi Jebakan): Pilihlah konjugasi bentuk-te dari kata kerja 書きます (kakimasu) yang benar.",sentencePrompt:'Bentuk-te yang benar dari "書きます" adalah:',options:["書【か】いて","書【か】って","書【か】んで","書【か】して"],correctAnswer:"書【か】いて",explanation:"Verba golongan 1 berakhiran ki berubah menjadi ite: kakimasu -> kaite.",diagnosticFeedback:{"書【か】って":"Jebakan: Akhiran tte adalah untuk verba i, chi, ri.","書【か】んで":"Jebakan: Akhiran nde adalah untuk verba mi, bi, ni.","書【か】して":"Jebakan: Akhiran shite adalah untuk verba shi."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Saat supervisor menegaskan "手順を守ってくださいね", tanggapan kepatuhan yang tepat adalah:',sentencePrompt:"Pilihlah respon komitmen prosedur:",options:["はい、しっかり 確認【かくにん】して 作業【さぎょう】を 始【はじ】めます。","いいえ、忘【わす】れます。","手順【てじゅん】は ありません。","さようなら、明日【あした】やります。"],correctAnswer:"はい、しっかり 確認【かくにん】して 作業【さぎょう】を 始【はじ】めます。",explanation:"Menyatakan komitmen memeriksa prosedur sebelum mulai kerja.",diagnosticFeedback:{"いいえ、忘【わす】れます。":"Sangat tidak bertanggung jawab mengaku akan melupakan SOP.","手順【てじゅん】は ありません。":"Membantah keberadaan SOP supervisor.","さようなら、明日【あした】やります。":"Menolak instruksi kerja saat itu juga."}}],can_do_challenge:{statement:"Bisa mengurutkan langkah kerja harian dari awal persiapan hingga selesai.",situation:"Menjelaskan rutinitas persiapan kerja kepada instruktur magang.",promptTask:"Katakan bahwa kamu berganti pakaian kerja, lalu mencuci tangan, lalu pergi ke pabrik!",modelAnswer:"作業服【さぎょうふく】に 着替【きが】えて、手【て】を 洗【あら】ってから 工場【こうじょう】へ 行【い】きます。",modelAnswerId:"Setelah berganti ke pakaian kerja dan mencuci tangan, saya baru pergi ke pabrik.",culturalEtiquette:"Rangkai dengan bentuk-te dan gunakan 〜てから untuk urutan prasyarat.",skillUnlocked:["Menguasai konjugasi verba bentuk-te","Mampu merangkai aksi kronologis dengan 〜てから"]},pocket_summary:{keyFormula:"[V1-te]、[V2-te]、[V3-masu] / [V-te] から",coreWords:["おきて","あらって","いって","しごと"],coreWarning:"Tenses lampau/sekarang hanya ditentukan oleh kata kerja terakhir di ujung kalimat.",quickDialogue:"A: 何を しますか。 → B: 手を 洗ってから 食べます。"}},"les-n5-u10-02":{pedagogical_framework:{what:{summary:"Permintaan tolong santun 〜てください, mencoba melakukan 〜てみる, ketidaksengajaan/penyesalan 〜てしまう, dan persiapan awal 〜ておく.",canDo:"Bisa meminta tolong secara sopan kepada rekan kerja, mencoba memakai alat baru, dan menyiapkan dokumen kerja terlebih dahulu.",targetPatterns:["[Verba-te] ください","[Verba-te] みます (mencoba)","[Verba-te] しまいました (terlanjur/menyesal)","[Verba-te] おきます (persiapan)"],coreVocabSample:["みてください","やってみます","わすれてしまいました","じゅんびしておきます"]},sensei_context:{sceneIntro:"Budi sedang belajar mengoperasikan mesin fotokopi baru di kantor. Sakura memandu langkah-langkahnya dan Budi mencoba sendiri.",dailyMission:"Minta bantuan dengan 〜てください, ungkapkan tekad mencoba dengan 〜てみます, dan laporkan persiapan dengan 〜ておきます.",whyOrder:"Bentuk-te adalah pintu masuk menuju aksi fungsional: memohon tolong, mencoba hal baru, dan mitigasi kekhilafan."},cultural_notes:{title:"Etika Meminta Bantuan (依頼 - Irai) di Lingkungan Kerja",etiquette:'Sebelum meminta tolong dengan 〜てください, dahului selalu dengan kata maaf "Sumimasen ga..." untuk melunakkan beban permintaan.',taboos:"Jangan gunakan 〜てください murni kepada atasan untuk instruksi kerja; gunakan bentuk permohonan yang lebih santun seperti 〜ていただけますか."},pronunciation_tips:{title:"Intonasi Permintaan Lembut",moraNote:'Pada frasa "mite kudasai", nada sedikit turun lembut di akhir kalimat.',soundTip:'Katakan "chotto matte kudasai" dengan jeda hening mora sokuon pada "matte".'},common_pitfalls:[{title:'Memakai "Kudasai" Tanpa Didahului Bentuk-Te',caseScenario:'Menempelkan kudasai langsung ke bentuk kamus: "kaku kudasai".',pitfallWarning:'"かく ください。" (Salah Fatal)',rightSolution:'"かいて ください。" (Benar - Wajib Bentuk-Te)',explanation:"Permintaan tolong verba wajib berkonjugasi ke bentuk-te terlebih dahulu."},{title:"Salah Membedakan 〜てみる (Mencoba) vs 〜てしまう (Terlanjur)",caseScenario:"Tertukar antara mencoba melakukan sesuatu dengan melakukan karena khilaf.",pitfallWarning:'"たべて しまいました (Saya mencoba makan - Salah makna)"',rightSolution:'"たべて みました (Saya mencoba mencicipinya - Benar)"',explanation:"〜てみる adalah uji coba aksi baru, sedangkan 〜てしまう adalah ketuntasan atau penyesalan."}],who_and_when:{situational_context:"Meminta petunjuk alat kerja, mengabarkan dokumen yang sudah disiapkan, meminta maaf atas kekhilafan.",social_relations:"Sangat sering digunakan dalam komunikasi interaktif antarstaf di tempat kerja.",when_not_to_use:"Jangan pakai bentuk perintah te-kudasai saat melarang orang (gunakan te wa ikemasen)."},scenario:{title:"Mempelajari Mesin Pemindai Dokumen Baru",setting:"Sudut ruang arsip kantor, pukul 10.30",narrative:"Sakura menunjukkan cara memindai berkas ke email. Budi mencoba mempraktikkan tombol pengaturannya."}},dialogue:[{id:"d1",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"さくらさん、すみませんが、この スキャナーの 使【つか】い方【かた】を 教【おし】えてください。",furigana:"さくらさん、すみませんが、この スキャナーの 使い方を 教えてください。",romaji:"Sakura-san, sumimasen ga, kono sukyana- no tsukaikata o oshiete kudasai.",idText:"Sakura-san, mohon maaf, tolong ajari cara menggunakan pemindai (scanner) ini ya."},{id:"d2",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"いいですよ。まず 書類【しょるい】を ここに 置【お】いて、青【あお】い ボタンを 押【お】してください。",furigana:"いいですよ。まず 書類を ここに 置いて、青い ボタンを 押してください。",romaji:"Ii desu yo. Mazu shorui o koko ni oite, aoi botan o oshite kudasai.",idText:"Tentu. Pertama letakkan dokumen di sini, lalu tolong tekan tombol biru."},{id:"d3",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、やってみます！……あ、スキャンできました！",furigana:"はい、やってみます！……あ、スキャンできました！",romaji:"Hai, yatte mimasu! ...A, sukyan dekimashita!",idText:"Baik, saya coba lakukan ya! ...Wah, berhasil terpindai!"},{id:"d4",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"上手【じょうず】ですね！明日【あした】の 会議【かいぎ】の 資料【しりょう】を 準備【じゅんび】しておいてくださいね。",furigana:"上手ですね！明日の 会議の 資料を 準備しておいてくださいね。",romaji:"Jouzu desu ne! Ashita no kaigi no shiryou o junbi shite oite kudasai ne.",idText:"Pintar ya! Tolong siapkan dokumen rapat besok terlebih dahulu ya."},{id:"d5",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】しました。今日【きょう】の うちに コピーしておきます。",furigana:"承知しました。今日の うちに コピーしておきます。",romaji:"Shouchi shimashita. Kyou no uchi ni kopi- shite okimasu.",idText:"Saya pahami. Hari ini juga akan saya fotokopi terlebih dahulu."},{id:"d6",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"あれ？さっきの 鍵【かぎ】は？",furigana:"あれ？さっきの 鍵は？",romaji:"Are? Sakki no kagi wa?",idText:"Eh? Kunci yang tadi di mana?"},{id:"d7",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"あ、すみません！机【つくえ】の 上【うえ】に 置【お】き忘【わす】れてしまいました。すぐ 取【と】って 来【き】ます！",furigana:"あ、すみません！机の 上に 置き忘れてしまいました。すぐ 取って 来ます！",romaji:"A, sumimasen! Tsukue no ue ni okiwasurete shimaimashita. Sugu totte kimasu!",idText:"Ah, maaf! Ketinggalan di atas meja kerja. Segera saya ambilkan!"},{id:"d8",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"大丈夫【だいじょうぶ】だよ、焦【あせ】らないでね。",furigana:"大丈夫だよ、焦らないでね。",romaji:"Daijoubu da yo, aseranaide ne.",idText:"Nggak apa-apa kok, jangan terburu-buru ya."}],vocab_breakdown:[{id:"vg-n5-00197",word:"たつ",reading:"たつ",romaji:"tatsu",meaning:"berdiri",pos:"verb-u",nuance:"Means to physically stand up from a sitting or lying position. It's an action, not the state of standing.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"立ってください。",furigana:"立ってください。",romaji:"",idText:"Tolong berdiri."}},{id:"vg-n5-00199",word:"つかう",reading:"つかう",romaji:"tsukau",meaning:"menggunakan",pos:"verb-u",nuance:"A very general verb for using tools, time, money, or language. Cannot be used for 'using' a person in a polite context.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"スマホをよく使います。",furigana:"スマホをよく使います。",romaji:"",idText:"Saya sering menggunakan smartphone."}},{id:"vg-n5-00200",word:"つくる",reading:"つくる",romaji:"tsukuru",meaning:"membuat",pos:"verb-u",nuance:"Refers to creating or building something from raw materials, such as cooking food or building a table.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"料理を作ります。",furigana:"料理を作ります。",romaji:"",idText:"Saya membuat masakan."}},{id:"vg-n5-00224",word:"もつ",reading:"もつ",romaji:"motsu",meaning:"membawa; memegang",pos:"verb-u",nuance:"Means to hold or carry something in your hands. When expressing ownership or possessing something, the continuous form 持っている is used.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"荷物を持ちましょうか。",furigana:"荷物を持ちましょうか。",romaji:"",idText:"Boleh saya bawakan barangnya?"}},{id:"vg-n5-00358",word:"さんぽ",reading:"さんぽ",romaji:"sanpo",meaning:"jalan-jalan; berjalan santai",pos:"verb-suru",nuance:"Refers to taking a leisurely walk or stroll for pleasure or health, not just walking to get to a destination.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"犬と散歩しました。",furigana:"犬と散歩しました。",romaji:"",idText:"Saya jalan-jalan bersama anjing."}},{id:"vg-n5-00843",word:"掃除",reading:"そうじ",romaji:"souji",meaning:"pembersihan, membersihkan (bersih-bersih)",pos:"verb-suru",nuance:"Bisa berfungsi sebagai nomina (掃除 = pembersihan/kegiatan bersih-bersih) maupun kata kerja suru (掃除する = membersihkan). Merujuk pada membersihkan ruangan atau lingkungan dengan menyapu, mengepel, atau merapikan benda.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"毎朝自分の部屋をきれいに掃除します。",furigana:"毎朝自分の部屋をきれいに掃除します。",romaji:"",idText:"Setiap pagi saya membersihkan kamar saya sampai rapi dan bersih."}},{id:"vg-n5-01011",word:"洗う",reading:"あらう",romaji:"arau",meaning:"mencuci",pos:"verb-u",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"いつこの車は洗われましたか。",furigana:"いつこの車は洗われましたか。",romaji:"",idText:"Kapan mobil ini dicuci?"}},{id:"vg-n5-01065",word:"買う",reading:"かう",romaji:"kau",meaning:"membeli",pos:"verb-u",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"買うかどうかはあなたしだいです。",furigana:"買うかどうかはあなたしだいです。",romaji:"",idText:"It is up to you whether to buy it or not."}},{id:"vg-n5-01067",word:"かかる",reading:"かかる",romaji:"kakaru",meaning:"memakan waktu atau biaya",pos:"verb-u",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"どうしたらエンジンがかかりますか。",furigana:"どうしたらエンジンがかかりますか。",romaji:"",idText:"How can I start the engine?"}},{id:"vg-n5-01070",word:"かける",reading:"かける",romaji:"kakeru",meaning:"menelepon",pos:"verb-ru",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"１０円で電話がかけられますか。",furigana:"１０円で電話がかけられますか。",romaji:"",idText:"Can I make a phone call for ten yen?"}}],explanations:[{id:"exp-1",grammarId:"gn5-00030",title:"Pola: 〜てください",formula:"Vて + ください",meaning:"tolong ... / silakan ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜てください",idText:"tolong ... / silakan ..."}],examples:[{jp:"ここに名前をかいてください。",romaji:"",idText:"Tolong tulis nama di sini."},{jp:"すこしまってください。",romaji:"",idText:"Tolong tunggu sebentar."}]},{id:"exp-2",grammarId:"gn5-00036",title:"Pola: 〜てみる",formula:"Vて + みる",meaning:"mencoba melakukan ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜てみる",idText:"mencoba melakukan ..."}],examples:[{jp:"すしをたべてみました。",romaji:"",idText:"Mencoba makan sushi."},{jp:"このみちをあるいてみましょう。",romaji:"",idText:"Coba berjalan di jalan ini."}]},{id:"exp-3",grammarId:"gn5-00080",title:"Pola: 〜てしまう",formula:"Vて + しまう",meaning:"sudah ... (selesai/tidak sengaja)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜てしまう",idText:"sudah ... (selesai/tidak sengaja)"}],examples:[{jp:"しゅくだいをぜんぶやってしまいました。",romaji:"",idText:"PR sudah selesai dikerjakan semua."},{jp:"さいふをわすれてしまった！",romaji:"",idText:"Tidak sengaja lupa dompet!"}]},{id:"exp-4",grammarId:"gn5-00078",title:"Pola: Vる / Vない + ほうがいい",formula:"Vる (negatif) / Vた (positif) + ほうがいい",meaning:"lebih baik ... / sebaiknya ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"Vる / Vない + ほうがいい",idText:"lebih baik ... / sebaiknya ..."}],examples:[{jp:"はやくいったほうがいいよ。",romaji:"",idText:"Sebaiknya pergi lebih cepat."},{jp:"タバコはすわないほうがいいです。",romaji:"",idText:"Sebaiknya tidak merokok."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Kata): Pilihlah arti kata "資料 (しりょう)".',sentencePrompt:'Kata "資料" dalam administrasi kantor bermakna:',options:["Materi / Dokumen rapat","Slip gaji bulanan","Tiket pesawat","Kuitansi belanja"],correctAnswer:"Materi / Dokumen rapat",explanation:'"資料 (しりょう)" berarti berkas materi atau dokumen data informasi.',diagnosticFeedback:{"Slip gaji bulanan":"Salah: Slip gaji adalah 給与明細 (kyuuyo meisai).","Tiket pesawat":"Salah: Tiket pesawat adalah 航空券 (koukuuken).","Kuitansi belanja":"Salah: Kuitansi adalah 領収書 (ryoushuusho)."}},{id:"drill-2",type:"cloze",instruction:'Langkah 2 (Isian Permohonan Santun): Pilihlah bentuk permohonan "tolong ajarkan".',sentencePrompt:"すみませんが、日本語【にほんご】を _____ ください。",options:["教【おし】えて","教【おし】える","教【おし】えます","教【おし】えた"],correctAnswer:"教【おし】えて",explanation:"Pola permohonan santun [Verba-te] + ください: 教えてください (tolong ajarkan).",diagnosticFeedback:{"教【おし】える":"Salah: Bentuk kamus tidak bisa disambung ke kudasai.","教【おし】えます":"Salah: Bentuk masu salah untuk pola kudasai.","教【おし】えた":"Salah: Bentuk lampau ta tidak bisa disambung ke kudasai."}},{id:"drill-3",type:"reorder",instruction:"Langkah 3 (Susun Kalimat): Urutkan kalimat yang menyatakan mencoba hal baru berikut.",sentencePrompt:"Susunan kalimat yang tepat:",options:["私【わたし】が やってみます","やってみます 私【わたし】が","みます 私【わたし】が やって","私【わたし】が みますやって"],correctAnswer:"私【わたし】が やってみます",explanation:"Subjek (私が) + Verba uji coba (やってみます - saya akan coba lakukan).",diagnosticFeedback:{"やってみます 私【わたし】が":"Jebakan: Subjek ditaruh di akhir kalimat.","みます 私【わたし】が やって":"Jebakan: Pola te-miru terpecah berantakan.","私【わたし】が みますやって":"Jebakan: Susunan kata terbalik."},tokens:["私【わたし】が","やってみます"],correctOrder:["0","1"]},{id:"drill-4",type:"trap_detect",instruction:"Langkah 4 (Deteksi Jebakan): Manakah kalimat yang menyatakan tindakan persiapan sebelumnya?",sentencePrompt:"Pilihlah kalimat persiapan awal:",options:["明日【あした】の 会議【かいぎ】の 資料【しりょう】を コピーしておきます。","明日【あした】の 会議【かいぎ】の 資料【しりょう】を コピーしてしまいます。","明日【あした】の 会議【かいぎ】の 資料【しりょう】を コピーしてみます。","明日【あした】の 会議【かいぎ】の 資料【しりょう】を コピーしてください。"],correctAnswer:"明日【あした】の 会議【かいぎ】の 資料【しりょう】を コピーしておきます。",explanation:"Melakukan persiapan sebelum waktu tertentu memakai pola 〜ておく (コピーしておきます).",diagnosticFeedback:{"明日【あした】の 会議【かいぎ】の 資料【しりょう】を コピーしてしまいます。":"Jebakan: 〜てしまう berarti penyesalan atau ketuntasan tanpa sengaja.","明日【あした】の 会議【かいぎ】の 資料【しりょう】を コピーしてみます。":"Jebakan: 〜てみる berarti uji coba percobaan.","明日【あした】の 会議【かいぎ】の 資料【しりょう】を コピーしてください。":"Jebakan: Malah menyuruh orang lain yang memfotokopi."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Saat atasan meminta "ボタンを押してください", respon kesiapan yang tepat adalah:',sentencePrompt:"Pilihlah jawaban melaksanakan instruksi:",options:["はい、わかりました。すぐ やってみます！","いいえ、押【お】しません。","ボタンは ありません。","さようなら、押【お】しました。"],correctAnswer:"はい、わかりました。すぐ やってみます！",explanation:"Menyatakan pemahaman dan kesiapan mencoba menekan tombol.",diagnosticFeedback:{"いいえ、押【お】しません。":"Penolakan membangkang terhadap instruksi atasan.","ボタンは ありません。":"Berdalih tanpa memeriksa terlebih dahulu.","さようなら、押【お】しました。":"Sayounara tidak nyambung dalam respons instruksi."}}],can_do_challenge:{statement:"Bisa meminta rekan menunjukkan cara kerja dan menyiapkan dokumen terlebih dahulu.",situation:"Belajar memakai peralatan kantor bersama mentor.",promptTask:"Minta tolong diajari cara pakainya, lalu katakan kamu akan mencobanya!",modelAnswer:"すみませんが、使【つか】い方【かた】を 教【おし】えてください。私【わたし】が やってみます。",modelAnswerId:"Mohon maaf, tolong ajari cara menggunakannya. Saya akan coba lakukan.",culturalEtiquette:'Awali dengan "Sumimasen ga" sebelum mengutarakan permohonan.',skillUnlocked:["Menguasai permohonan santun te-kudasai","Membedakan te-miru (uji coba), te-oku (persiapan), te-shimau (penyesalan)"]},pocket_summary:{keyFormula:"[V-te] ください (tolong) / [V-te] みる (coba) / [V-te] おく (persiapan)",coreWords:["おしえて","やってみます","じゅんび","わすれました"],coreWarning:'Kudasai wajib didahului bentuk-te. "Te-oku" untuk persiapan, "te-shimau" untuk penyesalan.',quickDialogue:"A: やってみてください。 → B: はい、やってみます！"}}},e={"les-n5-u11-01":{pedagogical_framework:{what:{summary:"Meminta izin dengan 〜てもいいですか, memberi izin 〜てもいいです, dan larangan mutlak keselamatan kerja 〜てはいけません.",canDo:"Bisa meminta izin menggunakan peralatan kantor atau memotret, serta mematuhi rambu larangan kerja pabrik.",targetPatterns:["[Verba-te] も いいですか (bolehkah?)","[Verba-te] も いいです (boleh)","[Verba-te] は いけません (tidak boleh / dilarang)"],coreVocabSample:["しゃしん","とります","つかいます","はいります","きんえん","きけん"]},sensei_context:{sceneIntro:"Orientasi keselamatan kerja di pabrik manufaktur. Tanaka-senpai menjelaskan aturan ketat: boleh memakai helm, tetapi dilarang memotret area rahasia.",dailyMission:"Mampu meminta izin dengan 〜てもいいですか dan mengenali tanda larangan 〜てはいけません.",whyOrder:"Keselamatan kerja (K3) dan kepatuhan aturan di Jepang sangat ketat. Melanggar larangan bisa berakibat pemutusan kontrak kerja!"},cultural_notes:{title:"Kepatuhan Aturan & Hak Cipta/Kerahasiaan Pabrik Jepang (守秘義務)",etiquette:"Mengambil foto di area pabrik tanpa izin resmi adalah pelanggaran berat kerahasiaan industri.",taboos:'Partikel は pada pola 〜てはいけません dilafalkan "wa" (te wa ikemasen), BUKAN "ha"!'},pronunciation_tips:{title:'Pelafalan Partikel は pada "Te wa ikemasen"',moraNote:'Aksara は di sini bertindak sebagai partikel, wajib dibaca "wa".',soundTip:'Katakan "haitte wa ikemasen" dengan nada tegas peringatan.'},common_pitfalls:[{title:'Melafalkan "Te wa ikemasen" sebagai "Te ha ikemasen"',caseScenario:"Membaca tulisan romaji persis huruf aslinya.",pitfallWarning:'"はいって は (ha) いけません。" (Salah)',rightSolution:'"はいって は (wa) いけません。" (Benar)',explanation:'Sebagai partikel, は selalu dilafalkan "wa".'},{title:'Menjawab Izin dengan "Iie, dame desu" Secara Kasar',caseScenario:"Menolak permohonan izin orang lain dengan bahasa konfrontatif.",pitfallWarning:'"だめ です。" (Kasar)',rightSolution:'"すみません、ここは ちょっと……" atau "いけません。"',explanation:"Dalam budaya Jepang, penolakan izin dihaluskan dengan ungkapan gantung atau penjelasan sopan."}],who_and_when:{situational_context:"Pemeriksaan keamanan pabrik, meminta izin meminjam alat, memasuki ruang steril.",social_relations:"Sangat krusial dalam hubungan bawahan-atasan dan kepatuhan regulasi.",when_not_to_use:'Jangan memakai kata "dame" kepada atasan.'},scenario:{title:"Inspeksi Keselamatan dan Kerahasiaan Area Pabrik",setting:"Pintu gerbang area perakitan mesin presisi, pukul 09.00",narrative:"Budi bertanya apakah boleh memotret denah mesin untuk catatan belajar pribadi."}},dialogue:[{id:"d1",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"田中【たなか】さん、ここで 写真【しゃしん】を 撮【と】っても いいですか。",furigana:"田中さん、ここで 写真を 撮っても いいですか。",romaji:"Tanaka-san, koko de shashin o totte mo ii desu ka.",idText:"Tanaka-san, apakah di sini boleh mengambil foto?"},{id:"d2",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"いいえ、ここは 撮影禁止【さつえいきんし】ですから、撮【と】っては いけません。",furigana:"いいえ、ここは 撮影禁止ですから、撮っては いけません。",romaji:"Iie, koko wa satsuei kinshi desu kara, totte wa ikemasen.",idText:"Tidak, karena di sini dilarang memotret, tidak boleh mengambil foto."},{id:"d3",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"あ、大変【たいへん】失礼【しつれい】しました！メモを 書【か】いても いいですか。",furigana:"あ、大変失礼しました！メモを 書いても いいですか。",romaji:"A, taihen shitsurei shimashita! Memo o kaite mo ii desu ka.",idText:"Ah, mohon maaf sebesar-besarnya! Kalau mencatat memo apakah boleh?"},{id:"d4",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"ええ、ノートに メモを 書【か】くのは いいですよ。",furigana:"ええ、ノートに メモを 書くのは いいですよ。",romaji:"Ee, no-to ni memo o kaku no wa ii desu yo.",idText:"Ya, kalau mencatat memo di buku catatan boleh kok."},{id:"d5",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"ブディさん、ヘルメットは もう 準備【じゅんび】しましたか。",furigana:"ブディさん、ヘルメットは もう 準備しましたか。",romaji:"Budi-san, herumetto wa mou junbi shimashita ka.",idText:"Budi-san, apakah helm pengaman sudah disiapkan?"},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、被【かぶ】りました。この 手袋【てぶくろ】を 使【つか】っても いいですか。",furigana:"はい、被りました。この 手袋を 使っても いいですか。",romaji:"Hai, kaburimashita. Kono tebukuro o tsukatte mo ii desu ka.",idText:"Iya, sudah saya pakai. Apakah boleh memakai sarung tangan ini?"},{id:"d7",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"はい、その 安全手袋【あんぜんてぶくろ】を 使【つか】ってください。怪我【けが】を 防【ふせ】ぎます。",furigana:"はい、その 安全手袋を 使ってください。怪我を 防ぎます。",romaji:"Hai, sono anzen tebukuro o tsukatte kudasai. Kega o fusegimasu.",idText:"Ya, silakan gunakan sarung tangan pengaman itu. Mencegah terjadinya luka."},{id:"d8",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】しました。ルールを 守【まも】って 作業【さぎょう】します！",furigana:"承知しました。ルールを 守って 作業します！",romaji:"Shouchi shimashita. Ru-ru o mamotte sagyou shimasu!",idText:"Saya pahami. Saya akan mematuhi aturan dan bekerja!"}],vocab_breakdown:[{id:"vg-n5-00002",word:"開く",reading:"あく",romaji:"aku",meaning:"terbuka",pos:"verb-u",nuance:"Intransitif — benda yang terbuka sendiri. Beda dengan 開ける (transitif).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"ドアが開きました。",furigana:"ドアが開きました。",romaji:"",idText:"Pintunya terbuka."}},{id:"vg-n5-00003",word:"開ける",reading:"あける",romaji:"akeru",meaning:"membuka",pos:"verb-ru",nuance:"Transitif — seseorang membuka sesuatu.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"窓を開けてください。",furigana:"窓を開けてください。",romaji:"",idText:"Tolong buka jendelanya."}},{id:"vg-n5-00005",word:"遊ぶ",reading:"あそぶ",romaji:"asobu",meaning:"bermain, bersenang-senang",pos:"verb-u",nuance:"Bisa untuk anak-anak maupun dewasa. Juga berarti mengunjungi seseorang.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"公園で遊びました。",furigana:"公園で遊びました。",romaji:"",idText:"Saya bermain di taman."}},{id:"vg-n5-00013",word:"聞く",reading:"きく",romaji:"kiku",meaning:"mendengar; bertanya",pos:"verb-u",nuance:"Dua arti: mendengarkan (音楽を聞く) dan bertanya (先生に聞く).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"音楽を聞いています。",furigana:"音楽を聞いています。",romaji:"",idText:"Saya sedang mendengarkan musik."}},{id:"vg-n5-00028",word:"出る",reading:"でる",romaji:"deru",meaning:"keluar; muncul",pos:"verb-ru",nuance:"〜を出る: keluar dari tempat. 〜に出る: muncul di acara.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"学校を出ました。",furigana:"学校を出ました。",romaji:"",idText:"Saya keluar dari sekolah."}},{id:"vg-n5-00035",word:"起きる",reading:"おきる",romaji:"okiru",meaning:"bangun (tidur); terjadi",pos:"verb-ru",nuance:"乗る = naik (kendaraan). 電車に乗る. Lawan: 降りる (oriru) = turun.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"毎朝６時に起きます。",furigana:"毎朝６時に起きます。",romaji:"",idText:"Setiap pagi saya bangun jam 6."}},{id:"vg-n5-00039",word:"貸す",reading:"かす",romaji:"kasu",meaning:"meminjamkan",pos:"verb-u",nuance:"Lawan: 借りる (meminjam).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"傘を貸してください。",furigana:"傘を貸してください。",romaji:"",idText:"Tolong pinjamkan payung."}},{id:"vg-n5-00049",word:"送る",reading:"おくる",romaji:"okuru",meaning:"mengirim; mengantarkan",pos:"verb-u",nuance:"Can mean to send a thing or to see someone off. When used for people, it implies accompanying someone to their point of departure.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"メールを送りました。",furigana:"メールを送りました。",romaji:"",idText:"Saya mengirim email."}},{id:"vg-n5-00053",word:"いる",reading:"いる",romaji:"iru",meaning:"ada (makhluk hidup)",pos:"verb-ru",nuance:"Untuk orang dan hewan. Benda mati pakai ある. Keigo: いらっしゃる.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"猫が二匹います。",furigana:"猫が二匹います。",romaji:"",idText:"Ada dua ekor kucing."}},{id:"vg-n5-00111",word:"電話",reading:"でんわ",romaji:"denwa",meaning:"telepon",pos:"verb-suru",nuance:"電話する = menelepon. 電話をかける juga umum.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"後で電話します。",furigana:"後で電話します。",romaji:"",idText:"Nanti saya telepon."}}],explanations:[{id:"exp-1",grammarId:"gn5-00031",title:"Pola: 〜てもいい",formula:"Vて + もいいです / もいいですか",meaning:"boleh ... / tidak apa-apa",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜てもいい",idText:"boleh ... / tidak apa-apa"}],examples:[{jp:"ここにすわってもいいですか。",romaji:"",idText:"Boleh duduk di sini?"},{jp:"あしたきてもいいですよ。",romaji:"",idText:"Boleh datang besok."}]},{id:"exp-2",grammarId:"gn5-00032",title:"Pola: 〜てはいけない",formula:"Vて + はいけません / はいけない",meaning:"tidak boleh ... / dilarang ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜てはいけない",idText:"tidak boleh ... / dilarang ..."}],examples:[{jp:"ここでタバコをすってはいけません。",romaji:"",idText:"Dilarang merokok di sini."},{jp:"うそをついてはいけないよ。",romaji:"",idText:"Tidak boleh berbohong."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Rambu): Pilihlah arti kata rambu keselamatan "禁煙 (きんえん)".',sentencePrompt:'Rambu bertuliskan "禁煙" artinya adalah:',options:["Dilarang merokok","Dilarang masuk","Dilarang memotret","Dilarang berbicara"],correctAnswer:"Dilarang merokok",explanation:'"禁煙 (きんえん)" berarti dilarang merokok.',diagnosticFeedback:{"Dilarang masuk":"Salah: Dilarang masuk adalah 立入禁止 (tachiiri kinshi).","Dilarang memotret":"Salah: Dilarang memotret adalah 撮影禁止 (satsuei kinshi).","Dilarang berbicara":"Salah: Dilarang berbicara adalah 静粛に (seishuku ni)."}},{id:"drill-2",type:"cloze",instruction:'Langkah 2 (Isian Rumus Izin): Pilihlah pola untuk menyatakan "bolehkah saya masuk?".',sentencePrompt:"ここへ 入【はい】っ _____ いいですか。",options:["ても","ては","てから","てまで"],correctAnswer:"ても",explanation:"Pola permohonan izin adalah [Verba-te] + も いいですか.",diagnosticFeedback:{ては:"Salah: 〜てはいけません digunakan untuk kalimat larangan, bukan izin.",てから:"Salah: 〜てから berarti setelah.",てまで:"Salah: Tidak ada rumus te-made."}},{id:"drill-3",type:"reorder",instruction:"Langkah 3 (Susun Kalimat): Urutkan kalimat larangan memotret berikut secara tepat.",sentencePrompt:"Susunan kalimat yang tepat:",options:["ここで 写真【しゃしん】を 撮【と】っては いけません","写真【しゃしん】を ここで 撮【と】っては いけません","いけません ここで 写真【しゃしん】を 撮【と】っては","ここで 撮【と】っては 写真【しゃしん】を いけません"],correctAnswer:"ここで 写真【しゃしん】を 撮【と】っては いけません",explanation:"Keterangan tempat (ここで) + Objek (写真を) + Larangan (撮ってはいけません).",diagnosticFeedback:{"写真【しゃしん】を ここで 撮【と】っては いけません":"Kurang lazim: Keterangan tempat biasanya ditaruh di awal.","いけません ここで 写真【しゃしん】を 撮【と】っては":"Jebakan: Kata ikemasen di awal kalimat.","ここで 撮【と】っては 写真【しゃしん】を いけません":"Jebakan: Objek disisipkan di tengah pola larangan."},tokens:["ここで","写真【しゃしん】を","撮【と】っては","いけません"],correctOrder:["0","1","2","3"]},{id:"drill-4",type:"trap_detect",instruction:"Langkah 4 (Deteksi Jebakan): Manakah pelafalan dan penulisan partikel larangan yang benar?",sentencePrompt:"Pilihlah kalimat larangan yang baku:",options:["機械【きかい】に 触【さわ】っては いけません。","機械【きかい】に 触【さわ】ってわ いけません。","機械【きかい】に 触【さわ】っても いけません。","機械【きかい】に 触【さわ】ってを いけません。"],correctAnswer:"機械【きかい】に 触【さわ】っては いけません。",explanation:'Pola larangan ditulis 〜てはいけません (aksara は bertindak sebagai partikel, dibaca "wa").',diagnosticFeedback:{"機械【きかい】に 触【さわ】ってわ いけません。":'Jebakan Ejaan: Walau dibaca "wa", aksara aslinya wajib ditulis "は".',"機械【きかい】に 触【さわ】っても いけません。":"Jebakan: 〜ても dipakai untuk izin (te mo ii), bukan larangan.","機械【きかい】に 触【さわ】ってを いけません。":"Jebakan: Menggunakan partikel を yang keliru."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Saat supervisor menegaskan "ここで写真を撮ってはいけません", tanggapan kepatuhan yang santun adalah:',sentencePrompt:"Pilihlah respon meminta maaf dan mematuhi aturan:",options:["あ、大変【たいへん】失礼【しつれい】しました。撮【と】りません。","いいえ、撮【と】りたいです。","だめですか、なぜですか。","写真【しゃしん】は さようなら。"],correctAnswer:"あ、大変【たいへん】失礼【しつれい】しました。撮【と】りません。",explanation:"Meminta maaf atas kekhilafan (Taihen shitsurei shimashita) dan menegaskan tidak akan memotret.",diagnosticFeedback:{"いいえ、撮【と】りたいです。":"Membantah atasan secara arogan.","だめですか、なぜですか。":"Menantang aturan pabrik secara tidak sopan.","写真【しゃしん】は さようなら。":"Sayounara tidak nyambung dalam konteks ini."}}],can_do_challenge:{statement:"Bisa meminta izin menggunakan peralatan kantor dan mematuhi larangan pabrik.",situation:"Meminta izin menggunakan alat di area produksi pabrik.",promptTask:"Minta izin apakah boleh memakai alat ini, lalu taati larangan jika dilarang!",modelAnswer:"この 道具【どうぐ】を 使【つか】っても いいですか。……はい、わかりました。触【さわ】りません。",modelAnswerId:"Apakah boleh memakai alat ini? ...Baik, saya paham. Saya tidak akan menyentuhnya.",culturalEtiquette:"Gunakan [Verba-te] + もいいですか dan patuhi larangan tanpa mendebat.",skillUnlocked:["Menguasai permohonan izin te-mo ii desu ka","Memahami rambu dan pola larangan mutlak te-wa ikemasen"]},pocket_summary:{keyFormula:"[V-te] も いいですか (Bolehkah?) / [V-te] は いけません (Dilarang!)",coreWords:["しゃしん","とります","つかいます","きんえん"],coreWarning:'Aksara は pada "てはいけません" dibaca "wa". Penolakan izin dihaluskan.',quickDialogue:"A: 撮っても いいですか。 → B: いいえ、撮っては いけません。"}},"les-n5-u11-02":{pedagogical_framework:{what:{summary:"Aspek sedang berlangsung 〜ている (progressive action), kondisi hasil/status menetap 〜ている (resultant state), dan pekerjaan/tempat tinggal (住んでいます / 働いています).",canDo:"Bisa menceritakan aktivitas yang sedang dilakukan saat ini dan menjelaskan status pekerjaan serta tempat tinggal.",targetPatterns:["[Verba-te] います (sedang)","[Tempat] に 住んでいます (tinggal di)","[Perusahaan] で 働いています (bekerja di)","知っています (tahu/kenal)"],coreVocabSample:["すんでいます","はたらいています","しっています","けっこんしています","いま","でんわ"]},sensei_context:{sceneIntro:"Budi mengobrol dengan rekan kerja tentang kehidupan keluarganya di Indonesia dan aktivitas kerjanya saat ini di Tokyo.",dailyMission:"Gunakan 〜ています untuk menyatakan aktivitas saat ini dan status jangka panjang (tempat tinggal, status pernikahan).",whyOrder:"Pola 〜ている adalah salah satu pola aspek paling serbaguna: membedakan aksi dinamis vs keadaan hasil menetap."},cultural_notes:{title:"Bentuk Negatif dari 知っています (Shitte imasu)",etiquette:'Hati-hati dengan kata "tahu"! Bentuk positifnya "知っています" (shitte imasu), tetapi bentuk negatifnya WAJIB "知りません" (shirimasen), BUKAN "shitte imasen"!',taboos:'Jangan katakan "shitte imasen" saat menyatakan tidak tahu; selalu gunakan "shirimasen"!'},pronunciation_tips:{title:"Kontraksi Lisan 〜てる (Te ru)",moraNote:'Dalam percakapan kasual santai, huruf "i" sering teredam/hilang: shiteru (dari shite iru), nonderu (dari nonde iru).',soundTip:'Dalam ragam sopan resmi kantor, pertahankan vokal "i" penuh: "hataraite imasu".'},common_pitfalls:[{title:'Sangkalan Kata Tahu Menggunakan "Shitte imasen"',caseScenario:'Ingin bilang "saya tidak tahu".',pitfallWarning:'"しっていません。" (Salah Besar)',rightSolution:'"しりません。" (Benar Mutlak)',explanation:"Kaidah bahasa Jepang menetapkan bahwa lawan kata 知っています selalu 知りません."},{title:"Salah Partikel Tempat Tinggal (で vs に)",caseScenario:"Menggunakan partikel で untuk tempat tinggal.",pitfallWarning:'"とうきょう で すんでいます。" (Salah)',rightSolution:'"とうきょう に すんでいます。" (Benar)',explanation:"Kata kerja 住む (tinggal) menandai titik menetap dengan partikel に, bukan で."}],who_and_when:{situational_context:"Perkenalan latar belakang profil, wawancara magang, obrolan santai status keluarga.",social_relations:"Sangat lazim dan ramah di tempat kerja maupun kehidupan bertetangga.",when_not_to_use:"Jangan memakai kata shirimasen dengan nada ketus jika ditanya atasan (gunakan wakarimasen)."},scenario:{title:"Menceritakan Profil dan Tempat Tinggal Rekan Kerja",setting:"Meja kerja saat jam rehat, pukul 15.30",narrative:"Sakura menanyakan di mana Budi tinggal sekarang dan apakah saudaranya bekerja di Jepang juga."}},dialogue:[{id:"d1",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"ブディさん、今【いま】どこに 住【す】んでいますか。",furigana:"ブディさん、今どこに 住んでいますか。",romaji:"Budi-san, ima doko ni sunde imasu ka.",idText:"Budi-san, sekarang tinggal di mana?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"立川【たちかわ】の 会社【かいしゃ】の 寮【りょう】に 住【す】んでいます。",furigana:"立川の 会社の 寮に 住んでいます。",romaji:"Tachikawa no kaisha no ryou ni sunde imasu.",idText:"Saya tinggal di asrama perusahaan di Tachikawa."},{id:"d3",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"ご家族【かぞく】は インドネシアに 住【す】んでいますか。",furigana:"ご家族は インドネシアに 住んでいますか。",romaji:"Gokazoku wa Indonesia ni sunde imasu ka.",idText:"Apakah keluargamu tinggal di Indonesia?"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、両親【りょうしん】は ジャカルタに 住【す】んでいます。父【ちち】は 銀行【ぎんこう】で 働【はたら】いています。",furigana:"はい、両親は ジャカルタに 住んでいます。父は 銀行で 働いています。",romaji:"Hai, ryoushin wa Jakaruta ni sunde imasu. Chichi wa ginkou de hataraite imasu.",idText:"Iya, kedua orang tua saya tinggal di Jakarta. Ayah bekerja di bank."},{id:"d5",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"お父【とう】さんは 日本語【にほんご】を 知【し】っていますか。",furigana:"お父さんは 日本語を 知っていますか。",romaji:"Otousan wa nihongo o shitte imasu ka.",idText:"Apakah ayahmu tahu bahasa Jepang?"},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"いいえ、父【ちち】は 日本語【にほんご】を 知【し】りません。英語【えいご】を 話【はな】します。",furigana:"いいえ、父は 日本語を 知りません。英語を 話します。",romaji:"Iie, chichi wa nihongo o shirimasen. Eigo o hanashimasu.",idText:"Tidak, ayah saya tidak tahu bahasa Jepang. Beliau berbicara bahasa Inggris."},{id:"d7",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"ブディさん、今【いま】何【なに】を していますか。電話【でんわ】が 鳴【な】っていますよ。",furigana:"ブディさん、今何を していますか。電話が 鳴っていますよ。",romaji:"Budi-san, ima nani o shite imasu ka. Denwa ga natte imasu yo.",idText:"Budi-san, sekarang sedang apa? Teleponnya berdering tuh."},{id:"d8",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"あ、報告書【ほうこくしょ】を 作【つく】っています。すぐ 電話【でんわ】に 出【で】ます！",furigana:"あ、報告書を 作っています。すぐ 電話に 出ます！",romaji:"A, houkokusho o tsukutte imasu. Sugu denwa ni demasu!",idText:"Ah, saya sedang membuat laporan. Segera saya angkat teleponnya!"}],vocab_breakdown:[{id:"vg-n5-00415",word:"生活",reading:"せいかつ",romaji:"seikatsu",meaning:"kehidupan",pos:"verb-suru",nuance:"Refers to one's daily life, livelihood, or lifestyle. It focuses on the everyday routines of living, rather than life as a biological state (命).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"日本での生活はとても楽しいです。",furigana:"日本での生活はとても楽しいです。",romaji:"",idText:"Kehidupan di Jepang sangat menyenangkan."}},{id:"vg-n5-00495",word:"聞こえる",reading:"きこえる",romaji:"kikoeru",meaning:"bisa terdengar",pos:"verb-ru",nuance:"聞こえる = terdengar (involuntar). Berbeda: 聞く = mendengarkan (sengaja).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"隣の部屋から音楽が聞こえます。",furigana:"隣の部屋から音楽が聞こえます。",romaji:"",idText:"Terdengar musik dari kamar sebelah."}},{id:"vg-n5-00618",word:"いそぐ",reading:"いそぐ",romaji:"isogu",meaning:"terburu-buru, bergegas",pos:"verb-u",nuance:"Means to hurry or rush. The te-form (急いで) is often used to tell someone to hurry up.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"時間がありませんから、いそぎましょう。",furigana:"時間がありませんから、いそぎましょう。",romaji:"",idText:"Karena tidak ada waktu, mari kita bergegas."}},{id:"vg-n5-01026",word:"いる",reading:"いる",romaji:"iru",meaning:"ada",pos:"verb-ru",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"すっかり食べ終わってはいない。",furigana:"すっかり食べ終わってはいない。",romaji:"",idText:"I haven't quite finished eating."}},{id:"vg-n5-01027",word:"要る",reading:"いる",romaji:"iru",meaning:"membutuhkan",pos:"verb-u",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"今のところお金はいらない。",furigana:"今のところお金はいらない。",romaji:"",idText:"I don't need money at present."}},{id:"vg-n5-01043",word:"起きる",reading:"おきる",romaji:"okiru",meaning:"bangun",pos:"verb-ru",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"お子さんはまだ起きているのですか。",furigana:"お子さんはまだ起きているのですか。",romaji:"",idText:"Apakah anak itu masih belum tidur?"}},{id:"vg-n5-01119",word:"困る",reading:"こまる",romaji:"komaru",meaning:"merasa cemas / khawatir",pos:"verb-u",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"時間がなくてたいへん困っている。",furigana:"時間がなくてたいへん困っている。",romaji:"",idText:"I am pressed for time."}},{id:"vg-n5-01200",word:"できる",reading:"できる",romaji:"dekiru",meaning:"bisa / sanggup",pos:"verb-ru",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"あの二人はどうもできているらしい。",furigana:"あの二人はどうもできているらしい。",romaji:"",idText:"They seem to be in love with each other."}},{id:"vg-n5-01201",word:"テスト",reading:"テスト",romaji:"tesuto",meaning:"ujian / tes",pos:"verb-suru",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"そのテストはむずかしかった。",furigana:"そのテストはむずかしかった。",romaji:"",idText:"I found the test difficult."}},{id:"vg-n5-01204",word:"出る",reading:"でる",romaji:"deru",meaning:"muncul",pos:"verb-ru",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"電話には出なかったからメールしておきました。",furigana:"電話には出なかったからメールしておきました。",romaji:"",idText:"He didn't answer the phone, so I left him an email."}}],explanations:[{id:"exp-1",grammarId:"gn5-00029",title:"Pola: 〜ている",formula:"Vて + いる",meaning:"sedang ... / dalam keadaan ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜ている",idText:"sedang ... / dalam keadaan ..."}],examples:[{jp:"いまほんをよんでいます。",romaji:"",idText:"Sekarang sedang membaca buku."},{jp:"かれはけっこんしています。",romaji:"",idText:"Dia sudah menikah (dalam keadaan menikah)."},{jp:"あめがふっています。",romaji:"",idText:"Sedang hujan."}]},{id:"exp-2",grammarId:"gn5-00082",title:"Pola: もう V-ました",formula:"もう + V(ます-form past)",meaning:"sudah V (selesai)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"もう V-ました",idText:"sudah V (selesai)"}],examples:[{jp:"もう宿題をしました。",romaji:"",idText:"Saya sudah mengerjakan PR."},{jp:"荷物はもう送りましたか？",romaji:"",idText:"Apakah barang bawaannya sudah dikirim?"},{jp:"もうご飯を食べましたか？",romaji:"",idText:"Apakah kamu sudah makan?"}]},{id:"exp-3",grammarId:"gn5-00083",title:"Pola: まだ V-ます / まだ V-ていません",formula:"まだ + V(ます) または まだ + V-ていません",meaning:"masih V / belum V",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"まだ V-ます / まだ V-ていません",idText:"masih V / belum V"}],examples:[{jp:"まだ仕事をしています。",romaji:"",idText:"Saya masih bekerja."},{jp:"報告書はまだ書いていません。",romaji:"",idText:"Laporan belum saya tulis."},{jp:"まだ決めていません。",romaji:"",idText:"Saya belum memutuskan."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Kata): Pilihlah arti kata "住んでいます (すんでいます)".',sentencePrompt:'Frasa "住んでいます" bermakna:',options:["Tinggal / Menetap","Bekerja lembur","Berangkat sekolah","Sedang makan"],correctAnswer:"Tinggal / Menetap",explanation:'"住んでいます (sunde imasu)" berarti tinggal atau berdomisili menetap.',diagnosticFeedback:{"Bekerja lembur":"Salah: Bekerja adalah 働いています (hataraite imasu).","Berangkat sekolah":"Salah: Berangkat adalah 出かけます (dekakemasu).","Sedang makan":"Salah: Sedang makan adalah 食べています (tabete imasu)."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Isian Partikel Domisili): Pilihlah partikel penanda tempat domisili tinggal.",sentencePrompt:"私【わたし】は 東京【とうきょう】 _____ 住【す】んでいます。",options:["に","で","を","へ"],correctAnswer:"に",explanation:"Tempat berdomisili menetap (住んでいます) wajib menggunakan partikel に.",diagnosticFeedback:{で:"Salah: Partikel で menandai tempat aktivitas aksi dinamis, bukan tempat berdiam.",を:"Salah: Partikel を menandai objek kata kerja transitif.",へ:"Salah: Partikel へ menandai arah perpindahan gerak."}},{id:"drill-3",type:"reorder",instruction:"Langkah 3 (Susun Kalimat): Urutkan kalimat yang menyatakan sedang membuat laporan saat ini.",sentencePrompt:"Susunan kalimat yang tepat:",options:["今【いま】報告書【ほうこくしょ】を 作【つく】っています","報告書【ほうこくしょ】を 今【いま】作【つく】っています","作【つく】っています 今【いま】報告書【ほうこくしょ】を","今【いま】作【つく】っています 報告書【ほうこくしょ】を"],correctAnswer:"今【いま】報告書【ほうこくしょ】を 作【つく】っています",explanation:"Keterangan waktu (今) + Objek (報告書を) + Verba aspek progresif (作っています).",diagnosticFeedback:{"報告書【ほうこくしょ】を 今【いま】作【つく】っています":'Kurang lazim: Keterangan waktu "ima" biasanya ditaruh di depan.',"作【つく】っています 今【いま】報告書【ほうこくしょ】を":"Jebakan: Kata kerja ditaruh di depan.","今【いま】作【つく】っています 報告書【ほうこくしょ】を":"Jebakan SVO: Memindahkan objek ke belakang kata kerja."},tokens:["今【いま】報告書【ほうこくしょ】を","作【つく】っています"],correctOrder:["0","1"]},{id:"drill-4",type:"trap_detect",instruction:'Langkah 4 (Deteksi Jebakan): Manakah bentuk sangkalan dari "知っています (tahu)" yang benar?',sentencePrompt:'Pilihlah bentuk sangkalan untuk kata "tahu":',options:["知【し】りません。","知【し】っていません。","知【し】らないでした。","知【し】ってではありません。"],correctAnswer:"知【し】りません。",explanation:"Kaidah khusus bahasa Jepang: sangkalan dari 知っています WAJIB 知りません.",diagnosticFeedback:{"知【し】っていません。":'Jebakan Fatal: "Shitte imasen" tidak ada dalam tata bahasa Jepang standar.',"知【し】らないでした。":"Jebakan: Tata bahasa konjugasi salah.","知【し】ってではありません。":"Jebakan: Salah menggabungkan bentuk-te dengan dewa arimasen."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Saat ditanya "今 何を していますか", jawaban aktivitas progresif yang tepat adalah:',sentencePrompt:"Pilihlah jawaban aktivitas yang sedang dikerjakan:",options:["日本語【にほんご】を 勉強【べんきょう】しています。","日本語【にほんご】を 勉強【べんきょう】しました。","はい、しています。","昨日【きのう】行【い】きました。"],correctAnswer:"日本語【にほんご】を 勉強【べんきょう】しています。",explanation:"Menjawab pertanyaan sedang apa dengan pola 〜ています (sedang belajar).",diagnosticFeedback:{"日本語【にほんご】を 勉強【べんきょう】しました。":"Bentuk lampau (tadi sudah belajar), tidak menjawab aktivitas sekarang.","はい、しています。":"Tidak menjawab konten aktivitas apa yang sedang dikerjakan.","昨日【きのう】行【い】きました。":"Salah konteks waktu kemarin."}}],can_do_challenge:{statement:"Bisa menceritakan status pekerjaan dan tempat tinggal saat ini.",situation:"Wawancara perkenalan latar belakang diri di tempat kerja.",promptTask:"Katakan bahwa kamu tinggal di Tokyo dan bekerja di pabrik!",modelAnswer:"私【わたし】は 東京【とうきょう】に 住【す】んでいて、工場【こうじょう】で 働【はたら】いています。",modelAnswerId:"Saya tinggal di Tokyo dan bekerja di pabrik.",culturalEtiquette:"Gunakan partikel に untuk 住んでいます dan で untuk 働いています.",skillUnlocked:["Menguasai aspek progresif dan keadaan hasil 〜ている","Membedakan partikel domisili に dan aksi で"]},pocket_summary:{keyFormula:"[Tempat] に 住んでいます / [Tempat] で 働いています / [V-te] います",coreWords:["すんでいます","はたらいています","しっています","しりません"],coreWarning:'Lawan kata dari "知っています" adalah "知りません", BUKAN "知っていません".',quickDialogue:"A: どこに 住んでいますか。 → B: 東京に 住んでいます。"}}},i={"les-n5-u12-01":{pedagogical_framework:{what:{summary:"Pola transaksi kebaikan dan bantuan: 〜てあげる (memberi bantuan ke luar), 〜てくれる (orang lain berbuat kebaikan ke arah pembicara), dan 〜てもらう (menerima/meminta bantuan).",canDo:"Bisa mengucapkan terima kasih mendalam saat dibantu rekan kerja dan menawarkan bantuan kepada orang lain.",targetPatterns:["[Orang] に [Verba-te] あげる","[Orang] が [Verba-te] くれる","[Orang] に [Verba-te] もらう"],coreVocabSample:["てつだって","おしえてくれました","なおしてもらいました","にもつ","てがみ"]},sensei_context:{sceneIntro:"Di kantor, Budi kesulitan mengisi formulir pendaftaran asuransi kesehatan dalam bahasa Jepang. Tanaka-senpai dengan ramah membantu mengoreksi.",dailyMission:"Gunakan 〜てくれました saat berterima kasih atas bantuan orang lain, dan 〜てあげます saat menawarkan kebaikan.",whyOrder:"Pola benefaktif (Yari-morai) adalah cermin psikologi sosial Jepang: sudut pandang batin (Uchi) vs luar (Soto)."},cultural_notes:{title:"Psikologi Arah Kebaikan (Inward vs Outward)",etiquette:'Saat menerima bantuan dari atasan atau orang lain, SELALU gunakan 〜てくれました atau 〜てもらいました. Jangan pernah katakan "Tanaka-san ni oshiete agemashita" saat Tanaka yang mengajari!',taboos:"Jangan memakai 〜てあげる secara terang-terangan kepada atasan, karena terdengar seperti merasa berjasa atau menggurui."},pronunciation_tips:{title:"Penekanan Rasa Syukur",moraNote:'Lafalkan "oshiete kuremashita" dengan intonasi hangat dan senyuman.',soundTip:'Katakan "tetsudaimashou ka" saat menawarkan bantuan dengan sopan.'},common_pitfalls:[{title:'Terbalik Arah Sudut Pandang "Ageru" vs "Kureru"',caseScenario:'Ingin bilang "Tanaka mengajari saya", tapi memakai ageru.',pitfallWarning:'"たなかさん は わたし に おしえて あげました。" (Salah Total)',rightSolution:'"たなかさん は わたし に おしえて くれました。" (Benar)',explanation:"Kebaikan yang mengalir DARI orang lain MENUJU pembicara WAJIB menggunakan くれる (kureru)."},{title:'Menyatakan "Te ageru" kepada Atasan',caseScenario:"Menawarkan bantuan kepada supervisor dengan pola ageru.",pitfallWarning:'"てつだって あげます。" (Tidak sopan ke atasan)',rightSolution:'"おてつだい しましょうか。" (Sopan santun)',explanation:"Pola 〜てあげる berkonotasi condescending jika ditujukan kepada status yang lebih tinggi."}],who_and_when:{situational_context:"Menerima bantuan dokumen dari rekan kantor, berterima kasih kepada mentor, menawarkan bantuan barang berat.",social_relations:"Sangat krusial untuk membangun hubungan kerja sama tim (Wa) di tempat kerja Jepang.",when_not_to_use:"Jangan pakai te-ageru kepada tamu perusahaan atau atasan langsung."},scenario:{title:"Bantuan Pengisian Formulir Asuransi Kantor",setting:"Meja kerja administrasi, pukul 16.30",narrative:"Tanaka membantu Budi memeriksa ejaan kanji pada formulir asuransi. Budi merasa sangat terbantu dan berterima kasih."}},dialogue:[{id:"d1",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"田中【たなか】さん、保険【ほけん】の 書類【しょるい】を 見【み】ていただけませんか。",furigana:"田中さん、保険の 書類を 見ていただけませんか。",romaji:"Tanaka-san, hoken no shorui o mite itadakemasen ka.",idText:"Tanaka-san, bolehkah saya meminta tolong memeriksa berkas asuransi ini?"},{id:"d2",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"いいですよ。どれどれ……あ、ここを 直【なお】して あげましょう。",furigana:"いいですよ。どれどれ……あ、ここを 直して あげましょう。",romaji:"Ii desu yo. Dore dore... a, koko o naoshite agemashou.",idText:"Boleh. Coba kulihat... ah, bagian ini saya perbaiki ya."},{id:"d3",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"ありがとうございます！田中【たなか】さんが 優【やさ】しく 教【おし】えて くれました。",furigana:"ありがとうございます！田中さんが 優しく 教えて くれました。",romaji:"Arigatou gozaimasu! Tanaka-san ga yasashiku oshiete kuremashita.",idText:"Terima kasih banyak! Tanaka-san telah mengajari saya dengan sangat ramah."},{id:"d4",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"分【わ】からない ことは、遠慮【えんりょ】しないで 先輩【せんぱい】に 聞【き】いてくださいね。",furigana:"分からない ことは、遠慮しないで 先輩に 聞いてくださいね。",romaji:"Wakaranai koto wa, enryo shinaide senpai ni kiite kudasai ne.",idText:"Kalau ada yang tidak dipahami, jangan sungkan bertanya kepada senior ya."},{id:"d5",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"ブディさん、重【おも】い 荷物【にもつ】ですね。手伝【てつだ】いましょうか。",furigana:"ブディさん、重い 荷物ですね。手伝いましょうか。",romaji:"Budi-san, omoi nimotsu desu ne. Tetsudaimashou ka.",idText:"Budi-san, barang bawaan berat ya. Mau kubantu?"},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"あ、さくらさん、ありがとうございます！持【も】って もらっても いいですか。",furigana:"あ、さくらさん、ありがとうございます！持って もらっても いいですか。",romaji:"A, Sakura-san, arigatou gozaimasu! Motte moratte mo ii desu ka.",idText:"Ah, Sakura-san, terima kasih banyak! Bolehkah saya minta tolong dibawakan?"},{id:"d7",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"もちろんですよ。一緒【いっしょ】に 倉庫【そうこ】へ 運【はこ】びましょう。",furigana:"もちろんですよ。一緒に 倉庫へ 運びましょう。",romaji:"Mochiron desu yo. Issho ni souko e hakobimashou.",idText:"Tentu saja. Mari kita angkut bersama ke gudang."},{id:"d8",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"助【たす】かりました。みなさん、いつも 親切【しんせつ】にしてくれて 感謝【かんしゃ】します！",furigana:"助かりました。みなさん、いつも 親切にしてくれて 感謝します！",romaji:"Tasukarimashita. Minasan, itsumo shinsetsu ni shite kurete kansha shimasu!",idText:"Sangat terbantu. Saya berterima kasih kepada semuanya yang selalu berbuat baik kepada saya!"}],vocab_breakdown:[{id:"vg-n5-00015",word:"着る",reading:"きる",romaji:"kiru",meaning:"memakai (pakaian bagian atas)",pos:"verb-ru",nuance:"Hanya untuk pakaian di bagian atas tubuh. 履く untuk celana/sepatu, かぶる untuk topi.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"コートを着て出かけました。",furigana:"コートを着て出かけました。",romaji:"",idText:"Saya keluar memakai mantel."}},{id:"vg-n5-00018",word:"知る",reading:"しる",romaji:"shiru",meaning:"mengetahui",pos:"verb-u",nuance:"知っている = keadaan tahu sekarang. 知らない = tidak tahu.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"彼の名前を知っていますか。",furigana:"彼の名前を知っていますか。",romaji:"",idText:"Apakah kamu tahu namanya?"}},{id:"vg-n5-00021",word:"座る",reading:"すわる",romaji:"suwaru",meaning:"duduk",pos:"verb-u",nuance:"来る (くる) — CATATAN: entry ini duplikat v-n5-0010? Cek.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"椅子に座ってください。",furigana:"椅子に座ってください。",romaji:"",idText:"Silakan duduk di kursi."}},{id:"vg-n5-00022",word:"立つ",reading:"たつ",romaji:"tatsu",meaning:"berdiri",pos:"verb-u",nuance:"ある = ada (benda mati/abstrak). Lawan: いる = ada (makhluk hidup). Negatif: ない (bukan あらない).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"立ってください。",furigana:"立ってください。",romaji:"",idText:"Silakan berdiri."}},{id:"vg-n5-00034",word:"泳ぐ",reading:"およぐ",romaji:"oyogu",meaning:"berenang",pos:"verb-u",nuance:"かける = menelepon / menggantungkan / menuangkan. Konteks tergantung objek.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"プールで泳ぎました。",furigana:"プールで泳ぎました。",romaji:"",idText:"Saya berenang di kolam renang."}},{id:"vg-n5-00046",word:"終わる",reading:"おわる",romaji:"owaru",meaning:"selesai, berakhir",pos:"verb-u",nuance:"Intransitif. Transitif: 終える (jarang).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"授業が終わりました。",furigana:"授業が終わりました。",romaji:"",idText:"Pelajaran sudah selesai."}},{id:"vg-n5-00048",word:"押す",reading:"おす",romaji:"osu",meaning:"mendorong; menekan",pos:"verb-u",nuance:"終わる = selesai/berakhir (intransitif). 仕事が終わる. Transitif: 終える (lebih formal).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"ボタンを押してください。",furigana:"ボタンを押してください。",romaji:"",idText:"Tolong tekan tombolnya."}},{id:"vg-n5-00051",word:"あげる",reading:"あげる",romaji:"ageru",meaning:"memberikan (ke orang lain)",pos:"verb-ru",nuance:"Keigo: 差し上げる (kenjo). Dipakai saat speaker memberi ke orang lain.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"友達にプレゼントをあげました。",furigana:"友達にプレゼントをあげました。",romaji:"",idText:"Saya memberi hadiah ke teman."}},{id:"vg-n5-00054",word:"ある",reading:"ある",romaji:"aru",meaning:"ada (benda mati)",pos:"verb-u",nuance:"Untuk benda. Nai-form irregular: ない (bukan あらない).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"机の上に本があります。",furigana:"机の上に本があります。",romaji:"",idText:"Ada buku di atas meja."}},{id:"vg-n5-00168",word:"あける",reading:"あける",romaji:"akeru",meaning:"membuka",pos:"verb-ru",nuance:"あける = membuka (transitif, ada pelaku). Intransitif: あく.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"窓を開けてください。",furigana:"窓を開けてください。",romaji:"",idText:"Tolong buka jendelanya."}}],explanations:[{id:"exp-1",grammarId:"gn5-00037",title:"Pola: 〜てあげる",formula:"Vて + あげる",meaning:"melakukan untuk (orang lain) — perspektif pemberi",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜てあげる",idText:"melakukan untuk (orang lain) — perspektif pemberi"}],examples:[{jp:"ともだちに本をかしてあげました。",romaji:"",idText:"Meminjamkan buku kepada teman."},{jp:"こどもにえをかいてあげた。",romaji:"",idText:"Menggambar gambar untuk anak itu."}]},{id:"exp-2",grammarId:"gn5-00038",title:"Pola: 〜てもらう",formula:"N (pelaku) + に + Vて + もらう",meaning:"menerima layanan / meminta seseorang melakukan ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜てもらう",idText:"menerima layanan / meminta seseorang melakukan ..."}],examples:[{jp:"せんせいにおしえてもらいました。",romaji:"",idText:"Diajari oleh guru (dan saya merasa beruntung)."},{jp:"ともだちにつれてもらった。",romaji:"",idText:"Dibawa pergi oleh teman."}]},{id:"exp-3",grammarId:"gn5-00039",title:"Pola: 〜てくれる",formula:"N (pelaku) + が/は + Vて + くれる",meaning:"(seseorang) melakukan untuk saya/kelompok kami",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜てくれる",idText:"(seseorang) melakukan untuk saya/kelompok kami"}],examples:[{jp:"ははがべんとうをつくってくれた。",romaji:"",idText:"Ibu membuatkan bento untuk saya."},{jp:"おしえてくれてありがとう。",romaji:"",idText:"Terima kasih sudah mengajari."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Kata): Pilihlah arti kata "親切 (しんせつ)".',sentencePrompt:'Kata sifat "親切" memiliki arti:',options:["Ramah / Baik hati","Cepat marah","Pelit / Kikir","Sombong"],correctAnswer:"Ramah / Baik hati",explanation:'"親切 (しんせつ)" berarti ramah, baik hati, dan suka menolong.',diagnosticFeedback:{"Cepat marah":"Salah: Cepat marah adalah 怒りっぽい (okorippoi).","Pelit / Kikir":"Salah: Pelit adalah けち (kechi).",Sombong:"Salah: Sombong adalah 生意気 (namaiki) atau 傲慢."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Isian Arah Kebaikan): Lengkapilah kalimat yang menyatakan rekan kerja telah mengajari saya.",sentencePrompt:"さくらさんが 私【わたし】に 日本語【にほんご】を 教【おし】えて _____。",options:["くれました","あげました","もらいました","やりました"],correctAnswer:"くれました",explanation:"Orang lain (Sakura-san) berbuat kebaikan ke arah pembicara (watashi ni) wajib memakai くれました.",diagnosticFeedback:{あげました:"Salah Fatal: Ageru berarti pembicara yang memberi ke luar, bukan menerima.",もらいました:"Salah Susunan: Jika memakai moraimashita, subjeknya harus pembicara (watashi wa Sakura-san ni...).",やりました:"Salah: やる hanya untuk hewan atau tanaman (memberi makan kucing)."}},{id:"drill-3",type:"reorder",instruction:"Langkah 3 (Susun Kalimat): Urutkan kalimat menerima bantuan perbaikan barang berikut.",sentencePrompt:"Susunan kalimat yang tepat:",options:["田中【たなか】さんに パソコンを 直【なお】して もらいました","パソコンを 田中【たなか】さんに 直【なお】して もらいました","直【なお】して もらいました 田中【たなか】さんに パソコンを","田中【たなか】さんに 直【なお】して パソコンを もらいました"],correctAnswer:"田中【たなか】さんに パソコンを 直【なお】して もらいました",explanation:"Pelaku pemberi jasa (田中さんに) + Objek (パソコンを) + Menerima kebaikan (直してもらいました).",diagnosticFeedback:{"パソコンを 田中【たなか】さんに 直【なお】して もらいました":"Kurang lazim: Penanda pelaku jasa biasanya mendahului objek barang.","直【なお】して もらいました 田中【たなか】さんに パソコンを":"Jebakan: Predikat di depan kalimat.","田中【たなか】さんに 直【なお】して パソコンを もらいました":"Jebakan: Pola te-morau terbelah objek."},tokens:["田中【たなか】さんに","パソコンを","直【なお】して","もらいました"],correctOrder:["0","1","2","3"]},{id:"drill-4",type:"trap_detect",instruction:"Langkah 4 (Deteksi Jebakan): Manakah penggunaan benefaktif yang benar saat senior menolong kita?",sentencePrompt:"Pilihlah kalimat yang tepat:",options:["先輩【せんぱい】が 荷物【にもつ】を 運【はこ】んで くれました。","先輩【せんぱい】が 荷物【にもつ】を 運【はこ】んで あげました。","私【わたし】が 先輩【せんぱい】に 運【はこ】んで くれました。","先輩【せんぱい】を 荷物【にもつ】が 運【はこ】んで もらいました。"],correctAnswer:"先輩【せんぱい】が 荷物【にもつ】を 運【はこ】んで くれました。",explanation:"Senior berbuat kebaikan ke arah kita memakai [Senior] が ... てくれました.",diagnosticFeedback:{"先輩【せんぱい】が 荷物【にもつ】を 運【はこ】んで あげました。":"Jebakan Fatal: Ageru tidak tepat untuk aksi senior menolong kita.","私【わたし】が 先輩【せんぱい】に 運【はこ】んで くれました。":"Jebakan terbalik: Watashi ga tidak bisa berpasangan dengan kuremashita.","先輩【せんぱい】を 荷物【にもつ】が 運【はこ】んで もらいました。":"Jebakan: Partikel tertukar berantakan."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Saat rekan kerja berkata "荷物を手伝いましょうか", respons menerima bantuan yang santun adalah:',sentencePrompt:"Pilihlah respon menerima tawaran bantuan:",options:["ありがとうございます！助【たす】かります。お願【ねが】いします。","いいえ、だめです。","手伝【てつだ】って あげます。","荷物【にもつ】は ありません。"],correctAnswer:"ありがとうございます！助【たす】かります。お願【ねが】いします。",explanation:"Mengucapkan terima kasih (Tasukarimasu) dan memohon bantuan (Onegai shimasu).",diagnosticFeedback:{"いいえ、だめです。":"Terlalu kasar menolak tawaran baik rekan kerja.","手伝【てつだ】って あげます。":"Jebakan: Malah terbalik menawarkan bantuan ke orang lain.","荷物【にもつ】は ありません。":"Berdalih tidak masuk akal padahal sedang membawa barang."}}],can_do_challenge:{statement:"Bisa mengucapkan terima kasih mendalam atas bantuan rekan kerja.",situation:"Menerima bantuan penyelesaian tugas kerja dari rekan kantor.",promptTask:"Ucapkan terima kasih bahwa Tanaka-senpai telah mengajarimu dengan ramah!",modelAnswer:"田中【たなか】さん、親切【しんせつ】に 教【おし】えてくれて 本当【ほんとう】に ありがとうございました。",modelAnswerId:"Tanaka-san, terima kasih banyak telah mengajari saya dengan sangat ramah.",culturalEtiquette:"Gunakan [Verba-te] + くれて arigatou gozaimashita untuk menunjukkan rasa terima kasih mendalam.",skillUnlocked:["Menguasai sudut pandang arah kebaikan yari-morai","Mampu berterima kasih secara elegan dalam konteks kerja"]},pocket_summary:{keyFormula:"[Orang] が [V-te] くれる (saya dibantu) / [Orang] に [V-te] もらう (menerima bantuan)",coreWords:["てつだって","おしえてくれました","しんせつ","にもつ"],coreWarning:'Jangan pernah gunakan "te ageru" kepada atasan atau saat menceritakan diri sendiri yang dibantu.',quickDialogue:"A: 教えてあげましょうか。 → B: ありがとうございます！助かります。"}},"les-n5-u12-02":{pedagogical_framework:{what:{summary:"Menyatakan potensi kemampuan nominal dengan [Verba Kamus] ことができる, dan pengalaman hidup di masa lalu dengan [Verba-ta] ことがある.",canDo:"Bisa memaparkan keterampilan mengemudi/berbahasa dan menceritakan pengalaman mendaki gunung di Jepang.",targetPatterns:["[Verba Kamus] ことが できます (bisa / mampu)","[Verba-ta] ことが あります (pernah)","[Verba-ta] ことが ありません (belum pernah)"],coreVocabSample:["うんてん","ふじさん","のぼったことがあります","かのう","がいこくご"]},sensei_context:{sceneIntro:"Sesi wawancara keterampilan magang atau obrolan santai di asrama. Sakura menanyakan pengalaman Budi keliling Jepang dan keterampilan berkendara.",dailyMission:"Mampu menjelaskan apa yang bisa kamu lakukan dengan ことができる dan menceritakan pengalaman lampau dengan ことがある.",whyOrder:'Dua pola "koto" ini adalah pola nominalisasi paling sering muncul di ujian JLPT N5 dan percakapan profil kerja!'},cultural_notes:{title:"Pengalaman Mendaki Gunung Fuji (富士登山)",etiquette:"Di Jepang, mendaki Gunung Fuji hanya dibuka saat musim panas (Juli–Agustus). Memiliki pengalaman mendaki Fuji adalah kebanggaan yang menarik diperbincangkan.",taboos:'Jangan tertukar! "Koto ga dekiru" WAJIB diawali Verba Kamus (Jisho-kei). "Koto ga aru" WAJIB diawali Verba Bentuk-Ta (Ta-kei)!'},pronunciation_tips:{title:"Pembeda Bentuk Kamus vs Bentuk-Ta",moraNote:'Perhatikan: "noboru koto ga dekiru" (Kamus) vs "nobotta koto ga aru" (Bentuk-Ta lampau).',soundTip:'Konsonan rangkap pada "nobotta" harus ditahan 1 ketukan mora.'},common_pitfalls:[{title:'Salah Menghubungkan Bentuk Verba ke "Koto ga aru"',caseScenario:'Memakai bentuk kamus sebelum koto ga aru: "noboru koto ga aru".',pitfallWarning:'"ふじさん に のぼる こと が あります。" (Artinya jadi: kadang-kadang mendaki)',rightSolution:'"ふじさん に のぼった こと が あります。" (Benar: pernah mendaki)',explanation:'Menyatakan pengalaman hidup masa lalu ("pernah") WAJIB menggunakan Bentuk-Ta: V-ta + ことがある.'},{title:'Menggunakan Bentuk Masu Sebelum "Koto ga dekiru"',caseScenario:'Menempelkan bentuk masu ke koto ga dekiru: "hanashimasu koto ga dekiru".',pitfallWarning:'"はなします こと が できます。" (Salah Fatal)',rightSolution:'"はなす こと が できます。" (Benar - Wajib Bentuk Kamus)',explanation:"Nominalisasi dengan こと selalu menuntut Bentuk Biasa Kamus (Jisho-kei)."}],who_and_when:{situational_context:"Wawancara kerja, pengisian CV/Resume (Rirekisho), obrolan wisata liburan.",social_relations:"Ragam sopan standar (Teineigo) yang sangat fleksibel.",when_not_to_use:"Jangan pakai koto ga aru untuk hal rutin yang baru terjadi kemarin (hanya untuk pengalaman hidup berkesan)."},scenario:{title:"Wawancara Keterampilan dan Pengalaman Budaya Jepang",setting:"Ruang rapat kantor saat evaluasi magang, pukul 14.00",narrative:"Tanaka menanyakan apakah Budi bisa mengendarai mobil di Jepang dan apakah pernah berwisata ke Kyoto."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"ブディさんは、車【くるま】の 運転【うんてん】を する ことが できますか。",furigana:"ブディさんは、車の 運転を する ことが できますか。",romaji:"Budi-san wa, kuruma no unten o suru koto ga dekimasu ka.",idText:"Budi-san, apakah kamu bisa menyetir mobil?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、インドネシアで 運転【うんてん】した ことが あります。国際免許【こくさいめんきょ】も あります。",furigana:"はい、インドネシアで 運転した ことが あります。国際免許も あります。",romaji:"Hai, Indonesia de unten shita koto ga arimasu. Kokusaimenkyo mo arimasu.",idText:"Iya, saya pernah menyetir di Indonesia. Saya punya SIM internasional juga."},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"それは 頼【たの】もしいですね！日本【にほん】で どこか 旅行【りょこう】に 行【い】きましたか。",furigana:"それは 頼もしいですね！日本で どこか 旅行に 行きましたか。",romaji:"Sore wa tanomoshii desu ne! Nihon de dokoka ryokou ni ikimashita ka.",idText:"Wah, bisa diandalkan ya! Di Jepang sudah pernah pergi liburan ke mana?"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"去年【きょねん】京都【きょうと】へ 行【い】った ことが あります。お寺【てら】が きれいでした。",furigana:"去年京都へ 行った ことが あります。お寺が きれいでした。",romaji:"Kyonen Kyouto e itta koto ga arimasu. Otera ga kirei deshita.",idText:"Tahun lalu saya pernah pergi ke Kyoto. Kuil-kuilnya sangat indah."},{id:"d5",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"富士山【ふじさん】に 登【のぼ】った ことが ありますか。",furigana:"富士山に 登った ことが ありますか。",romaji:"Fujisan ni nobotta koto ga arimasu ka.",idText:"Apakah pernah mendaki Gunung Fuji?"},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"いいえ、まだ 一度【いちど】も 登【のぼ】った ことが ありません。今年【ことし】登【のぼ】りたいです。",furigana:"いいえ、まだ 一度も 登った ことが ありません。今年登りたいです。",romaji:"Iie, mada ichido mo nobotta koto ga arimasen. Kotoshi noboritai desu.",idText:"Belum, sama sekali belum pernah mendaki. Tahun ini saya ingin mendakinya."},{id:"d7",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"夏【なつ】に なったら、みんなで 一緒【いっしょ】に 行【い】きましょう！",furigana:"夏に なったら、みんなで 一緒に 行きましょう！",romaji:"Natsu ni nattara, minna de issho ni ikimashou!",idText:"Kalau sudah musim panas, ayo kita pergi bersama semuanya!"},{id:"d8",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい！ぜひ 登【のぼ】ってみたいです。よろしく お願【ねが】いします！",furigana:"はい！ぜひ 登ってみたいです。よろしくお願いします！",romaji:"Hai! Zehi nobotte mitai desu. Yoroshiku onegaishimasu!",idText:"Wah, saya ingin sekali mencoba mendakinya. Mohon bimbingannya ya!"}],vocab_breakdown:[{id:"vg-n5-00103",word:"母",reading:"はは",romaji:"haha",meaning:"ibu (saya)",pos:"noun",nuance:"Untuk bicara tentang ibu sendiri. お母さん untuk ibu orang lain.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"母は料理が上手です。",furigana:"母は料理が上手です。",romaji:"",idText:"Ibu saya pandai masak."}},{id:"vg-n5-00104",word:"朝",reading:"あさ",romaji:"asa",meaning:"pagi",pos:"noun",nuance:"弟 (おとうと) = adik laki-laki saya. Bicara tentang adik orang lain: 弟さん.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"朝ご飯を食べましたか。",furigana:"朝ご飯を食べましたか。",romaji:"",idText:"Apakah kamu sudah sarapan?"}},{id:"vg-n5-00289",word:"うち",reading:"うち",romaji:"uchi",meaning:"rumah; keluarga saya",pos:"noun",nuance:"うち = rumah/keluargaku (kasual). 家 (いえ) = rumah (bangunan). お宅 (formal).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"うちでご飯を食べましょう。",furigana:"うちでご飯を食べましょう。",romaji:"",idText:"Mari makan di rumah."}},{id:"vg-n5-00370",word:"かぞく",reading:"かぞく",romaji:"kazoku",meaning:"keluarga",pos:"noun",nuance:"Refers to one's own family or a family unit. When referring to someone else's family politely, 'ごかぞく' (gokazoku) is used.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"家族と旅行しました。",furigana:"家族と旅行しました。",romaji:"",idText:"Saya berwisata bersama keluarga."}},{id:"vg-n5-00371",word:"ちち",reading:"ちち",romaji:"chichi",meaning:"ayah (saya)",pos:"noun",nuance:"父 (humble, untuk ayah sendiri). お父さん = panggilan/bicara tentang ayah orang lain.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"父は会社員です。",furigana:"父は会社員です。",romaji:"",idText:"Ayah saya karyawan."}},{id:"vg-n5-00372",word:"はは",reading:"はは",romaji:"haha",meaning:"ibu (saya)",pos:"noun",nuance:"母 (humble, untuk ibu sendiri). お母さん = panggilan/bicara tentang ibu orang lain.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"母は料理が上手です。",furigana:"母は料理が上手です。",romaji:"",idText:"Ibu saya pandai memasak."}},{id:"vg-n5-00373",word:"あに",reading:"あに",romaji:"ani",meaning:"kakak laki-laki (saya)",pos:"noun",nuance:"兄 (humble). お兄さん = kakak laki-laki orang lain.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"兄は大学生です。",furigana:"兄は大学生です。",romaji:"",idText:"Kakak laki-laki saya mahasiswa."}},{id:"vg-n5-00374",word:"あね",reading:"あね",romaji:"ane",meaning:"kakak perempuan (saya)",pos:"noun",nuance:"姉 (humble). お姉さん = kakak perempuan orang lain.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"姉は看護師として働いています。",furigana:"姉は看護師として働いています。",romaji:"",idText:"Kakak perempuan saya bekerja sebagai perawat."}},{id:"vg-n5-00375",word:"おとうと",reading:"おとうと",romaji:"otouto",meaning:"adik laki-laki (saya)",pos:"noun",nuance:"Used when talking about one's own younger brother to others. For someone else's younger brother, use 'おとうとさん' (otoutosan).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"弟は中学生です。",furigana:"弟は中学生です。",romaji:"",idText:"Adik laki-laki saya siswa SMP."}},{id:"vg-n5-00376",word:"いもうと",reading:"いもうと",romaji:"imouto",meaning:"adik perempuan (saya)",pos:"noun",nuance:"Used when talking about one's own younger sister. When referring to someone else's, use 'いもうとさん' (imoutosan).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"妹はまだ小学生です。",furigana:"妹はまだ小学生です。",romaji:"",idText:"Adik perempuan saya masih siswa SD."}}],explanations:[{id:"exp-1",grammarId:"gn5-00050",title:"Pola: 〜ことができる",formula:"Vる + ことができる",meaning:"bisa / mampu melakukan ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜ことができる",idText:"bisa / mampu melakukan ..."}],examples:[{jp:"かれはえいごをはなすことができます。",romaji:"",idText:"Dia bisa berbicara bahasa Inggris."},{jp:"にほんごをよむことができますか。",romaji:"",idText:"Bisa membaca bahasa Jepang?"}]},{id:"exp-2",grammarId:"gn5-00051",title:"Pola: 〜ことがある",formula:"Vた + ことがある (pengalaman) / Vる + ことがある (kadang-kadang)",meaning:"pernah ... / kadang-kadang ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜ことがある",idText:"pernah ... / kadang-kadang ..."}],examples:[{jp:"にほんへいったことがあります。",romaji:"",idText:"Pernah pergi ke Jepang."},{jp:"にほんごをわすれることがある。",romaji:"",idText:"Kadang-kadang lupa bahasa Jepang."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Kata): Pilihlah arti kata "運転 (うんてん)".',sentencePrompt:'Kata "運転" bermakna:',options:["Menyetir / Mengemudi","Memasak makanan","Membaca buku","Mencuci baju"],correctAnswer:"Menyetir / Mengemudi",explanation:'"運転 (うんてん)" berarti menyetir atau mengoperasikan kendaraan/mesin.',diagnosticFeedback:{"Memasak makanan":"Salah: Memasak adalah 料理 (ryouri).","Membaca buku":"Salah: Membaca adalah 読書 (dokusho).","Mencuci baju":"Salah: Mencuci baju adalah 洗濯 (sentaku)."}},{id:"drill-2",type:"cloze",instruction:'Langkah 2 (Isian Rumus Pengalaman): Pilihlah bentuk verba yang tepat untuk "pernah pergi ke Kyoto".',sentencePrompt:"私【わたし】は 京都【きょうと】へ _____ ことが あります。",options:["行【い】った","行【い】く","行【い】きます","行【い】って"],correctAnswer:"行【い】った",explanation:"Menyatakan pengalaman masa lalu (pernah) WAJIB menggunakan Verba Bentuk-Ta: 行った ことが あります.",diagnosticFeedback:{"行【い】く":'Salah: Bentuk kamus + koto ga aru berarti "kadang-kadang terjadi aksi".',"行【い】きます":"Salah: Bentuk masu tidak bisa menempel pada koto.","行【い】って":"Salah: Bentuk-te tidak digunakan untuk pola koto ga aru."}},{id:"drill-3",type:"reorder",instruction:"Langkah 3 (Susun Kalimat): Urutkan kalimat yang menyatakan kemampuan berbahasa Jepang berikut.",sentencePrompt:"Susunan kalimat yang tepat:",options:["日本語【にほんご】を 話【はな】す ことが できます","話【はな】す ことが 日本語【にほんご】を できます","できます 日本語【にほんご】を 話【はな】す ことが","日本語【にほんご】を 話【はな】します ことが できます"],correctAnswer:"日本語【にほんご】を 話【はな】す ことが できます",explanation:"Objek (日本語を) + Verba Kamus + ことが できます (話すことができます).",diagnosticFeedback:{"話【はな】す ことが 日本語【にほんご】を できます":"Jebakan: Objek ditaruh di tengah pola kemampuan.","できます 日本語【にほんご】を 話【はな】す ことが":"Jebakan: Predikat di awal kalimat.","日本語【にほんご】を 話【はな】します ことが できます":"Jebakan Fatal: Salah memakai bentuk masu sebelum koto."},tokens:["日本語【にほんご】を","話【はな】す","ことが","できます"],correctOrder:["0","1","2","3"]},{id:"drill-4",type:"trap_detect",instruction:'Langkah 4 (Deteksi Jebakan): Manakah kalimat yang menyatakan "belum pernah sama sekali mendaki"?',sentencePrompt:"Pilihlah ungkapan belum pernah yang benar:",options:["一度【いちど】も 登【のぼ】った ことが ありません。","一度【いちど】も 登【のぼ】る ことが ありません。","一度【いちど】も 登【のぼ】った ことが あります。","一度【いちど】も 登【のぼ】りません ことが あります。"],correctAnswer:"一度【いちど】も 登【のぼ】った ことが ありません。",explanation:"Belum pernah sama sekali = 一度も + [V-ta] ことが ありません.",diagnosticFeedback:{"一度【いちど】も 登【のぼ】る ことが ありません。":"Jebakan: Menggunakan bentuk kamus bukan bentuk-ta.","一度【いちど】も 登【のぼ】った ことが あります。":'Kontradiktif: Mengatakan "belum sekali pun" tapi predikatnya positif "pernah".',"一度【いちど】も 登【のぼ】りません ことが あります。":"Jebakan: Bentuk masen salah menempel pada koto."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Saat ditanya "富士山に 登った ことが ありますか", jawaban "belum pernah tapi ingin mencoba" yang tepat adalah:',sentencePrompt:"Pilihlah jawaban yang tepat:",options:["いいえ、まだ ありませんが、登【のぼ】ってみたいです。","はい、行【い】きません。","富士山【ふじさん】は どこですか、知【し】りません。","登【のぼ】ることが できます、さようなら。"],correctAnswer:"いいえ、まだ ありませんが、登【のぼ】ってみたいです。",explanation:"Menjawab secara lengkap: belum pernah, tetapi ingin mencoba mendakinya.",diagnosticFeedback:{"はい、行【い】きません。":"Kontradiktif menjawab ya tetapi predikatnya menyangkal.","富士山【ふじさん】は どこですか、知【し】りません。":"Ketus dan tidak menjawab esensi pengalaman.","登【のぼ】ることが できます、さようなら。":"Sayounara tidak nyambung."}}],can_do_challenge:{statement:"Bisa memaparkan keterampilan mengemudi dan pengalaman berwisata di Jepang.",situation:"Wawancara keterampilan dan pengalaman budaya.",promptTask:"Katakan bahwa kamu bisa menyetir mobil dan pernah pergi ke Kyoto!",modelAnswer:"私【わたし】は 車【くるま】を 運転【うんてん】する ことが できます。そして、京都【きょうと】へ 行【い】った ことが あります。",modelAnswerId:"Saya bisa menyetir mobil. Dan juga, saya pernah pergi ke Kyoto.",culturalEtiquette:"Gunakan bentuk kamus untuk dekiru dan bentuk-ta untuk koto ga aru.",skillUnlocked:["Menguasai pola kemampuan V-kamar + koto ga dekiru","Menguasai pola pengalaman hidup V-ta + koto ga aru"]},pocket_summary:{keyFormula:"[V-Kamus] ことが できます (bisa) / [V-ta] ことが あります (pernah)",coreWords:["うんてん","ふじさん","きょうと","のぼった"],coreWarning:'"Koto ga dekiru" = Verba Kamus. "Koto ga aru" = Verba Bentuk-Ta.',quickDialogue:"A: 食べたことが ありますか。 → B: はい、食べたことが あります。"}}},t={"les-n5-u13-01":{pedagogical_framework:{what:{summary:"Peralihan dari ragam sopan (Teineigo) ke bentuk biasa (普通形 Futsuukei): Bentuk Kamus (Kini/Masa Depan), Bentuk-Ta (Lampau), dan Bentuk Kehendak Kasual 〜よう (Ayo).",canDo:"Bisa mengobrol santai saat istirahat makan siang atau di asrama bersama rekan kerja sebaya.",targetPatterns:["[Verba Bentuk Biasa] (Futsuukei)","[Verba-ta] (Lampau biasa)","[Verba-you] (Ajakan kasual: 行こう / 食べよう)"],coreVocabSample:["いく","いった","いこう","たべる","たべた","たべよう"]},sensei_context:{sceneIntro:"Jam istirahat makan siang di kafetaria asrama. Kenji mengajak Budi mengobrol santai dengan ragam bahasa kasual tanpa desu/masu.",dailyMission:"Gunakan bentuk biasa (Futsuukei) kepada teman sebaya dan bentuk ajakan kasual 〜よう saat mengajak makan atau pergi.",whyOrder:"Setelah menguasai fondasi ragam sopan desu/masu (Unit 1–12), sekarang kita belajar bahasa pertemanan akrab agar bisa menjalin persahabatan sejati di Jepang."},cultural_notes:{title:"Batas Pemakaian Ragam Biasa (Tameguchi) di Jepang",etiquette:"Ragam biasa (Tameguchi) HANYA dipakai untuk teman sebaya, rekan yang seumuran dan sudah akrab, atau bawahan/anggota keluarga. Jangan pernah gunakan ragam biasa kepada atasan kerja atau orang yang baru dikenal!",taboos:'Dalam kalimat tanya bentuk biasa, partikel か dihilangkan dan diganti dengan intonasi naik di ujung kalimat: "食べる？" (bukan "食べるか").'},pronunciation_tips:{title:"Intonasi Pertanyaan Kasual",moraNote:'Pada kalimat tanya biasa "Iku?", intonasi dinaikkan tajam pada suku kata terakhir.',soundTip:'Katakan "Ikou yo!" dengan vokal ou panjang 2 mora.'},common_pitfalls:[{title:'Memakai Partikel "Ka" pada Percakapan Kasual',caseScenario:'Bertanya santai tapi menambahkan partikel ka: "Iku ka?".',pitfallWarning:'"どこ へ いく か。" (Terdengar kasar / menantang)',rightSolution:'"どこ いくの？" atau "どこ いく？" (Ramah & Alami)',explanation:"Partikel か pada bentuk biasa terdengar sangat maskulin dan kasar jika tidak dihaluskan menjadi の?."},{title:"Salah Menempatkan Ragam Biasa kepada Atasan",caseScenario:'Menjawab pertanyaan supervisor dengan bentuk biasa: "Un, itta".',pitfallWarning:'"うん、いった。" (Tidak sopan ke atasan)',rightSolution:'"はい、行【い】きました。" (Sopan)',explanation:'Kepada supervisor kerja wajib selalu menggunakan "Hai" dan bentuk sopan masu/desu.'}],who_and_when:{situational_context:"Mengobrol di kamar asrama bersama teman sebaya, nongkrong santai saat libur akhir pekan.",social_relations:"Eksklusif untuk rekan sebaya yang sudah akrab (in-group peer).",when_not_to_use:"DILARANG KERAS dipakai kepada atasan, senior, klien, atau orang asing."},scenario:{title:"Mengobrol Santai Saat Istirahat Bersama Kenji",setting:"Bangku taman depan asrama pekerja, pukul 12.45",narrative:"Kenji mengajak Budi makan ramen sore nanti setelah jam kerja selesai."}},dialogue:[{id:"d1",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"ブディ、今日【きょう】の 仕事【しごと】の あと、何【なに】か 予定【よてい】ある？",furigana:"ブディ、今日の 仕事の あと、何か 予定ある？",romaji:"Budi, kyou no shigoto no ato, nanika yotei aru?",idText:"Budi, setelah kerja hari ini ada acara apa?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"特【とく】に ないよ。部屋【へや】で 休【やす】む つもり。ケンジは？",furigana:"特に ないよ。部屋で 休む つもり。ケンジは？",romaji:"Toku ni nai yo. Heya de yasumu tsumori. Kenji wa?",idText:"Nggak ada hal khusus kok. Rencananya mau istirahat di kamar. Kalau Kenji?"},{id:"d3",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"駅前【えきまえ】に 新【あたら】しい ラーメン屋【や】が できたんだ。一緒【いっしょ】に 行【い】こうよ！",furigana:"駅前に 新しい ラーメン屋が できたんだ。一緒に 行こうよ！",romaji:"Ekimae ni atarashii ra-menya ga dekita n da. Issho ni ikou yo!",idText:"Di depan stasiun baru buka kedai ramen baru lho. Ayo kita pergi bareng!"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"いいね！何時【なんじ】頃【ごろ】行【い】く？",furigana:"いいね！何時頃行く？",romaji:"Ii ne! Nanji goro iku?",idText:"Wah asyik! Sekitar jam berapa perginya?"},{id:"d5",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"定時【ていじ】で 終【お】わったら、６時半【ろくじはん】に 寮【りょう】の ロビーで 会【あ】おう。",furigana:"定時で 終わったら、６時半に 寮の ロビーで 会おう。",romaji:"Teiji de owattara, rokujihan ni ryou no robi- de aou.",idText:"Kalau selesai tepat waktu, jam 6.30 ayo ketemu di lobi asrama."},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"了解【りょうかい】！昨日【きのう】も ラーメン 食【た】べたけど、全然【ぜんぜん】大丈夫【だいじょうぶ】！",furigana:"了解！昨日も ラーメン 食べたけど、全然大丈夫！",romaji:"Ryoukai! Kinou mo ra-men tabeta kedo, zenzen daijoubu!",idText:"Oke siap! Kemarin sih aku juga makan ramen, tapi sama sekali nggak masalah!"},{id:"d7",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"あはは、ラーメン 好【す】きだね！じゃあ、あとで ね！",furigana:"あはは、ラーメン 好きだね！じゃあ、あとで ね！",romaji:"Ahaha, ra-men suki da ne! Jaa, ato de ne!",idText:"Hahaha, doyan banget ramen ya! Sip, sampai nanti ya!"},{id:"d8",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"うん、また あとで！仕事【しごと】頑張【がんば】ろう！",furigana:"うん、また あとで！仕事頑張ろう！",romaji:"Un, mata ato de! Shigoto gambarou!",idText:"Sip, sampai nanti! Semangat kerjanya!"}],vocab_breakdown:[{id:"vg-n5-00004",word:"浴びる",reading:"あびる",romaji:"abiru",meaning:"mandi shower, terkena (sinar)",pos:"verb-ru",nuance:"シャワーを浴びる adalah kolokasi paling umum.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"毎朝シャワーを浴びます。",furigana:"毎朝シャワーを浴びます。",romaji:"",idText:"Setiap pagi saya mandi shower."}},{id:"vg-n5-00008",word:"言う",reading:"いう",romaji:"iu",meaning:"berkata, mengatakan",pos:"verb-u",nuance:"Sangat umum. Keigo: おっしゃる (sonkei), 申す (kenjo).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"何と言いましたか。",furigana:"何と言いましたか。",romaji:"",idText:"Apa yang kamu katakan?"}},{id:"vg-n5-00016",word:"消す",reading:"けす",romaji:"kesu",meaning:"mematikan; menghapus",pos:"verb-u",nuance:"聞く = mendengarkan (sengaja) ATAU bertanya. Konteks menentukan. Lawan: 聞こえる = terdengar.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"電気を消してください。",furigana:"電気を消してください。",romaji:"",idText:"Tolong matikan lampunya."}},{id:"vg-n5-00020",word:"する",reading:"する",romaji:"suru",meaning:"melakukan",pos:"verb-suru",nuance:"Irregular verb. Paling sering dipakai untuk suru-compound: 勉強する, 仕事する, dll.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"毎日運動します。",furigana:"毎日運動します。",romaji:"",idText:"Saya olahraga setiap hari."}},{id:"vg-n5-00025",word:"使う",reading:"つかう",romaji:"tsukau",meaning:"menggunakan",pos:"verb-u",nuance:"わかる = mengerti/paham (intransitif). Tidak ada objek-を; pakai が: 日本語がわかります.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"日本語を使って話してください。",furigana:"日本語を使って話してください。",romaji:"",idText:"Tolong bicara menggunakan bahasa Jepang."}},{id:"vg-n5-00036",word:"寝る",reading:"ねる",romaji:"neru",meaning:"tidur",pos:"verb-ru",nuance:"降りる = turun (dari kendaraan). 電車を降りる. Lawan: 乗る.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"１１時に寝ます。",furigana:"１１時に寝ます。",romaji:"",idText:"Saya tidur jam 11."}},{id:"vg-n5-00040",word:"借りる",reading:"かりる",romaji:"kariru",meaning:"meminjam",pos:"verb-ru",nuance:"Lawan: 貸す (meminjamkan).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"図書館で本を借りました。",furigana:"図書館で本を借りました。",romaji:"",idText:"Saya meminjam buku di perpustakaan."}},{id:"vg-n5-00052",word:"くれる",reading:"くれる",romaji:"kureru",meaning:"memberikan (ke saya)",pos:"verb-ru",nuance:"Keigo: くださる. Orang lain memberi ke speaker atau in-group.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"友達が本をくれました。",furigana:"友達が本をくれました。",romaji:"",idText:"Teman memberiku buku."}},{id:"vg-n5-00166",word:"違う",reading:"ちがう",romaji:"chigau",meaning:"berbeda, salah, tidak sama",pos:"verb-u",nuance:"Dua nuansa: berbeda (これは違う = ini berbeda) dan salah/tidak tepat (違います = itu salah). Lawan: 同じ.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"この答えは違います。",furigana:"この答えは違います。",romaji:"",idText:"Jawaban ini salah."}},{id:"vg-n5-00176",word:"おきる",reading:"おきる",romaji:"okiru",meaning:"bangun tidur",pos:"verb-ru",nuance:"Means both to wake up from sleep and to physically get up from a bed. Also used for things that 'happen' or 'occur'.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"毎朝七時に起きます。",furigana:"毎朝七時に起きます。",romaji:"",idText:"Setiap pagi saya bangun jam tujuh."}}],explanations:[{id:"exp-1",grammarId:"gn5-00028",title:"Pola: 〜た (lampau plain)",formula:"V → Vた",meaning:"lampau bentuk biasa",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜た (lampau plain)",idText:"lampau bentuk biasa"}],examples:[{jp:"きのうえいがをみた。",romaji:"",idText:"Kemarin nonton film."},{jp:"ごはんをたべた。",romaji:"",idText:"Sudah makan nasi."}]},{id:"exp-2",grammarId:"gn5-00042",title:"Pola: 〜ましょう",formula:"V-ます語幹 + ましょう",meaning:"ayo ... / mari ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜ましょう",idText:"ayo ... / mari ..."}],examples:[{jp:"いっしょにいきましょう！",romaji:"",idText:"Ayo pergi bersama!"},{jp:"もっとべんきょうしましょう。",romaji:"",idText:"Ayo belajar lebih giat."}]},{id:"exp-3",grammarId:"gn5-00043",title:"Pola: 〜ませんか",formula:"V-ます語幹 + ませんか",meaning:"maukah kamu ...? / bagaimana kalau kita ...?",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜ませんか",idText:"maukah kamu ...? / bagaimana kalau kita ...?"}],examples:[{jp:"いっしょにひるごはんをたべませんか。",romaji:"",idText:"Mau makan siang bersama?"},{jp:"えいがをみませんか。",romaji:"",idText:"Bagaimana kalau menonton film?"}]},{id:"exp-4",grammarId:"gn5-00044",title:"Pola: 〜ましょうか",formula:"V-ます語幹 + ましょうか",meaning:"maukah saya ...? / apakah kita ...?",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜ましょうか",idText:"maukah saya ...? / apakah kita ...?"}],examples:[{jp:"にもつをもちましょうか。",romaji:"",idText:"Mau saya bawakan barangnya?"},{jp:"どこへいきましょうか。",romaji:"",idText:"Kita mau ke mana?"}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Bentuk): Pilihlah padanan bentuk biasa kasual dari "行きます (ikimasu)".',sentencePrompt:'Bentuk kamus biasa dari "行きます" adalah:',options:["行【い】く","行【い】った","行【い】こう","行【い】かない"],correctAnswer:"行【い】く",explanation:'"行く (iku)" adalah bentuk kamus biasa dari 行きます (masa kini/akan datang).',diagnosticFeedback:{"行【い】った":"Salah: 行った adalah bentuk lampau (tadi sudah pergi).","行【い】こう":"Salah: 行こう adalah bentuk ajakan kasual (ayo pergi).","行【い】かない":"Salah: 行かない adalah bentuk sangkalan (tidak pergi)."}},{id:"drill-2",type:"cloze",instruction:'Langkah 2 (Isian Ajakan Kasual): Pilihlah bentuk ajakan kasual "ayo makan ramen bareng!".',sentencePrompt:"一緒【いっしょ】に ラーメンを 食【た】べ _____ よ！",options:["よう","る","た","ない"],correctAnswer:"よう",explanation:"Verba Golongan 2 (食べる) diubah ke bentuk kehendak/ajakan kasual menjadi 食べよう (ayo makan).",diagnosticFeedback:{る:"Salah: 食べる hanya bentuk kamus biasa.",た:"Salah: 食べた adalah bentuk lampau.",ない:"Salah: 食べない adalah bentuk sangkalan."}},{id:"drill-3",type:"reorder",instruction:'Langkah 3 (Susun Kalimat): Urutkan pertanyaan santai "setelah kerja ada acara apa?" berikut.',sentencePrompt:"Susunan kalimat yang tepat:",options:["仕事【しごと】の あと、何【なに】か 予定【よてい】ある？","予定【よてい】ある？ 仕事【しごと】の あと、何【なに】か","何【なに】か 予定【よてい】ある？ あと、仕事【しごと】の","仕事【しごと】の あと、ある 予定【よてい】何【なに】か？"],correctAnswer:"仕事【しごと】の あと、何【なに】か 予定【よてい】ある？",explanation:"Keterangan waktu (仕事のあと) + Objek (何か予定) + Verba Kasual naik intonasi (ある？).",diagnosticFeedback:{"予定【よてい】ある？ 仕事【しごと】の あと、何【なに】か":"Jebakan: Predikat di depan kalimat.","何【なに】か 予定【よてい】ある？ あと、仕事【しごと】の":"Jebakan: Susunan kata acak terbalik.","仕事【しごと】の あと、ある 予定【よてい】何【なに】か？":"Jebakan: Posisi kata kerja tertukar dengan objek."},tokens:["仕事【しごと】の","あと、何【なに】か","予定【よてい】ある？"],correctOrder:["0","1","2"]},{id:"drill-4",type:"trap_detect",instruction:"Langkah 4 (Deteksi Jebakan): Manakah etika berbicara yang benar saat ditanya oleh supervisor kerja?",sentencePrompt:'Jika Tanaka-senpai (supervisor) bertanya "明日来ますか", jawaban yang sopan adalah:',options:["はい、行【い】きます。","うん、いく。","いくよ。","いくだろう。"],correctAnswer:"はい、行【い】きます。",explanation:'Kepada supervisor kerja WAJIB selalu menjawab dengan "Hai" dan bentuk sopan ます (行きます).',diagnosticFeedback:{"うん、いく。":'Jebakan Fatal: "Un, iku" adalah ragam kasual yang sangat tidak sopan ke atasan.',"いくよ。":"Tidak sopan: Partikel yo kasual tanpa desu/masu.","いくだろう。":"Kasar dan terdengar menggurui atasan."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Saat teman akrab mengajak "一緒に ラーメン食べに行こうよ！", tanggapan santai yang pas adalah:',sentencePrompt:"Pilihlah respon santai pertemanan:",options:["いいね！何時【なんじ】頃【ごろ】行【い】く？","いいえ、食【た】べません。","ラーメンは さようなら。","行【い】きません、だめです。"],correctAnswer:"いいね！何時【なんじ】頃【ごろ】行【い】く？",explanation:'"いいね！何時頃行く？" (Boleh tuh! Jam berapa perginya?) adalah respons akrab alami.',diagnosticFeedback:{"いいえ、食【た】べません。":"Terlalu kaku dan menolak dingin ajakan teman akrab.","ラーメンは さようなら。":"Sayounara tidak nyambung dalam percakapan makan.","行【い】きません、だめです。":"Kasar dan merusak suasana pertemanan."}}],can_do_challenge:{statement:"Bisa mengobrol santai saat istirahat makan siang bersama rekan kerja sebaya.",situation:"Merencanakan makan bersama sepulang kerja dengan rekan satu asrama.",promptTask:"Ajak temanmu makan ramen bersama sepulang kerja dengan ragam bahasa biasa!",modelAnswer:"今日【きょう】の 仕事【しごと】の あと、一緒【いっしょ】に ラーメン 食【た】べに 行【い】こうよ！",modelAnswerId:"Setelah kerja hari ini, ayo kita pergi makan ramen bareng!",culturalEtiquette:"Gunakan bentuk 〜ようよ kepada teman sebaya yang sudah akrab.",skillUnlocked:["Menguasai peralihan Futsuukei kasual","Menguasai bentuk kehendak ajakan ikoukei kasual"]},pocket_summary:{keyFormula:"[V-Kamus] (Biasa) / [V-ta] (Lampau) / [V-you] (Ayo)",coreWords:["いく","いった","いこう","たべる"],coreWarning:"Ragam biasa hanya untuk teman sebaya akrab. Jangan pernah pakai ke atasan kerja!",quickDialogue:"A: ごはん 食べた？ → B: うん、食べたよ！"}},"les-n5-u13-02":{pedagogical_framework:{what:{summary:"Bentuk biasa sangkalan (ない形 Nai-kei), meminta agar tidak melakukan [Verba-nai] でください, dan melakukan sesuatu tanpa [Verba-nai] で.",canDo:"Bisa meminta tolong agar tidak khawatir, serta menceritakan kebiasaan melakukan aktivitas tanpa hal tertentu.",targetPatterns:["[Verba-nai] で ください (tolong jangan)","[Verba 1-nai] で [Verba 2] (melakukan V2 tanpa V1)","[Verba-nai] ずに (ragam tulis: tanpa)"],coreVocabSample:["しんぱいしないで","さとうをいれないで","わすれないで","のみます"]},sensei_context:{sceneIntro:"Budi sedang membuat kopi di ruang istirahat dan menanyakan preferensi gula rekan kerja. Sakura mengingatkan agar tidak lupa mematikan lampu mesin.",dailyMission:'Gunakan [Verba-nai] でください untuk mengingatkan hal penting, dan [Verba-nai] で untuk tindakan "tanpa".',whyOrder:"Bentuk negatif kasual (Nai-kei) adalah tiang penting untuk aturan pencegahan dan preferensi konsumsi."},cultural_notes:{title:"Aturan Konjugasi Bentuk-Nai Golongan 1",etiquette:'Pada verba Golongan 1, vokal akhir "u" bergeser ke baris "a" lalu ditambah nai: Kaku -> Kakanai, Nomu -> Nomanai. Pengecualian khusus: Kau -> KAWANAI (bukan kaanai).',taboos:'Kata kerja "あります (arimasu)" bentuk negatifnya BUKAN "aranai", melainkan langsung menjadi "ない (nai)"!'},pronunciation_tips:{title:"Irama Pelafalan Bentuk-Nai",moraNote:'Perhatikan kata "shinpaishinaide kudasai" diucapkan mengalir tanpa penekanan kasar.',soundTip:'Katakan "wasurenaide ne" dengan nada ramah peduli.'},common_pitfalls:[{title:"Salah Mengonjugasikan Verba Berakhiran U Murni",caseScenario:"Mengubah kau (membeli) menjadi kaanai.",pitfallWarning:'"かあない で ください。" (Salah Fatal)',rightSolution:'"かわない で ください。" (Benar: Kawanai)',explanation:"Verba berakhiran vokal u murni berubah menjadi wa: Kau -> Kawanai, Iu -> Iwanai."},{title:'Mengatakan "Aranai" untuk Bentuk Negatif Arimasu',caseScenario:"Mencoba membuat bentuk nai dari arimasu secara literal.",pitfallWarning:'"おかね が あらない。" (Salah Besar)',rightSolution:'"おかね が ない。" (Benar Mutlak)',explanation:"Bentuk negatif dari ある adalah ない."}],who_and_when:{situational_context:"Meminta rekan tidak khawatir, memesan makanan tanpa bahan alergen, pengingat kunci.",social_relations:"Sangat sering dipakai dalam interaksi kerja dan keseharian asrama.",when_not_to_use:"Jangan pakai bentuk nai-kudasai dengan intonasi membentak."},scenario:{title:"Membuat Kopi dan Mengingatkan Kunci Kantor",setting:"Pantry kantor menjelang pulang kerja, pukul 17.15",narrative:"Budi membuatkan kopi untuk Sakura dan memastikan preferensi gula, sementara Sakura mengingatkan jadwal kunci pintu."}},dialogue:[{id:"d1",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"さくらさん、コーヒーを 淹【い】れましょうか。砂糖【さとう】は 入【い】れますか。",furigana:"さくらさん、コーヒーを 淹れましょうか。砂糖は 入れますか。",romaji:"Sakura-san, ko-hi- o iremashou ka. Satou wa iremasu ka.",idText:"Sakura-san, bagaimana kalau saya buatkan kopi? Mau dimasukkan gula?"},{id:"d2",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"ありがとう！砂糖【さとう】は 入【い】れないで、ブラックで 飲【の】みます。",furigana:"ありがとう！砂糖は 入れないで、ブラックで 飲みます。",romaji:"Arigatou! Satou wa irenaide, burakku de nomimasu.",idText:"Terima kasih! Jangan masukkan gula ya, saya minum kopi hitam."},{id:"d3",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】しました。砂糖【さとう】を 入【い】れないで 淹【い】れますね。",furigana:"承知しました。砂糖を 入れないで 淹れますね。",romaji:"Shouchi shimashita. Satou o irenaide iremasu ne.",idText:"Saya pahami. Saya buatkan tanpa memasukkan gula ya."},{id:"d4",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"あと、今日【きょう】は 最後【さいご】の 人【ひと】だから、窓【まど】の 鍵【かぎ】を 忘【わす】れないでね。",furigana:"あと、今日は 最後の 人だから、窓の 鍵を 忘れないでね。",romaji:"Ato, kyou wa saigo no hito da kara, mado no kagi o wasurenaide ne.",idText:"Satu lagi, karena kamu orang terakhir hari ini, jangan lupa kunci jendela ya."},{id:"d5",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、心配【しんぱい】しないでください。しっかり 確認【かくにん】します！",furigana:"はい、心配しないでください。しっかり 確認します！",romaji:"Hai, shinpai shinaide kudasai. Shikkari kakunin shimasu!",idText:"Baik, tolong jangan khawatir. Saya akan periksa dengan teliti!"},{id:"d6",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"無理【むり】を しないで、早【はや】く 帰【かえ】って 休【やす】んでくださいね。",furigana:"無理を しないで、早く 帰って 休んでくださいね。",romaji:"Muri o shinaide, hayaku kaette yasunde kudasai ne.",idText:"Jangan memaksakan diri, cepatlah pulang dan istirahat ya."},{id:"d7",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"田中【たなか】さんも お疲【つか】れ様【さま】でした。お先【さき】に 失礼【しつれい】します！",furigana:"田中さんも お疲れ様でした。お先に 失礼します！",romaji:"Tanaka-san mo otsukaresama deshita. Osaki ni shitsurei shimasu!",idText:"Tanaka-san juga terima kasih atas kerja kerasnya. Saya pamit duluan ya!"},{id:"d8",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"お疲【つか】れ様【さま】！気【き】をつけて 帰【かえ】ってね。",furigana:"お疲れ様！気を つけて 帰ってね。",romaji:"Otsukaresama! Ki o tsukete kaette ne.",idText:"Terima kasih atas kerja kerasnya! Hati-hati di jalan ya."}],vocab_breakdown:[{id:"vg-n5-01168",word:"先週",reading:"せんしゅう",romaji:"senshuu",meaning:"minggu lalu",pos:"adverb",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"あの人は先週ここにいた人です。",furigana:"あの人は先週ここにいた人です。",romaji:"",idText:"Dialah pria yang ada di sini minggu lalu."}},{id:"vg-n5-01188",word:"違う",reading:"ちがう",romaji:"chigau",meaning:"berbeda",pos:"verb-u",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"ライオンとヒョウの違いは何ですか。",furigana:"ライオンとヒョウの違いは何ですか。",romaji:"",idText:"What's the difference between lions and leopards?"}},{id:"vg-n5-01219",word:"取る",reading:"とる",romaji:"toru",meaning:"mengambil",pos:"verb-u",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"そのお金はいざというときのために取っておくよ。",furigana:"そのお金はいざというときのために取っておくよ。",romaji:"",idText:"Saya akan menyisihkan uang itu untuk keadaan darurat."}},{id:"vg-n5-01221",word:"鳴く",reading:"なく",romaji:"naku",meaning:"berbunyi",pos:"verb-u",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"カエルが鳴いたら帰ろう。",furigana:"カエルが鳴いたら帰ろう。",romaji:"",idText:"Let's return when the frog croaks."}},{id:"vg-n5-01233",word:"脱ぐ",reading:"ぬぐ",romaji:"nugu",meaning:"melepas pakaian",pos:"verb-u",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"ここで靴を脱がなければなりませんか。",furigana:"ここで靴を脱がなければなりませんか。",romaji:"",idText:"Do I have to take off my shoes here?"}},{id:"vg-n5-01245",word:"働く",reading:"はたらく",romaji:"hataraku",meaning:"bekerja",pos:"verb-u",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"スイッチは時間通りに働かなかった。",furigana:"スイッチは時間通りに働かなかった。",romaji:"",idText:"The switch didn't work on time."}},{id:"vg-n5-01254",word:"弾く",reading:"ひく",romaji:"hiku",meaning:"memetik / memainkan alat musik dawai",pos:"verb-u",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"ギターをひくのはおもしろい。",furigana:"ギターをひくのはおもしろい。",romaji:"",idText:"Bermain gitar itu menyenangkan."}},{id:"vg-n5-01315",word:"旅行",reading:"りょこう",romaji:"ryokou",meaning:"perjalanan",pos:"verb-suru",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"いつ旅行においでになりますか。",furigana:"いつ旅行においでになりますか。",romaji:"",idText:"When will you go on a journey?"}},{id:"vg-n5-01321",word:"渡す",reading:"わたす",romaji:"watasu",meaning:"menyerahkan",pos:"verb-u",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"わたしを川のむこうに渡してください。",furigana:"わたしを川のむこうに渡してください。",romaji:"",idText:"Tolong take me across the river."}},{id:"vg-n5-00486",word:"新聞",reading:"しんぶん",romaji:"shinbun",meaning:"koran",pos:"noun",nuance:"新聞を読む = membaca koran. 新聞社 = perusahaan surat kabar.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"毎朝新聞を読みます。",furigana:"毎朝新聞を読みます。",romaji:"",idText:"Setiap pagi saya membaca koran."}}],explanations:[{id:"exp-1",grammarId:"gn5-00027",title:"Pola: 〜ない (negatif plain)",formula:"V → Vない",meaning:"negatif bentuk biasa",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜ない (negatif plain)",idText:"negatif bentuk biasa"}],examples:[{jp:"あまりテレビをみない。",romaji:"",idText:"Tidak terlalu sering nonton TV."},{jp:"きょうはいかないつもりです。",romaji:"",idText:"Berencana tidak pergi hari ini."}]},{id:"exp-2",grammarId:"gn5-00035",title:"Pola: 〜ないで",formula:"Vない + で",meaning:"tanpa melakukan ... / jangan ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜ないで",idText:"tanpa melakukan ... / jangan ..."}],examples:[{jp:"なにもたべないでねてしまった。",romaji:"",idText:"Tertidur tanpa makan apapun."},{jp:"ここでおよがないでください。",romaji:"",idText:"Tolong jangan berenang di sini."}]},{id:"exp-3",grammarId:"gn5-00077",title:"Pola: Vる つもり",formula:"Vる / Vない + つもりです",meaning:"berencana untuk ... / bermaksud ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"Vる つもり",idText:"berencana untuk ... / bermaksud ..."}],examples:[{jp:"らいねんにほんへいくつもりです。",romaji:"",idText:"Berencana pergi ke Jepang tahun depan."},{jp:"もうやめるつもりはないです。",romaji:"",idText:"Tidak bermaksud berhenti."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Kata): Pilihlah arti kata "心配 (しんぱい)".',sentencePrompt:'Kata "心配" memiliki arti:',options:["Khawatir / Cemas","Gembira / Senang","Marah / Kesal","Lapar / Dahaga"],correctAnswer:"Khawatir / Cemas",explanation:'"心配 (しんぱい)" berarti rasa cemas atau khawatir.',diagnosticFeedback:{"Gembira / Senang":"Salah: Gembira adalah 嬉しい (ureshii).","Marah / Kesal":"Salah: Marah adalah 怒る (okoru).","Lapar / Dahaga":"Salah: Lapar adalah 空腹 (kuufuku)."}},{id:"drill-2",type:"cloze",instruction:'Langkah 2 (Isian Rumus Larangan Halus): Pilihlah pola untuk menyatakan "tolong jangan khawatir".',sentencePrompt:"どうぞ 心配【しんぱい】_____ ください。",options:["しないで","するで","してで","したで"],correctAnswer:"しないで",explanation:"Pola permohonan agar tidak melakukan sesuatu adalah [Verba-nai] + で ください: しないでください.",diagnosticFeedback:{するで:"Salah: Bentuk kamus tidak bisa digabung langsung dengan de kudasai.",してで:"Salah: Bentuk-te tidak digabung dengan de kudasai.",したで:"Salah: Bentuk lampau salah untuk pola ini."}},{id:"drill-3",type:"reorder",instruction:"Langkah 3 (Susun Kalimat): Urutkan kalimat yang menyatakan minum kopi tanpa gula berikut.",sentencePrompt:"Susunan kalimat yang tepat:",options:["砂糖【さとう】を 入【い】れないで 飲【の】みます","入【い】れないで 砂糖【さとう】を 飲【の】みます","飲【の】みます 砂糖【さとう】を 入【い】れないで","砂糖【さとう】を 飲【の】みます 入【い】れないで"],correctAnswer:"砂糖【さとう】を 入【い】れないで 飲【の】みます",explanation:"Objek yang dihindari (砂糖を) + Tanpa aksi (入れないで) + Aksi utama (飲みます).",diagnosticFeedback:{"入【い】れないで 砂糖【さとう】を 飲【の】みます":"Kurang tepat: Objek yang dihindari sebaiknya mendahului verba negatifnya.","飲【の】みます 砂糖【さとう】を 入【い】れないで":"Jebakan: Kata kerja di awal kalimat.","砂糖【さとう】を 飲【の】みます 入【い】れないで":"Jebakan: Pola tindakan tanpa terbelah."},tokens:["砂糖【さとう】を","入【い】れないで","飲【の】みます"],correctOrder:["0","1","2"]},{id:"drill-4",type:"trap_detect",instruction:'Langkah 4 (Deteksi Jebakan): Manakah bentuk sangkalan dari kata kerja "買います (kaimasu)" yang benar?',sentencePrompt:'Bentuk-nai yang benar dari "買います" adalah:',options:["買【か】わない","買【か】あない","買【か】きない","買【か】しない"],correctAnswer:"買【か】わない",explanation:"Verba golongan 1 berakhiran vokal u murni berubah menjadi wa: kaimasu -> kawanai.",diagnosticFeedback:{"買【か】あない":'Jebakan Fatal: "Kaanai" adalah kesalahan fatal yang sering dilakukan pemula.',"買【か】きない":"Jebakan: Akhiran kinai tidak ada dalam konjugasi.","買【か】しない":"Jebakan: Akhiran shinai hanya untuk kata kerja suru."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Saat supervisor mengingatkan "無理をしないで、早く帰って休んでね", tanggapan sopan saat pamit adalah:',sentencePrompt:"Pilihlah ungkapan pamit pulang yang tepat:",options:["ありがとうございます。お先【さき】に 失礼【しつれい】します！","いいえ、だめです。","さようなら、明日【あした】来【こ】ないで。","仕事【しごと】は ありません。"],correctAnswer:"ありがとうございます。お先【さき】に 失礼【しつれい】します！",explanation:'Mengucapkan terima kasih atas perhatian dan berpamitan pulang dengan "Osaki ni shitsurei shimasu".',diagnosticFeedback:{"いいえ、だめです。":"Menolak perhatian atasan dengan ketus.","さようなら、明日【あした】来【こ】ないで。":"Sangat lancang menyuruh atasan jangan datang besok.","仕事【しごと】は ありません。":"Tidak nyambung dengan etika pamit pulang."}}],can_do_challenge:{statement:"Bisa meminta rekan kerja agar tidak cemas dan mematuhi pengingat keselamatan.",situation:"Menegaskan kepada senior kantor bahwa kamu sudah memahami prosedur.",promptTask:"Katakan kepada supervisor agar jangan cemas karena kamu akan mengeceknya dengan teliti!",modelAnswer:"心配【しんぱい】しないでください。しっかり 確認【かくにん】します。",modelAnswerId:"Tolong jangan khawatir. Saya akan memeriksanya dengan sungguh-sungguh.",culturalEtiquette:'Ucapkan "Shinpai shinaide kudasai" dengan nada meyakinkan dan santun.',skillUnlocked:["Menguasai konjugasi bentuk-nai","Menguasai pola larangan halus [V-nai] de kudasai dan kondisi [V-nai] de"]},pocket_summary:{keyFormula:"[V-nai] で ください (Tolong jangan) / [V1-nai] で [V2] (Melakukan V2 tanpa V1)",coreWords:["しんぱい","わすれないで","はいらないで","むり"],coreWarning:'Verba berakhiran vokal u murni berubah menjadi "wanai" (kawanai), bukan "aanai".',quickDialogue:"A: 忘れないでね。 → B: はい、心配しないでください！"}}},r={"les-n5-u14-01":{pedagogical_framework:{what:{summary:"Menjelaskan alasan logis dengan から (subjektif/personal), alasan sopan objektif dengan ので (halus/faktual), dan penjelas konteks wacana 〜んです / 〜のです.",canDo:"Bisa menjelaskan alasan terlambat, memohon izin tidak masuk, atau menerangkan situasi kerja secara masuk akal.",targetPatterns:["[Alasan] から、[Akibat]","[Alasan] ので、[Akibat]","[Bentuk Biasa] んです (penjelasan latar belakang)"],coreVocabSample:["から","ので","あたまがいたいんです","ねつがあります","おくれます"]},sensei_context:{sceneIntro:"Pagi hari, Budi bangun tidur dengan badan demam dan kepala pusing. Dia harus menelepon Tanaka-senpai untuk mengabarkan kondisi sakitnya.",dailyMission:"Mampu menjelaskan alasan kondisi kesehatan dengan 〜んです dan memohon izin sakit menggunakan 〜ので.",whyOrder:"Komunikasi absensi kerja (Kesseki Renraku) adalah keterampilan bertahan hidup paling krusial bagi pekerja asing di Jepang."},cultural_notes:{title:"Etika Menghubungi Kantor Saat Sakit (欠勤連絡 - Kekkin Renraku)",etiquette:"Jangan hanya kirim pesan teks singkat! Selalu telepon atasan minimal 15–30 menit sebelum jam kerja dimulai, jelaskan gejala sakit dengan sopan, dan minta maaf atas kendala yang ditimbulkan.",taboos:'Jangan gunakan "kara" yang terkesan menyalahkan keadaan kepada atasan; gunakan "node" yang bernuansa objektif dan sopan.'},pronunciation_tips:{title:"Pelafalan Partikel Penjelas 〜んです",moraNote:'Pada frasa "atama ga itai n desu", huruf n mendapat 1 ketukan mora hening sebelum desu.',soundTip:'Katakan "netsu ga aru node" dengan nada bersalah dan sopan.'},common_pitfalls:[{title:'Memakai "Kara" Terlalu Keras Saat Izin ke Atasan',caseScenario:"Mengatakan alasan izin sakit dengan kara secara kaku.",pitfallWarning:'"あたま が いたい から、やすみます。" (Terdengar menuntut)',rightSolution:'"あたま が いたい ので、休【やす】ませて いただけませんか。" (Sopan & Rendah Hati)',explanation:"Partikel ので melunakkan hubungan sebab-akibat menjadi fakta objektif yang santun."},{title:'Menggunakan "Ndesu" Tanpa Bentuk Biasa yang Benar',caseScenario:'Menggabungkan desu dengan ndesu: "itai desu ndesu".',pitfallWarning:'"いたい です んです。" (Salah)',rightSolution:'"いたい んです。" (Benar - Langsung Futsuukei)',explanation:"Pola 〜んです menuntut bentuk biasa langsung: Itai + んです."}],who_and_when:{situational_context:"Menelepon atasan saat sakit, mengabarkan keterlambatan kereta, menjelaskan alasan keputusan.",social_relations:"Sangat krusial dalam etika komunikasi Hou-Ren-So di perusahaan Jepang.",when_not_to_use:"Jangan berdalih bohong dengan ndesu; sampaikan fakta sebenarnya."},scenario:{title:"Telepon Izin Sakit ke Kantor Pagi Hari",setting:"Kamar asrama Budi pukul 08.15, menelepon kantor",narrative:"Budi menelepon Tanaka-senpai untuk mengabarkan bahwa ia demam tinggi dan memohon izin ke klinik dokter."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"はい、タナカ製作所【せいさくしょ】の 田中【たなか】です。",furigana:"はい、タナカ製作所の 田中です。",romaji:"Hai, Tanaka Seisakusho no Tanaka desu.",idText:"Halo, dengan Tanaka dari Bengkel Manufaktur Tanaka."},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"おはようございます。実習生【じっしゅうせい】の ブディです。今【いま】お時間【じかん】よろしいでしょうか。",furigana:"おはようございます。実習生の ブディです。今お時間よろしいでしょうか。",romaji:"Ohayou gozaimasu. Jisshuusei no Budi desu. Ima ojikan yoroshii deshou ka.",idText:"Selamat pagi. Saya Budi peserta magang. Apakah sekarang ada waktu sebentar?"},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"おはよう、ブディさん。どうしましたか。声【こえ】が 辛【つら】そうですね。",furigana:"おはよう、ブディさん。どうしましたか。声が 辛そうですね。",romaji:"Ohayou, Budi-san. Dou shimashita ka. Koe ga tsurasou desu ne.",idText:"Selamat pagi, Budi-san. Ada apa? Suaramu terdengar payah ya."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、朝【あさ】から 頭【あたま】が 痛【いた】くて、３８度【さんじゅうはちど】の 熱【ねつ】が あるんです。",furigana:"はい、朝から 頭が 痛くて、３８度の 熱が あるんです。",romaji:"Hai, asa kara atama ga itakute, sanjuuhachido no netsu ga aru n desu.",idText:"Iya, sejak pagi kepala saya pusing dan ada demam 38 derajat."},{id:"d5",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"それは 大変【たいへん】ですね。病院【びょういん】へ 行【い】きますか。",furigana:"それは 大変ですね。病院へ 行きますか。",romaji:"Sore wa taihen desu ne. Byouin e ikimasu ka.",idText:"Wah gawat itu ya. Apakah kamu akan pergi ke rumah sakit/klinik?"},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、これから 病院【びょういん】へ 行【い】くので、今日【きょう】は 休【やす】ませて いただけないでしょうか。",furigana:"はい、これから 病院へ 行くので、今日は 休ませて いただけないでしょうか。",romaji:"Hai, kore kara byouin e iku node, kyou wa yasumasete itadakenai deshou ka.",idText:"Iya, karena setelah ini saya mau ke rumah sakit, apakah hari ini saya diperkenankan izin libur?"},{id:"d7",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"わかりました。仕事【しごと】の 心配【しんぱい】は しないで、しっかり 診【み】てもらってください。",furigana:"わかりました。仕事の 心配は しないで、しっかり 診てもらってください。",romaji:"Wakarimashita. Shigoto no shinpai wa shinaide, shikkari mite moratte kudasai.",idText:"Saya pahami. Jangan khawatirkan pekerjaan, periksakanlah ke dokter dengan baik ya."},{id:"d8",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"ご迷惑【めいわく】を おかけして すみません。診察【しんさつ】の あと、また 連絡【れんらく】します。",furigana:"ご迷惑を おかけして すみません。診察の あと、また 連絡します。",romaji:"Gomeiwaku o okake shite sumimasen. Shinsatsu no ato, mata renraku shimasu.",idText:"Mohon maaf telah merepotkan. Setelah pemeriksaan dokter, saya akan berkabar lagi."}],vocab_breakdown:[{id:"vg-n5-00206",word:"なく",reading:"なく",romaji:"naku",meaning:"menangis",pos:"verb-u",nuance:"Refers to crying or weeping (humans) or making a sound (animals, like barking or meowing). Kanji differs: 泣く for humans, 鳴く for animals.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"悲しい映画を見て泣きました。",furigana:"悲しい映画を見て泣きました。",romaji:"",idText:"Saya menangis menonton film sedih."}},{id:"vg-n5-00396",word:"メール",reading:"メール",romaji:"meeru",meaning:"email; pesan",pos:"verb-suru",nuance:"A loanword meaning email or text message. To send an email, you say メールを送る or メールする.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"後でメールします。",furigana:"後でメールします。",romaji:"",idText:"Nanti saya email."}},{id:"vg-n5-00484",word:"安心する",reading:"あんしんする",romaji:"anshinsuru",meaning:"merasa lega",pos:"verb-suru",nuance:"安心する = lega/merasa tenang setelah khawatir. Lawan: 心配する.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"元気だと聞いて安心しました。",furigana:"元気だと聞いて安心しました。",romaji:"",idText:"Saya lega mendengar kabar kamu baik-baik saja."}},{id:"vg-n5-00768",word:"～がる",reading:"～がる",romaji:"-garu",meaning:"tampak merasa ..., bersikap ... (menunjukkan rasa)",pos:"verb-u",nuance:"Sufiks verba godan yang ditempelkan pada kata sifat-i/na atau pola keinginan ~たい untuk menyatakan emosi/keinginan pihak ketiga (orang lain) yang terlihat dari perilakunya (contoh: 欲しがる = tampak menginginkan; 寂しがる = tampak kesepian). Jangan dipakai untuk diri sendiri.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"妹は新しいおもちゃを欲しがっています。",furigana:"妹は新しいおもちゃを欲しがっています。",romaji:"",idText:"Adik perempuan saya tampak sangat menginginkan mainan baru."}},{id:"vg-n5-00820",word:"質問",reading:"しつもん",romaji:"shitsumon",meaning:"pertanyaan; bertanya",pos:"verb-suru",nuance:"Digunakan saat menanyakan hal yang belum dimengerti atau meminta kejelasan informasi. Sering memakai kata kerja 質問する atau frasa 質問がある. Berbeda dengan 問題 (mondai) yang berarti soal ujian atau permasalahan hidup.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"分からないところがあれば先生に質問してください。",furigana:"分からないところがあれば先生に質問してください。",romaji:"",idText:"Jika ada bagian yang belum dimengerti, silakan ajukan pertanyaan kepada guru."}},{id:"vg-n5-00868",word:"疲れる",reading:"つかれる",romaji:"tsukareru",meaning:"lelah, capek, letih",pos:"verb-ru",nuance:"Kata kerja ichidan (一段動詞). Dalam percakapan sehari-hari hampir selalu digunakan dalam bentuk lampau/status 疲れました (tsukaremashita / saya lelah) atau 疲れている (tsukarete iru / sedang dalam keadaan lelah) untuk menyatakan kondisi lelah fisik atau mental saat ini.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"今日はたくさん歩いたので、とても疲れました。",furigana:"今日はたくさん歩いたので、とても疲れました。",romaji:"",idText:"Hari ini karena banyak berjalan kaki, saya sangat lelah."}},{id:"vg-n5-00996",word:"あさって",reading:"あさって",romaji:"asatte",meaning:"lusa",pos:"adverb",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"あさって彼にここへ来てもらうつもりです。",furigana:"あさって彼にここへ来てもらうつもりです。",romaji:"",idText:"Saya akan menyuruhnya datang ke sini lusa."}},{id:"vg-n5-01008",word:"あまり",reading:"あまり",romaji:"amari",meaning:"tidak begitu",pos:"adverb",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"この手の本はあまり読まない。",furigana:"この手の本はあまり読まない。",romaji:"",idText:"I don't read this kind of book much."}},{id:"vg-n5-01185",word:"だんだん",reading:"だんだん",romaji:"dandan",meaning:"berangsur-angsur",pos:"adverb",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"日がだんだん長くなってきています。",furigana:"日がだんだん長くなってきています。",romaji:"",idText:"Hari-hari menjadi semakin panjang."}},{id:"vg-n5-01249",word:"春",reading:"はる",romaji:"haru",meaning:"musim semi",pos:"adverb",nuance:"Kosakata level N5: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"カッコウは春にここにやってくる。",furigana:"カッコウは春にここにやってくる。",romaji:"",idText:"Cuckoos visit here in spring."}}],explanations:[{id:"exp-1",grammarId:"gn5-00065",title:"Pola: 〜から (alasan)",formula:"文 (plain/polite) + から",meaning:"karena ... (alasan)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜から (alasan)",idText:"karena ... (alasan)"}],examples:[{jp:"あめがふっているから、でかけません。",romaji:"",idText:"Karena sedang hujan, tidak keluar."},{jp:"びょうきですから、がっこうをやすみます。",romaji:"",idText:"Karena sakit, tidak masuk sekolah."}]},{id:"exp-2",grammarId:"gn5-00066",title:"Pola: 〜ので",formula:"V/Adj plain + ので / N/Adj-na + な + ので",meaning:"karena ... (alasan sopan)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜ので",idText:"karena ... (alasan sopan)"}],examples:[{jp:"あしたしけんがあるので、はやくねます。",romaji:"",idText:"Karena besok ada ujian, tidur lebih awal."},{jp:"いそがしいので、てつだえません。",romaji:"",idText:"Karena sibuk, tidak bisa membantu."}]},{id:"exp-3",grammarId:"gn5-00076",title:"Pola: 〜し",formula:"V/Adj plain / N (+ だ) + し",meaning:"dan juga ... (menghubungkan alasan)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜し",idText:"dan juga ... (menghubungkan alasan)"}],examples:[{jp:"やすいし、おいしいし、このみせがすきです。",romaji:"",idText:"Karena murah dan enak, suka toko ini."},{jp:"あめだし、つかれてるし、でかけたくない。",romaji:"",idText:"Hujan, capek, tidak mau keluar."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Gejala): Pilihlah arti kata "熱 (ねつ)".',sentencePrompt:'Kata "熱がある" artinya adalah:',options:["Demam / Panas badan","Sakit gigi","Batuk kering","Keseleo pergelangan"],correctAnswer:"Demam / Panas badan",explanation:'"熱 (ねつ)" berarti demam atau panas suhu tubuh.',diagnosticFeedback:{"Sakit gigi":"Salah: Sakit gigi adalah 虫歯 (mushiba) atau 歯が痛い.","Batuk kering":"Salah: Batuk adalah 咳 (seki).","Keseleo pergelangan":"Salah: Keseleo adalah 捻挫 (nenza)."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Isian Alasan Objektif): Pilihlah partikel penanda alasan santun objektif.",sentencePrompt:"熱【ねつ】が ある _____、今日【きょう】は 休【やす】みます。",options:["ので","より","でも","まで"],correctAnswer:"ので",explanation:"Alasan santun dan objektif yang sopan kepada atasan ditandai dengan ので: 熱がある node.",diagnosticFeedback:{より:"Salah: より digunakan untuk perbandingan.",でも:"Salah: でも berarti walaupun / tetapi.",まで:"Salah: まで menandai batas akhir."}},{id:"drill-3",type:"reorder",instruction:"Langkah 3 (Susun Kalimat): Urutkan penjelasan gejala sakit kepala dengan pola 〜んです berikut.",sentencePrompt:"Susunan kalimat yang tepat:",options:["朝【あさ】から 頭【あたま】が 痛【いた】いんです","頭【あたま】が 朝【あさ】から 痛【いた】いんです","痛【いた】いんです 朝【あさ】から 頭【あたま】が","朝【あさ】から 痛【いた】いんです 頭【あたま】が"],correctAnswer:"朝【あさ】から 頭【あたま】が 痛【いた】いんです",explanation:"Keterangan waktu (朝から) + Subjek keluhan (頭が) + Predikat penjelas (痛いんです).",diagnosticFeedback:{"頭【あたま】が 朝【あさ】から 痛【いた】いんです":"Bisa dipahami namun keterangan waktu biasanya mengawali kalimat.","痛【いた】いんです 朝【あさ】から 頭【あたま】が":"Jebakan: Kata sifat di awal kalimat.","朝【あさ】から 痛【いた】いんです 頭【あたま】が":"Jebakan: Subjek di belakang kata sifat."},tokens:["朝【あさ】から","頭【あたま】が","痛【いた】いんです"],correctOrder:["0","1","2"]},{id:"drill-4",type:"trap_detect",instruction:"Langkah 4 (Deteksi Jebakan): Manakah permohonan izin sakit kepada atasan yang paling santun?",sentencePrompt:"Pilihlah kalimat memohon izin sakit yang paling santun:",options:["病院【びょういん】へ 行【い】くので、休【やす】ませて いただけないでしょうか。","病院【びょういん】へ 行【い】くから、休【やす】みます。","休【やす】みたいから、仕事【しごと】は だめです。","熱【ねつ】が ある、さようなら。"],correctAnswer:"病院【びょういん】へ 行【い】くので、休【やす】ませて いただけないでしょうか。",explanation:'Menggunakan "node" dan permohonan sangat santun "yasumasete itadakenai deshou ka".',diagnosticFeedback:{"病院【びょういん】へ 行【い】くから、休【やす】みます。":"Jebakan: Terdengar menuntut sepihak tanpa memohon izin.","休【やす】みたいから、仕事【しごと】は だめです。":"Sangat kasar dan tidak sopan.","熱【ねつ】が ある、さようなら。":"Sangat tidak profesional memutuskan telepon secara sepihak."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Saat atasan berkata "しっかり病院で診てもらってください", respon penutup yang benar adalah:',sentencePrompt:"Pilihlah respon menutup pembicaraan telepon sakit:",options:["ご迷惑【めいわく】を おかけして すみません。診察【しんさつ】の あと、また 連絡【れんらく】します。","はい、知【し】りません。","だめです、行【い】きません。","お疲【つか】れ様【さま】、さようなら。"],correctAnswer:"ご迷惑【めいわく】を おかけして すみません。診察【しんさつ】の あと、また 連絡【れんらく】します。",explanation:"Meminta maaf atas ketidaknyamanan dan berjanji akan mengabari hasil diagnosa dokter.",diagnosticFeedback:{"はい、知【し】りません。":"Tidak nyambung sama sekali.","だめです、行【い】きません。":"Membantah saran dokter atasan secara kasar.","お疲【つか】れ様【さま】、さようなら。":"Otsukaresama tidak digunakan bawahan ke atasan saat izin sakit."}}],can_do_challenge:{statement:"Bisa menjelaskan alasan sakit dan memohon izin kerja secara masuk akal.",situation:"Menelepon atasan kantor saat mengalami demam di pagi hari.",promptTask:"Telepon atasan, jelaskan bahwa kamu demam dan mohon izin periksa ke dokter!",modelAnswer:"熱【ねつ】が あるので、今日【きょう】は 病院【びょういん】へ 行【い】かせて いただけないでしょうか。",modelAnswerId:"Karena saya demam, apakah hari ini saya diperkenankan izin pergi ke rumah sakit?",culturalEtiquette:"Gunakan partikel node dan ungkapkan rasa maaf atas kendala yang ditimbulkan.",skillUnlocked:["Menguasai etika izin sakit telepon Hou-Ren-So","Membedakan partikel alasan kara dan node"]},pocket_summary:{keyFormula:"[Alasan] ので、[Permohonan] / [Bentuk Biasa] んです",coreWords:["ねつ","あたまがいたい","ので","から"],coreWarning:'Gunakan "node" bukan "kara" saat izin sakit ke atasan. Akhiri dengan permohonan santun.',quickDialogue:"A: どうしたんですか。 → B: 熱があるんです。"}},"les-n5-u14-02":{pedagogical_framework:{what:{summary:"Penyambung kontras percakapan 〜けど (tapi / permisi), menyatakan opini pribadi [Bentuk Biasa] と思います (menurut saya), dan mengutip perkataan orang lain [Bentuk Biasa] と言いました (berkata bahwa).",canDo:"Bisa menyampaikan pendapat dalam rapat singkat dan meneruskan pesan dari supervisor.",targetPatterns:["[Bentuk Biasa] と 思います (saya rasa / menurut saya)","[Bentuk Biasa] と 言いました (berkata bahwa)","〜けど、〜 (tapi / sebagai pengantar)"],coreVocabSample:["おもいます","いいました","いけん","あした","はれる"]},sensei_context:{sceneIntro:"Saat briefing sore atau rapat harian, Budi dimintai pendapat mengenai jadwal pameran dan meneruskan pesan dari Tanaka-buchou.",dailyMission:"Gunakan 〜と思います saat mengutarakan opini pribadi agar tidak terkesan memaksakan kehendak, dan 〜と言いました untuk mengutip pesan.",whyOrder:"Orang Jepang jarang menyatakan fakta secara absolut tanpa penghalus. Pola と思います adalah pelumas sosial agar opini terdengar santun."},cultural_notes:{title:"Kearifan Menghaluskan Opini (和 - Wa & 断定回避)",etiquette:'Menyatakan "Kore wa ii desu" (Ini bagus) terdengar kaku dan mutlak. Orang Jepang lebih memilih "Kore wa ii to omoimasu" (Menurut saya ini bagus) untuk memberi ruang diskusi bagi lawan bicara.',taboos:"Kalimat sebelum と思います dan と言いました WAJIB berada dalam BENTUK BIASA (Futsuukei), bukan bentuk desu/masu!"},pronunciation_tips:{title:"Irama Pengutipan と思います",moraNote:'Tidak ada jeda panjang antara partikel to dan omoimasu: "da to omoimasu" menyatu harmonis.',soundTip:'Katakan "ashita wa hare da to omoimasu" dengan nada wajar.'},common_pitfalls:[{title:'Memasukkan Bentuk Desu/Masu Sebelum "To Omoimasu"',caseScenario:'Mengatakan: "ii desu to omoimasu".',pitfallWarning:'"いい です と おもいます。" (Salah)',rightSolution:'"いい と おもいます。" (Benar - Futsuukei)',explanation:"Klausa yang dikutip dengan partikel と WAJIB menggunakan Bentuk Biasa (Futsuukei)."},{title:'Lupa Menambahkan "Da" pada Kata Benda/Kata Sifat-Na',caseScenario:'Menghubungkan kata benda langsung ke to omoimasu: "ame to omoimasu".',pitfallWarning:'"あした は あめ と おもいます。" (Kurang Tepat)',rightSolution:'"あした は あめ だ と おもいます。" (Benar - Da-form)',explanation:'Kata benda dan kata sifat-na membutuhkan "だ (da)" sebelum partikel kutipan と.'}],who_and_when:{situational_context:"Rapat harian, musyawarah menentukan tempat makan, meneruskan pesan atasan.",social_relations:"Sangat esensial dalam komunikasi profesional maupun diskusi santai.",when_not_to_use:"Jangan menyatakan fakta mutlak matematika dengan to omoimasu (1+1=2 bukan opini)."},scenario:{title:"Menyampaikan Pendapat dalam Evaluasi Briefing Sore",setting:"Ruang kerja tim, pukul 16.45",narrative:"Budi menyampaikan opininya mengenai cuaca besok dan mengutip pesan Tanaka-senpai tentang persiapan alat kerja."}},dialogue:[{id:"d1",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"ブディさん、明日【あした】の 工事【こうじ】の 天気【てんき】はどうでしょうか。",furigana:"ブディさん、明日の 工事の 天気はどうでしょうか。",romaji:"Budi-san, ashita no kouji no tenki wa dou deshou ka.",idText:"Budi-san, bagaimana ya kira-kira cuaca untuk pekerjaan proyek besok?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"天気予報【てんきよほう】を 見【み】ましたが、明日【あした】は 晴【は】れると 思【おも】います。",furigana:"天気予報を 見ましたが、明日は 晴れると 思います。",romaji:"Tenki yohou o mimashita ga, ashita wa hareru to omoimasu.",idText:"Saya sudah melihat prakiraan cuaca, menurut saya besok akan cerah."},{id:"d3",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"晴【は】れたら いいですね。田中【たなか】さんは 何【なに】か 言【い】っていましたか。",furigana:"晴れたら いいですね。田中さんは 何か 言っていましたか。",romaji:"Haretara ii desu ne. Tanaka-san wa nanika itte imashita ka.",idText:"Baguslah kalau cerah. Apakah Tanaka-san ada mengatakan sesuatu?"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、田中【たなか】さんは「朝【あさ】８時【はちじ】に 集合【しゅうごう】する」と 言【い】いました。",furigana:"はい、田中さんは「朝８時に 集合する」と 言いました。",romaji:'Hai, Tanaka-san wa "asa hachiji ni shuugou suru" to iimashita.',idText:'Iya, Tanaka-san berkata bahwa "pagi jam 8 berkumpul".'},{id:"d5",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"８時【はちじ】か、ちょっと 早【はや】いけど、頑張【がんば】ろう！",furigana:"８時か、ちょっと 早いけど、頑張ろう！",romaji:"Hachiji ka, chotto hayai kedo, gambarou!",idText:"Jam 8 ya, agak pagi sih, tapi ayo bersemangat!"},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"私【わたし】も 準備【じゅんび】が 大切【たいせつ】だ と 思【おも】います。",furigana:"私も 準備が 大切だ と 思います。",romaji:"Watashi mo junbi ga taisetsu da to omoimasu.",idText:"Saya juga berpendapat bahwa persiapan itu sangat penting."},{id:"d7",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"その 通【とお】りですね！みんなで 声【こえ】を かけ合【あ】いましょう。",furigana:"その 通りですね！みんなで 声を かけ合いましょう。",romaji:"Sono toori desu ne! Minna de koe o kakeaimashou.",idText:"Tepat sekali! Mari kita semua saling menyemangati."},{id:"d8",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい！明日【あした】も 安全【あんぜん】に 頑張【がんば】りましょう！",furigana:"はい！明日も 安全に 頑張りましょう！",romaji:"Hai! Ashita mo anzen ni gambarimashou!",idText:"Baik! Besok mari kita bekerja dengan selamat dan semangat!"}],vocab_breakdown:[{id:"vg-n5-00776",word:"切手",reading:"きって",romaji:"kitte",meaning:"perangko",pos:"noun",nuance:"Khusus merujuk pada perangko pos yang ditempelkan di amplop atau kartu pos saat mengirim surat melalui kantor pos (郵便局). Berbeda dengan 切符 (きっぷ) yang berarti tiket transportasi.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"手紙に切手を貼ってポストに入れました。",furigana:"手紙に切手を貼ってポストに入れました。",romaji:"",idText:"Saya menempelkan perangko di surat lalu memasukkannya ke kotak pos."}},{id:"vg-n5-00786",word:"グラム",reading:"グラム",romaji:"guramu",meaning:"gram (satuan berat)",pos:"noun",nuance:"Satuan berat standar metrik (gram). Sering digunakan saat membeli daging, menimbang bumbu dapur, atau menakar bahan makanan saat memasak.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"牛肉を二百グラム買いました。",furigana:"牛肉を二百グラム買いました。",romaji:"",idText:"Saya membeli dua ratus gram daging sapi."}},{id:"vg-n5-00792",word:"～語",reading:"～ご",romaji:"~go",meaning:"bahasa (akhiran nama bahasa)",pos:"noun",nuance:"Akhiran pembentuk nama bahasa dari nama negara atau daerah asalnya, misalnya 日本語 (bahasa Jepang), 英語 (bahasa Inggris), dan インドネシア語 (bahasa Indonesia). Sering digunakan dalam konteks perkenalan atau pendidikan.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"大学で日本語と英語を勉強しています。",furigana:"大学で日本語と英語を勉強しています。",romaji:"",idText:"Saya belajar bahasa Jepang dan bahasa Inggris di universitas."}},{id:"vg-n5-00795",word:"声",reading:"こえ",romaji:"koe",meaning:"suara (manusia atau hewan)",pos:"noun",nuance:"Khusus untuk bunyi suara vokal yang dihasilkan oleh pita suara manusia atau seruan hewan. Berbeda dengan 音 (oto) yang dipakai untuk bebunyian benda mati, alat musik, mesin, atau fenomena alam.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"後ろから友達の明るい声が聞こえました。",furigana:"後ろから友達の明るい声が聞こえました。",romaji:"",idText:"Terdengar suara ceria teman saya dari arah belakang."}},{id:"vg-n5-00800",word:"こっち",reading:"こっち",romaji:"kotchi",meaning:"sebelah sini, arah sini (kasual)",pos:"noun",nuance:"Bentuk santai dan akrab dari こちら (kochira) untuk menunjukkan arah atau posisi di dekat pembicara. Sangat wajar dipakai antarteman sebaya, namun hindari pemakaiannya kepada atasan atau orang yang belum akrab.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"席が空いているから、こっちにおいでよ。",furigana:"席が空いているから、こっちにおいでよ。",romaji:"",idText:"Tempat duduknya masih kosong, yuk kemari ke sebelah sini."}},{id:"vg-n5-00803",word:"これ",reading:"これ",romaji:"kore",meaning:"ini (kata ganti benda)",pos:"noun",nuance:"Kata ganti penunjuk benda mandiri yang posisinya berada di dekat pembicara. Berbeda dengan この yang wajib diikuti kata benda, これ langsung berfungsi sebagai subjek atau objek kalimat (misalnya これは atau これを).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"これは日本の友達にもらったお土産です。",furigana:"これは日本の友達にもらったお土産です。",romaji:"",idText:"Ini adalah oleh-oleh yang saya peroleh dari teman di Jepang."}},{id:"vg-n5-00811",word:"作文",reading:"さくぶん",romaji:"sakubun",meaning:"karangan, esai tulisan",pos:"noun",nuance:"Karangan atau tulisan esai pendek yang disusun siswa dalam latihan menulis bahasa. Berbeda dengan 論文 (ronbun) yang mengacu pada karya ilmiah resmi, skripsi, atau tesis akademis.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"日本語の授業で将来の夢について作文を書きました。",furigana:"日本語の授業で将来の夢について作文を書きました。",romaji:"",idText:"Saya menulis karangan mengenai cita-cita masa depan pada kelas bahasa Jepang."}},{id:"vg-n5-00823",word:"じゃ; じゃあ",reading:"じゃ; じゃあ",romaji:"ja; jaa",meaning:"kalau begitu, nah (kata sambung peralihan kasual)",pos:"conjunction",nuance:"Bentuk percakapan kasual yang merupakan singkatan dari では (dewa). Digunakan untuk beralih topik, menarik simpulan, atau berpamitan antarteman sebaya (じゃあ、また / sampai jumpa). Untuk situasi resmi wajib menggunakan では atau それでは.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"じゃあ、明日駅の前で待ち合わせしよう。",furigana:"じゃあ、明日駅の前で待ち合わせしよう。",romaji:"",idText:"Kalau begitu, besok kita janjian bertemu di depan stasiun ya."}},{id:"vg-n5-00836",word:"ズボン",reading:"ズボン",romaji:"zubon",meaning:"celana panjang",pos:"noun",nuance:"Kata serapan dari bahasa Prancis 'jupon'. Merujuk pada celana panjang secara umum. Kata kerja untuk mengenakan celana adalah はく (haku). Di era modern, kata パンツ (pantsu) juga kerap dipakai untuk celana luar.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"この黒いズボンをはいて会社に行きます。",furigana:"この黒いズボンをはいて会社に行きます。",romaji:"",idText:"Saya mengenakan celana panjang hitam ini lalu pergi ke kantor."}},{id:"vg-n5-00844",word:"そうして; そして",reading:"そうして; そして",romaji:"soushite; soshite",meaning:"lalu, kemudian, dan (penghubung kalimat)",pos:"conjunction",nuance:"Kata sambung urutan kronologis antar kalimat. そして (soshite) adalah ragam yang paling umum digunakan dalam percakapan dan tulisan, sedangkan そうして (soushite) sedikit lebih bernuansa formal atau menggambarkan kelanjutan dari suatu cara/proses.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"朝起きて、顔を洗いました。そして、朝ご飯を食べました。",furigana:"朝起きて、顔を洗いました。そして、朝ご飯を食べました。",romaji:"",idText:"Pagi hari saya bangun lalu mencuci muka. Kemudian, saya sarapan."}}],explanations:[{id:"exp-1",grammarId:"gn5-00067",title:"Pola: 〜が (tapi)",formula:"文1 + が + 文2",meaning:"tapi / namun (kontras)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜が (tapi)",idText:"tapi / namun (kontras)"}],examples:[{jp:"にほんごはすきですが、むずかしいです。",romaji:"",idText:"Suka bahasa Jepang, tapi susah."},{jp:"まいにちれんしゅうしますが、まだじょうずじゃないです。",romaji:"",idText:"Latihan setiap hari, tapi belum mahir."}]},{id:"exp-2",grammarId:"gn5-00068",title:"Pola: 〜けど / 〜けれど",formula:"文1 + けど / けれど(も) + 文2",meaning:"tapi / walaupun (kasual)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜けど / 〜けれど",idText:"tapi / walaupun (kasual)"}],examples:[{jp:"やってみたけど、できなかった。",romaji:"",idText:"Sudah dicoba, tapi tidak bisa."},{jp:"たかいけど、かいます。",romaji:"",idText:"Mahal, tapi beli."}]},{id:"exp-3",grammarId:"gn5-00071",title:"Pola: 〜という",formula:"N1 + という + N2",meaning:"yang bernama ... / yang disebut ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜という",idText:"yang bernama ... / yang disebut ..."}],examples:[{jp:"「さくら」というえいがをみましたか。",romaji:"",idText:'Sudah menonton film yang berjudul "Sakura"?'},{jp:"やまだというひとがきました。",romaji:"",idText:"Datang seseorang bernama Yamada."}]},{id:"exp-4",grammarId:"gn5-00072",title:"Pola: 〜と言っています",formula:"「...」 + と + 言っています / 言いました",meaning:"mengatakan bahwa ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜と言っています",idText:"mengatakan bahwa ..."}],examples:[{jp:"かれはあしたくると言っています。",romaji:"",idText:"Dia bilang akan datang besok."},{jp:"ははは「はやくかえって」と言いました。",romaji:"",idText:'Ibu bilang "pulang cepat".'}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Kata): Pilihlah arti kata "意見 (いけん)".',sentencePrompt:'Kata "意見" memiliki arti:',options:["Pendapat / Opini","Gaji bulanan","Pakaian kerja","Jadwal kereta"],correctAnswer:"Pendapat / Opini",explanation:'"意見 (いけん)" berarti pendapat atau opini pemikiran.',diagnosticFeedback:{"Gaji bulanan":"Salah: Gaji adalah 給料 (kyuuryou).","Pakaian kerja":"Salah: Pakaian kerja adalah 作業服 (sagyoufuku).","Jadwal kereta":"Salah: Jadwal adalah 時刻表 (jikokuhyou)."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Isian Partikel Kutipan): Pilihlah partikel penanda isi opini/kutipan.",sentencePrompt:"私【わたし】は 明日【あした】晴【は】れる _____ 思【おも】います。",options:["と","を","に","が"],correctAnswer:"と",explanation:"Partikel penanda isi kutipan pemikiran (〜と思います) adalah と.",diagnosticFeedback:{を:"Salah: を menandai objek kata kerja transitif langsung.",に:"Salah: に menandai arah atau titik waktu.",が:"Salah: が menandai subjek klausa."}},{id:"drill-3",type:"reorder",instruction:"Langkah 3 (Susun Kalimat): Urutkan kalimat yang menyatakan opini bahwa persiapan itu penting.",sentencePrompt:"Susunan kalimat yang tepat:",options:["私【わたし】も 準備【じゅんび】が 大切【たいせつ】だ と 思【おも】います","準備【じゅんび】が 大切【たいせつ】だ 私【わたし】も と 思【おも】います","と 思【おも】います 私【わたし】も 準備【じゅんび】が 大切【たいせつ】だ","私【わたし】も 準備【じゅんび】が 大切【たいせつ】です と 思【おも】います"],correctAnswer:"私【わたし】も 準備【じゅんび】が 大切【たいせつ】だ と 思【おも】います",explanation:"Subjek (私も) + Isi Opini Futsuukei (準備が大切だ) + と 思います.",diagnosticFeedback:{"準備【じゅんび】が 大切【たいせつ】だ 私【わたし】も と 思【おも】います":"Jebakan: Posisi subjek terselip di tengah.","と 思【おも】います 私【わたし】も 準備【じゅんび】が 大切【たいせつ】だ":"Jebakan: Predikat di awal kalimat.","私【わたし】も 準備【じゅんび】が 大切【たいせつ】です と 思【おも】います":"Jebakan: Sebelum と wajib bentuk biasa (だ), bukan です."},tokens:["私【わたし】も","準備【じゅんび】が","大切【たいせつ】だ","と","思【おも】います"],correctOrder:["0","1","2","3","4"]},{id:"drill-4",type:"trap_detect",instruction:"Langkah 4 (Deteksi Jebakan): Manakah kalimat kutipan perkataan orang lain yang benar?",sentencePrompt:"Pilihlah kalimat yang mengutip ucapan Tanaka-san:",options:["田中【たなか】さんは ８時【はちじ】に 来【く】る と 言【い】いました。","田中【たなか】さんは ８時【はちじ】に 来【き】ます と 言【い】いました。","田中【たなか】さんは ８時【はちじ】に 来【く】る を 言【い】いました。","田中【たなか】さんは ８時【はちじ】に 来【く】る に 言【い】いました。"],correctAnswer:"田中【たなか】さんは ８時【はちじ】に 来【く】る と 言【い】いました。",explanation:"Kutipan tidak langsung memakai bentuk biasa: 来る + と 言いました.",diagnosticFeedback:{"田中【たなか】さんは ８時【はちじ】に 来【き】ます と 言【い】いました。":"Kurang tepat: Dalam kutipan tidak langsung, bentuk sopan kimasu dinetralkan menjadi kuru.","田中【たなか】さんは ８時【はちじ】に 来【く】る を 言【い】いました。":"Jebakan: Salah memakai partikel を.","田中【たなか】さんは ８時【はちじ】に 来【く】る に 言【い】いました。":"Jebakan: Salah memakai partikel に."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Saat dimintai pendapat "この計画について どう思いますか", respons opini yang tepat adalah:',sentencePrompt:"Pilihlah jawaban yang mengutarakan pendapat:",options:["とても いい 計画【けいかく】だ と 思【おも】います。","はい、言【い】いました。","計画【けいかく】は さようなら。","誰【だれ】も いません。"],correctAnswer:"とても いい 計画【けいかく】だ と 思【おも】います。",explanation:"Menyampaikan opini dengan bentuk [Futsuukei] + と思います.",diagnosticFeedback:{"はい、言【い】いました。":"Tidak mengutarakan opini yang diminta.","計画【けいかく】は さようなら。":"Sayounara tidak nyambung dalam rapat.","誰【だれ】も いません。":"Tidak menjawab pertanyaan."}}],can_do_challenge:{statement:"Bisa menyampaikan pendapat pribadi dan meneruskan pesan supervisor secara santun.",situation:"Rapat evaluasi singkat bersama tim kerja.",promptTask:"Katakan bahwa menurutmu rencana ini bagus, dan Tanaka-san berkata besok mulai jam 8!",modelAnswer:"いい 計画【けいかく】だ と 思【おも】います。田中【たなか】さんも 明日【あした】８時【はちじ】に 始【はじ】まると 言【い】いました。",modelAnswerId:"Menurut saya ini rencana yang bagus. Tanaka-san juga berkata bahwa besok mulai jam 8.",culturalEtiquette:"Gunakan bentuk biasa sebelum partikel kutipan と.",skillUnlocked:["Menguasai ekspresi opini to omoimasu","Menguasai kutipan pesan to iimashita"]},pocket_summary:{keyFormula:"[Futsuukei] と 思います (opini) / [Futsuukei] と 言いました (kutipan)",coreWords:["おもいます","いいました","いけん","けいかく"],coreWarning:'Klausa sebelum "to" wajib berbentuk biasa (Futsuukei). Nomina/Na-adj memakai "da".',quickDialogue:"A: どう思いますか。 → B: いいと 思います。"}}},u={"les-n5-u15-01":{pedagogical_framework:{what:{summary:"Kewajiban/keharusan mutlak [Verba-nai] ければ なりません (harus), kelonggaran izin tidak perlu [Verba-nai] くても いいです (tidak usah), dan penetapan keputusan [Verba Kamus] ことにする / ことになる.",canDo:"Bisa memahami peraturan keselamatan pabrik, kewajiban perpanjangan visa, dan hal yang tidak wajib dilakukan.",targetPatterns:["[Verba-nai] ければ なりません (wajib/harus)","[Verba-nai] くても いいです (tidak perlu)","[Verba Kamus] ことに します (memutuskan)"],coreVocabSample:["ビザ","パスポート","ださなければなりません","しなくてもいいです","きめました"]},sensei_context:{sceneIntro:"Di balai imigrasi dan administrasi kantor, Budi mengurus perpanjangan izin tinggal dan mempelajari aturan keselamatan pabrik.",dailyMission:"Gunakan 〜なければなりません untuk kewajiban mutlak dan 〜なくてもいいです untuk hal yang tidak diwajibkan.",whyOrder:"Memahami keharusan hukum (visa) dan keselamatan (K3) adalah syarat mutlak hidup aman dan legal di Jepang."},cultural_notes:{title:"Kepatuhan Regulasi Keimigrasian & Kartu Zairyu (在留カード)",etiquette:"Di Jepang, warga negara asing wajib membawa Kartu Izin Tinggal (Zairyuu Ka-do) ke mana pun pergi (Keitai Gimu). Tidak membawa kartu bisa dikenakan denda pidana!",taboos:"Bentuk 〜なければなりません secara lisan sering disingkat menjadi 〜なきゃ (nakya). Namun dalam situasi resmi dengan atasan, tetap gunakan bentuk panjangnya yang santun!"},pronunciation_tips:{title:"Irama Pelafalan Nakereba Narimasen",moraNote:'Frasa "nakereba narimasen" memiliki banyak mora. Ucapkan secara berirama per segmen: na-ke-re-ba na-ri-ma-se-n.',soundTip:'Lafalkan "dasanakereba narimasen" dengan artikulasi jelas.'},common_pitfalls:[{title:'Salah Mengonjugasikan Verba Sebelum "Kereba Narimasen"',caseScenario:'Memakai bentuk masu sebelum nakereba: "ikimasunakereba".',pitfallWarning:'"いきます なければ なりません。" (Salah Total)',rightSolution:'"いかなければ なりません。" (Benar - Dari Bentuk-Nai)',explanation:'Hilangkan huruf "i" pada bentuk-nai lalu sambungkan kereba narimasen: Ikanai -> Ikanakereba narimasen.'},{title:'Tertukar Antara "Koto ni suru" vs "Koto ni naru"',caseScenario:"Ingin menyatakan aturan kantor tapi memakai koto ni suru.",pitfallWarning:'"かいしゃ の ルール を することにしました。" (Rancu)',rightSolution:'"〜することになりました。" (Keputusan aturan luar)',explanation:"Koto ni suru = keputusan tekad diri sendiri. Koto ni naru = aturan/keputusan dari pihak organisasi eksternal."}],who_and_when:{situational_context:"Pengurusan dokumen imigrasi, kepatuhan APD pabrik, konfirmasi jam lembur.",social_relations:"Sangat penting dalam hubungan formal kepatuhan hukum dan instruksi atasan.",when_not_to_use:'Jangan pakai bentuk singkatan "nakya" saat berbicara di loket imigrasi.'},scenario:{title:"Pemberitahuan Prosedur Perpanjangan Dokumen Visa",setting:"Ruang HRD kantor, pukul 11.00",narrative:"Tanaka-senpai mengingatkan Budi dokumen apa saja yang harus diserahkan ke imigrasi sebelum masa berlaku habis."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"ブディさん、在留【ざいりゅう】カードの 期限【きげん】は いつまでですか。",furigana:"ブディさん、在留カードの 期限は いつまでですか。",romaji:"Budi-san, zairyuu ka-do no kigen wa itsu made desu ka.",idText:"Budi-san, masa berlaku Kartu Izin Tinggal (Zairyu Card) milikmu sampai kapan?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"来月【らいげつ】の １５日【じゅうごにち】までです。更新【こうしん】しなければ なりませんか。",furigana:"来月の １５日までです。更新しなければ なりませんか。",romaji:"Raigetsu no juugonichi made desu. Koushin shinakereba narimasen ka.",idText:"Sampai tanggal 15 bulan depan. Apakah saya harus memperpanjangnya?"},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"ええ、今月中【こんげつちゅう】に 入管【にゅうかん】へ 書類【しょるい】を 出【だ】さなければ なりませんよ。",furigana:"ええ、今月中に入管へ 書類を 出さなければ なりませんよ。",romaji:"Ee, kongetsuchuu ni nyuukan e shorui o dasanakereba narimasen yo.",idText:"Iya, dalam bulan ini kamu harus menyerahkan dokumen ke imigrasi lho."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"写真【しゃしん】も 新【あたら】しく 撮【と】らなければ なりませんか。",furigana:"写真も 新しく 撮らなければ なりませんか。",romaji:"Shashin mo atarashiku toranakereba narimasen ka.",idText:"Apakah foto juga harus mengambil yang baru?"},{id:"d5",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"３ヶ月以内【さんかげついない】の 写真【しゃしん】なら、新【あたら】しく 撮【と】らなくても いいですよ。",furigana:"３ヶ月以内の 写真なら、新しく 撮らなくても いいですよ。",romaji:"Sankagetsu inai no shashin nara, atarashiku toranakutemo ii desu yo.",idText:"Kalau foto dalam 3 bulan terakhir, tidak usah ambil baru juga tidak apa-apa kok."},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"わかりました！明日【あした】書類【しょるい】を 準備【じゅんび】する ことに します。",furigana:"わかりました！明日書類を 準備する ことに します。",romaji:"Wakarimashita! Ashita shorui o junbi suru koto ni shimasu.",idText:"Saya paham! Besok saya memutuskan untuk menyiapkan dokumen-dokumennya."},{id:"d7",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"会社【かいしゃ】の 証明書【しょうめいしょ】も 必要【ひつよう】ですから、私【わたし】が 作【つく】っておきますね。",furigana:"会社の 証明書も 必要ですから、私が 作っておきますね。",romaji:"Kaisha no shoumeisho mo hitsuyou desu kara, watashi ga tsukutte okimasu ne.",idText:"Karena surat keterangan dari perusahaan juga diperlukan, nanti saya buatkan terlebih dahulu ya."},{id:"d8",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"助【たす】かります！本当【ほんとう】に ありがとうございます。",furigana:"助かります！本当に ありがとうございます。",romaji:"Tasukarimasu! Hontou ni arigatou gozaimasu.",idText:"Sangat terbantu! Terima kasih banyak atas kebaikan Anda."}],vocab_breakdown:[{id:"vg-n5-00041",word:"教える",reading:"おしえる",romaji:"oshieru",meaning:"mengajar; memberitahu",pos:"verb-ru",nuance:"もらう = menerima/mendapat (dari orang). Lawan: あげる (ageru) = memberi.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"日本語を教えています。",furigana:"日本語を教えています。",romaji:"",idText:"Saya mengajar bahasa Jepang."}},{id:"vg-n5-00042",word:"覚える",reading:"おぼえる",romaji:"oboeru",meaning:"mengingat; menghafal",pos:"verb-ru",nuance:"あげる = memberi (ke orang). Keigo: さしあげる (humble). Lawan: もらう.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"単語を覚えました。",furigana:"単語を覚えました。",romaji:"",idText:"Saya menghafal kosakata."}},{id:"vg-n5-00155",word:"勉強する",reading:"べんきょうする",romaji:"benkyou suru",meaning:"belajar, mempelajari",pos:"verb-suru",nuance:"勉強 (noun) + する. Bisa dipisah: 日本語を勉強する atau digabung langsung: 勉強します.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"毎日日本語を勉強しています。",furigana:"毎日日本語を勉強しています。",romaji:"",idText:"Saya belajar bahasa Jepang setiap hari."}},{id:"vg-n5-00181",word:"かく",reading:"かく",romaji:"kaku",meaning:"menulis; menggambar",pos:"verb-u",nuance:"Used broadly for writing words or drawing pictures. Kanji varies depending on whether you write letters (書く) or draw pictures (描く).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"名前を書いてください。",furigana:"名前を書いてください。",romaji:"",idText:"Tolong tulis namanya."}},{id:"vg-n5-00191",word:"こたえる",reading:"こたえる",romaji:"kotaeru",meaning:"menjawab",pos:"verb-ru",nuance:"Refers to replying to a question, answering a test, or responding to someone. Takes the particle に for what you are answering.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"質問に答えてください。",furigana:"質問に答えてください。",romaji:"",idText:"Tolong jawab pertanyaannya."}},{id:"vg-n5-00203",word:"とぶ",reading:"とぶ",romaji:"tobu",meaning:"terbang; melompat",pos:"verb-u",nuance:"Can mean to fly through the air (like a bird or airplane) or to jump high. Written with different kanji depending on the meaning.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"鳥が空を飛んでいます。",furigana:"鳥が空を飛んでいます。",romaji:"",idText:"Burung terbang di langit."}},{id:"vg-n5-00208",word:"ならう",reading:"ならう",romaji:"narau",meaning:"belajar dari seseorang",pos:"verb-u",nuance:"習う = belajar dari guru/orang lain. Berbeda: 勉強する = belajar mandiri.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"先生に日本語を習っています。",furigana:"先生に日本語を習っています。",romaji:"",idText:"Saya belajar bahasa Jepang dari guru."}},{id:"vg-n5-00219",word:"ふる",reading:"ふる",romaji:"furu",meaning:"turun (hujan/salju)",pos:"verb-u",nuance:"Specifically used for precipitation falling from the sky, such as rain (雨が降る) or snow (雪が降る).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"雨が降っています。",furigana:"雨が降っています。",romaji:"",idText:"Hujan turun."}},{id:"vg-n5-00227",word:"よむ",reading:"よむ",romaji:"yomu",meaning:"membaca",pos:"verb-u",nuance:"Refers to reading text. It can also imply understanding the deeper meaning of a situation or 'reading the room'.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"毎日新聞を読みます。",furigana:"毎日新聞を読みます。",romaji:"",idText:"Saya membaca koran setiap hari."}},{id:"vg-n5-00228",word:"わかる",reading:"わかる",romaji:"wakaru",meaning:"mengerti; paham",pos:"verb-u",nuance:"日本語がわかります (pakai が, bukan を). Intransitif.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"説明がわかりましたか。",furigana:"説明がわかりましたか。",romaji:"",idText:"Apakah penjelasannya dimengerti?"}}],explanations:[{id:"exp-1",grammarId:"gn5-00045",title:"Pola: 〜なければならない",formula:"Vない → Vなければ + ならない/なりません",meaning:"harus ... / wajib ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜なければならない",idText:"harus ... / wajib ..."}],examples:[{jp:"まいにちべんきょうしなければなりません。",romaji:"",idText:"Harus belajar setiap hari."},{jp:"もうかえらなきゃ。",romaji:"",idText:"Harus pulang sekarang."}]},{id:"exp-2",grammarId:"gn5-00046",title:"Pola: 〜なくてもいい",formula:"Vなく + てもいい",meaning:"tidak perlu ... / boleh tidak ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜なくてもいい",idText:"tidak perlu ... / boleh tidak ..."}],examples:[{jp:"あしたはこなくてもいいですよ。",romaji:"",idText:"Besok boleh tidak datang."},{jp:"ぜんぶたべなくてもいいです。",romaji:"",idText:"Tidak perlu dimakan semua."}]},{id:"exp-3",grammarId:"gn5-00052",title:"Pola: 〜ことにする",formula:"Vる / Vない + ことにする",meaning:"memutuskan untuk ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜ことにする",idText:"memutuskan untuk ..."}],examples:[{jp:"まいにちうんどうすることにしました。",romaji:"",idText:"Memutuskan untuk berolahraga setiap hari."},{jp:"おさけをのまないことにする。",romaji:"",idText:"Memutuskan untuk tidak minum alkohol."}]},{id:"exp-4",grammarId:"gn5-00053",title:"Pola: 〜ことになる",formula:"Vる / Vない + ことになる",meaning:"sudah diputuskan / ternyata menjadi ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜ことになる",idText:"sudah diputuskan / ternyata menjadi ..."}],examples:[{jp:"らいねんとうきょうへいくことになりました。",romaji:"",idText:"Sudah diputuskan (saya) akan ke Tokyo tahun depan."},{jp:"かいぎがへやAでひらかれることになった。",romaji:"",idText:"Rapat akan diadakan di ruangan A."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Kata): Pilihlah arti kata "更新 (こうしん)".',sentencePrompt:'Kata "更新" dalam administrasi visa berarti:',options:["Perpanjangan / Pembaruan","Pembatalan visa","Surat tilang","Pindah alamat"],correctAnswer:"Perpanjangan / Pembaruan",explanation:'"更新 (こうしん)" berarti perpanjangan atau pembaruan masa berlaku dokumen.',diagnosticFeedback:{"Pembatalan visa":"Salah: Pembatalan adalah 取消 (torikeshi).","Surat tilang":"Salah: Surat tilang adalah 交通違反切符.","Pindah alamat":"Salah: Pindah alamat adalah 住所変更 (juusho henkou)."}},{id:"drill-2",type:"cloze",instruction:'Langkah 2 (Isian Rumus Keharusan): Pilihlah pola untuk menyatakan "harus menyerahkan dokumen".',sentencePrompt:"書類【しょるい】を 出【だ】さ _____ なりません。",options:["なければ","なくては","ないなら","ないでも"],correctAnswer:"なければ",explanation:"Pola keharusan mutlak adalah [V-nai tanpa i] + なければ なりません.",diagnosticFeedback:{なくては:"Bisa secara lisan (nakute wa ikemasen), tapi pasangannya narimasen adalah nakereba.",ないなら:"Salah: Pengandaian biasa.",ないでも:"Salah: Rumus tidak baku."}},{id:"drill-3",type:"reorder",instruction:'Langkah 3 (Susun Kalimat): Urutkan kalimat kelonggaran "tidak usah foto baru" berikut.',sentencePrompt:"Susunan kalimat yang tepat:",options:["新【あたら】しく 撮【と】らなくても いいです","撮【と】らなくても 新【あたら】しく いいです","いいです 新【あたら】しく 撮【と】らなくても","新【あたら】しく 撮【と】るなくても いいです"],correctAnswer:"新【あたら】しく 撮【と】らなくても いいです",explanation:"Adverbia (新しく) + [V-nai tanpa i] + くても いいです (撮らなくてもいいです).",diagnosticFeedback:{"撮【と】らなくても 新【あたら】しく いいです":"Jebakan: Kata keterangan ditaruh di tengah pola.","いいです 新【あたら】しく 撮【と】らなくても":"Jebakan: Predikat di depan kalimat.","新【あたら】しく 撮【と】るなくても いいです":"Jebakan Fatal: Salah mengubah bentuk kamus toru menjadi torunakutemo."},tokens:["新【あたら】しく","撮【と】らなくても","いいです"],correctOrder:["0","1","2"]},{id:"drill-4",type:"trap_detect",instruction:'Langkah 4 (Deteksi Jebakan): Manakah konjugasi bentuk keharusan dari kata "行きます" yang benar?',sentencePrompt:"Bentuk keharusan dari 行きます adalah:",options:["行【い】かなければ なりません。","行【い】きます なければ なりません。","行【い】く なければ なりません。","行【い】かない なければ なりません。"],correctAnswer:"行【い】かなければ なりません。",explanation:"Bentuk-nai ikanai -> huruf i dilepas diganti kereba: 行かなければ なりません.",diagnosticFeedback:{"行【い】きます なければ なりません。":"Jebakan Fatal: Bentuk masu salah digabung dengan nakereba.","行【い】く なければ なりません。":"Jebakan: Bentuk kamus salah digabung.","行【い】かない なければ なりません。":"Jebakan: Lupa membuang huruf i pada ikanai."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Saat atasan mengingatkan "今月中に入管へ書類を出さなければなりませんよ", respons kesiapan yang tepat adalah:',sentencePrompt:"Pilihlah respon komitmen prosedur:",options:["承知【しょうち】しました。明日【あした】準備【じゅんび】する ことに します。","いいえ、出【だ】しません。","ビザは ありません。","さようなら、行【い】きません。"],correctAnswer:"承知【しょうち】しました。明日【あした】準備【じゅんび】する ことに します。",explanation:"Menyatakan pemahaman dan keputusan segera bersiap (koto ni shimasu).",diagnosticFeedback:{"いいえ、出【だ】しません。":"Menolak memperpanjang visa berakibat status ilegal.","ビザは ありません。":"Berdalih tidak masuk akal padahal pekerja asing wajib berizin tinggal.","さようなら、行【い】きません。":"Kasar dan tidak bertanggung jawab."}}],can_do_challenge:{statement:"Bisa memahami kewajiban pengurusan visa dan hal yang tidak wajib dilakukan.",situation:"Konsultasi berkas imigrasi bersama supervisor kerja.",promptTask:"Katakan bahwa kamu harus menyerahkan berkas, tetapi tidak perlu foto baru!",modelAnswer:"書類【しょるい】を 出【だ】さなければ なりませんが、写真【しゃしん】は 新【あたら】しく 撮【と】らなくても いいです。",modelAnswerId:"Saya harus menyerahkan dokumen, tetapi tidak perlu mengambil foto baru.",culturalEtiquette:"Gunakan bentuk nakereba narimasen untuk hukum dan nakutemo ii untuk dispensasi.",skillUnlocked:["Menguasai kewajiban nakereba narimasen","Menguasai dispensasi nakutemo ii desu"]},pocket_summary:{keyFormula:"[V-nai tanpa i] + ければなりません (Wajib) / くてもいいです (Boleh tidak)",coreWords:["ビザ","しょるい","ださなければなりません","きげん"],coreWarning:'Huruf "i" pada bentuk-nai wajib dibuang sebelum digabung "kereba narimasen".',quickDialogue:"A: 行かなければなりませんか。 → B: いいえ、行かなくても いいですよ。"}},"les-n5-u15-02":{pedagogical_framework:{what:{summary:"Hubungan sekuensial waktu: [Verba Kamus / Nomina の] 前に (sebelum), [Verba-ta / Nomina の] 後で (setelah), dan momen kejadian [Bentuk Biasa / Nomina の] とき (ketika / saat).",canDo:"Bisa menjelaskan jadwal operasional mesin sebelum dan sesudah dinyalakan, serta prosedur saat keadaan darurat.",targetPatterns:["[Verba Kamus] まえに (sebelum)","[Verba-ta] あとで (setelah)","[Bentuk Biasa / Nomina の] とき (ketika / saat)"],coreVocabSample:["まえに","あとで","とき","スイッチ","じしん","ひなん"]},sensei_context:{sceneIntro:"Pelatihan simulasi gempa bumi (Bousai Kunren) dan keselamatan mesin pabrik. Tanaka menjelaskan apa yang harus dilakukan sebelum menyalakan mesin dan saat terjadi gempa.",dailyMission:"Mampu menghubungkan aksi waktu dengan 前に, 後で, dan とき secara tepat tenses.",whyOrder:'Jepang adalah negeri rawan gempa. Memahami instruksi "saat gempa (jishin no toki)" menyelamatkan nyawa!'},cultural_notes:{title:"Latihan Mitigasi Bencana di Jepang (防災訓練 - Bousai Kunren)",etiquette:"Setiap kantor dan pabrik rutin mengadakan simulasi evakuasi. Saat alarm gempa berbunyi, langsung matikan sakelar api/mesin lalu berlindung di bawah meja.",taboos:"Perhatikan tenses: 前に SELALU diawali Verba Kamus (belum terjadi). 後で SELALU diawali Verba Bentuk-Ta (sudah terjadi)!"},pronunciation_tips:{title:"Pembeda Bentuk Verba Sebelum Mae dan Ato",moraNote:'Perhatikan: "neru mae ni" (Kamus) vs "tabeta ato de" (Bentuk-Ta).',soundTip:'Katakan "jishin no toki" dengan partikel no menyambung lembut.'},common_pitfalls:[{title:'Memakai Bentuk Lampau Sebelum "Mae ni"',caseScenario:"Refleks menggunakan bentuk lampau karena peristiwanya terjadi kemarin.",pitfallWarning:'"ねた まえに、ほんを よみました。" (Salah Fatal)',rightSolution:'"ねる まえに、ほんを よみました。" (Benar - Wajib Kamus)',explanation:"Pola 〜まえに selalu menuntut Bentuk Kamus, tidak peduli apakah kalimat penutupnya lampau atau sekarang."},{title:'Lupa Memberi Partikel "No" pada Kata Benda Sebelum Toki',caseScenario:'Menempelkan jishin langsung ke toki: "jishin toki".',pitfallWarning:'"じしん とき、机【つくえ】の 下【した】へ 入【はい】ります。" (Salah)',rightSolution:'"じしん の とき、机【つくえ】の 下【した】へ 入【はい】ります。" (Benar)',explanation:"Kata benda sebelum とき wajib memakai jembatan partikel の."}],who_and_when:{situational_context:"Pelatihan mitigasi bencana pabrik, instruksi pemeliharaan mesin, bercerita jadwal harian.",social_relations:"Sangat vital dalam briefing teknis dan komunikasi darurat K3.",when_not_to_use:"Jangan panik berlari saat gempa; lindungi kepala terlebih dahulu."},scenario:{title:"Simulasi Keselamatan Gempa Bumi dan Operasional Mesin",setting:"Lantai produksi pabrik saat simulasi K3, pukul 14.00",narrative:"Tanaka-senpai menguji pemahaman Budi tentang prosedur keselamatan sebelum menyalakan mesin dan saat terjadi gempa."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"ブディさん、機械【きかい】を 動【うご】かす 前【まえ】に、何【なに】を しますか。",furigana:"ブディさん、機械を 動かす 前に、何を しますか。",romaji:"Budi-san, kikai o ugokasu mae ni, nani o shimasu ka.",idText:"Budi-san, sebelum mengoperasikan mesin, apa yang kamu lakukan?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"動【うご】かす 前【まえ】に、安全点検【あんぜんてんけん】を します。油【あぶら】と スイッチを 確認【かくにん】します。",furigana:"動かす 前に、安全点検を します。油と スイッチを 確認します。",romaji:"Ugokasu mae ni, anzen tenken o shimasu. Abura to suitchi o kakunin shimasu.",idText:"Sebelum menyalakan mesin, saya melakukan inspeksi keselamatan. Memeriksa oli dan sakelar tombol."},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"正解【せいかい】です。では、作業【さぎょう】が 終【お】わった あとで、どうしますか。",furigana:"正解です。では、作業が 終わった あとで、どうしますか。",romaji:"Seikai desu. Dewa, sagyou ga owatta ato de, dou shimasu ka.",idText:"Benar sekali. Kalau begitu, setelah pekerjaan selesai, bagaimana?"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"作業【さぎょう】が 終【お】わった あとで、電源【でんげん】を 切【き】って、掃除【そうじ】を します。",furigana:"作業が 終わった あとで、電源を 切って、掃除を します。",romaji:"Sagyou ga owatta ato de, dengen o kitte, souji o shimasu.",idText:"Setelah pekerjaan selesai, saya matikan daya listrik lalu membersihkannya."},{id:"d5",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"もし 地震【じしん】の ときは、どうしますか。",furigana:"もし 地震の ときは、どうしますか。",romaji:"Moshi jishin no toki wa, dou shimasu ka.",idText:"Kalau saat terjadi gempa bumi, apa yang dilakukan?"},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"地震【じしん】の ときは、すぐ 機械【きかい】を 止【と】めて、机【つくえ】の 下【した】へ 入【はい】ります！",furigana:"地震の ときは、すぐ 機械を 止めて、机の 下へ 入ります！",romaji:"Jishin no toki wa, sugu kikai o tomete, tsukue no shita e hairimasu!",idText:"Saat gempa bumi, segera hentikan mesin, lalu masuk berlindung ke bawah meja!"},{id:"d7",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"完璧【かんぺき】ですね！避難訓練【ひなんくんれん】の 成果【せいか】が 出【で】ています。",furigana:"完璧ですね！避難訓練の 成果が 出ています。",romaji:"Kanpeki desu ne! Hinan kunren no seika ga dete imasu.",idText:"Sempurna ya! Hasil latihan evakuasi terlihat sangat nyata."},{id:"d8",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"ありがとうございます！安全【あんぜん】に 気【き】をつけて 働【はたら】きます！",furigana:"ありがとうございます！安全に 気をつけて 働きます！",romaji:"Arigatou gozaimasu! Anzen ni ki o tsukete hatarakimasu!",idText:"Terima kasih banyak! Saya akan bekerja dengan selalu memperhatikan keselamatan!"}],vocab_breakdown:[{id:"vg-n5-00335",word:"きょうしつ",reading:"きょうしつ",romaji:"kyoushitsu",meaning:"ruang kelas",pos:"noun",nuance:"Refers to the physical room where classes are held. Can also refer to a specific course or lesson, like 'りょうりきょうしつ' (cooking class).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"教室に入ってください。",furigana:"教室に入ってください。",romaji:"",idText:"Tolong masuk ke kelas."}},{id:"vg-n5-00336",word:"じゅぎょう",reading:"じゅぎょう",romaji:"jugyou",meaning:"pelajaran; kelas",pos:"noun",nuance:"Refers to the actual teaching or instruction period. Distinct from 'クラス' (kurasu) which refers to the group of students.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"授業は何時間ありますか。",furigana:"授業は何時間ありますか。",romaji:"",idText:"Ada berapa jam pelajaran?"}},{id:"vg-n5-00337",word:"しけん",reading:"しけん",romaji:"shiken",meaning:"ujian; tes",pos:"noun",nuance:"A formal examination or test of knowledge/skills. Often used interchangeably with 'テスト' (tesuto), though 'しけん' sounds slightly more formal.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"明日試験があります。",furigana:"明日試験があります。",romaji:"",idText:"Besok ada ujian."}},{id:"vg-n5-00338",word:"しゅくだい",reading:"しゅくだい",romaji:"shukudai",meaning:"pekerjaan rumah; PR",pos:"noun",nuance:"Assignments given to students to complete outside of school. Also used metaphorically for a task one needs to complete later.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"宿題を忘れました。",furigana:"宿題を忘れました。",romaji:"",idText:"Saya lupa PR."}},{id:"vg-n5-00339",word:"としょかん",reading:"としょかん",romaji:"toshokan",meaning:"perpustakaan",pos:"noun",nuance:"A public or institutional building where books are kept for reading or borrowing. Distinct from 'ほんや' (bookstore) where books are sold.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"図書館で本を借ります。",furigana:"図書館で本を借ります。",romaji:"",idText:"Saya meminjam buku di perpustakaan."}},{id:"vg-n5-00341",word:"そら",reading:"そら",romaji:"sora",meaning:"langit",pos:"noun",nuance:"Refers to the physical sky above. Can be combined with weather terms, like 'あおぞら' (blue sky) or 'ほしぞら' (starry sky).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"空が青くてきれいですね。",furigana:"空が青くてきれいですね。",romaji:"",idText:"Langitnya biru dan indah ya."}},{id:"vg-n5-00342",word:"きせつ",reading:"きせつ",romaji:"kisetsu",meaning:"musim",pos:"noun",nuance:"Refers to the four seasons (spring, summer, autumn, winter) or a specific time of year associated with something (e.g., cherry blossom season).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"好きな季節はいつですか。",furigana:"好きな季節はいつですか。",romaji:"",idText:"Musim favorit kamu apa?"}},{id:"vg-n5-00343",word:"なつ",reading:"なつ",romaji:"natsu",meaning:"musim panas",pos:"noun",nuance:"The hottest season of the year in Japan, associated with festivals (matsuri) and cicadas. Used in combinations like 'なつやすみ' (summer vacation).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"夏は暑くて好きじゃないです。",furigana:"夏は暑くて好きじゃないです。",romaji:"",idText:"Saya tidak suka musim panas karena panas."}},{id:"vg-n5-00344",word:"あき",reading:"あき",romaji:"aki",meaning:"musim gugur",pos:"noun",nuance:"The season of cooling temperatures and autumn leaves (momiji). Often associated with appetite, reading, and sports in Japanese culture.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"秋は涼しくてきれいです。",furigana:"秋は涼しくてきれいです。",romaji:"",idText:"Musim gugur itu sejuk dan indah."}},{id:"vg-n5-00345",word:"ふゆ",reading:"ふゆ",romaji:"fuyu",meaning:"musim dingin",pos:"noun",nuance:"The coldest season, often associated with snow. Used in words like 'ふゆやすみ' (winter vacation).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"冬はスキーが楽しいです。",furigana:"冬はスキーが楽しいです。",romaji:"",idText:"Di musim dingin ski sangat menyenangkan."}}],explanations:[{id:"exp-1",grammarId:"gn5-00054",title:"Pola: 〜前に",formula:"Vる / N + の + 前に",meaning:"sebelum ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜前に",idText:"sebelum ..."}],examples:[{jp:"ねるまえに、はをみがきます。",romaji:"",idText:"Sikat gigi sebelum tidur."},{jp:"しょくじのまえにてをあらいます。",romaji:"",idText:"Cuci tangan sebelum makan."}]},{id:"exp-2",grammarId:"gn5-00055",title:"Pola: 〜後で",formula:"Vた / N + の + 後で",meaning:"setelah ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜後で",idText:"setelah ..."}],examples:[{jp:"しゅくだいをしたあとで、あそびます。",romaji:"",idText:"Bermain setelah PR selesai."},{jp:"しょくじのあとでコーヒーをのみます。",romaji:"",idText:"Minum kopi setelah makan."}]},{id:"exp-3",grammarId:"gn5-00056",title:"Pola: 〜とき",formula:"V plain / Adj plain / N + の + とき",meaning:"ketika ... / saat ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜とき",idText:"ketika ... / saat ..."}],examples:[{jp:"こどものとき、よくやまへいきました。",romaji:"",idText:"Waktu kecil, sering pergi ke gunung."},{jp:"にほんへいくとき、かいものをします。",romaji:"",idText:"Saat pergi ke Jepang, saya belanja."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Bencana): Pilihlah arti kata "地震 (じしん)".',sentencePrompt:'Kata "地震" bermakna bencana:',options:["Gempa bumi","Banjir bandang","Gunung meletus","Angin puting beliung"],correctAnswer:"Gempa bumi",explanation:'"地震 (じしん)" berarti gempa bumi.',diagnosticFeedback:{"Banjir bandang":"Salah: Banjir adalah 洪水 (kouzui).","Gunung meletus":"Salah: Letusan adalah 噴火 (funka).","Angin puting beliung":"Salah: Angin topan adalah 台風 (taifuu) atau 竜巻 (tatsumaki)."}},{id:"drill-2",type:"cloze",instruction:'Langkah 2 (Isian Rumus Mae ni): Pilihlah bentuk kata kerja yang tepat sebelum "前に (sebelum)".',sentencePrompt:"寝【ね】る _____、歯【は】を 磨【みが】きます。",options:["前【まえ】に","後【あと】で","とき","から"],correctAnswer:"前【まえ】に",explanation:"Sebelum tidur = 寝る 前に (Verba Kamus + 前に).",diagnosticFeedback:{"後【あと】で":"Salah: 後で harus diawali bentuk-ta (neta ato de) dan artinya jadi setelah tidur.",とき:"Salah: とき berarti saat/ketika.",から:"Salah: から didahului bentuk-te (nete kara)."}},{id:"drill-3",type:"reorder",instruction:"Langkah 3 (Susun Kalimat): Urutkan tindakan saat gempa bumi berikut.",sentencePrompt:"Susunan kalimat yang tepat:",options:["地震【じしん】の とき、机【つくえ】の 下【した】へ 入【はい】ります","机【つくえ】の 下【した】へ 地震【じしん】の とき 入【はい】ります","入【はい】ります 地震【じしん】の とき、机【つくえ】の 下【した】へ","地震【じしん】とき、机【つくえ】の 下【した】へ 入【はい】ります"],correctAnswer:"地震【じしん】の とき、机【つくえ】の 下【した】へ 入【はい】ります",explanation:"Momen kejadian (地震のとき) + Lokasi arah (机の下へ) + Verba (入ります).",diagnosticFeedback:{"机【つくえ】の 下【した】へ 地震【じしん】の とき 入【はい】ります":"Kurang lazim: Keterangan waktu darurat ditaruh paling depan.","入【はい】ります 地震【じしん】の とき、机【つくえ】の 下【した】へ":"Jebakan: Kata kerja di awal kalimat.","地震【じしん】とき、机【つくえ】の 下【した】へ 入【はい】ります":"Jebakan: Lupa partikel の antara nomina dan とき."},tokens:["地震【じしん】の","とき、机【つくえ】の","下【した】へ","入【はい】ります"],correctOrder:["0","1","2","3"]},{id:"drill-4",type:"trap_detect",instruction:'Langkah 4 (Deteksi Jebakan): Manakah bentuk verba yang benar sebelum "後で (setelah)"?',sentencePrompt:'Pilihlah kalimat yang benar untuk "setelah makan siang":',options:["ごはんを 食【た】べた 後【あと】で、薬【くすり】を 飲【の】みます。","ごはんを 食【た】べる 後【あと】で、薬【くすり】を 飲【の】みます。","ごはんを 食【た】べて 後【あと】で、薬【くすり】を 飲【の】みます。","ごはんを 食【た】べます 後【あと】で、薬【くすり】を 飲【の】みます。"],correctAnswer:"ごはんを 食【た】べた 後【あと】で、薬【くすり】を 飲【の】みます。",explanation:"Pola 〜後で WAJIB diawali Verba Bentuk-Ta: 食べた 後で.",diagnosticFeedback:{"ごはんを 食【た】べる 後【あと】で、薬【くすり】を 飲【の】みます。":"Jebakan Fatal: Bentuk kamus dipakai untuk 前に, bukan 後で!","ごはんを 食【た】べて 後【あと】で、薬【くすり】を 飲【の】みます。":"Jebakan: Bentuk-te tidak menempel pada ato de.","ごはんを 食【た】べます 後【あと】で、薬【くすり】を 飲【の】みます。":"Jebakan: Bentuk masu salah digabung."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Saat supervisor bertanya "機械を動かす前に何をしますか", jawaban prosedur keselamatan yang tepat adalah:',sentencePrompt:"Pilihlah jawaban prosedur awal:",options:["動【うご】かす 前【まえ】に、安全点検【あんぜんてんけん】を します。","動【うご】かした 前【まえ】に、掃除【そうじ】します。","知【し】りません、動【うご】かします。","機械【きかい】は さようなら。"],correctAnswer:"動【うご】かす 前【まえ】に、安全点検【あんぜんてんけん】を します。",explanation:"Menjawab dengan pola [Verba Kamus] 前に + tindakan inspeksi keselamatan.",diagnosticFeedback:{"動【うご】かした 前【まえ】に、掃除【そうじ】します。":"Jebakan: Bentuk lampau salah dipakai sebelum mae ni.","知【し】りません、動【うご】かします。":"Sangat berbahaya mengoperasikan mesin tanpa tahu SOP.","機械【きかい】は さようなら。":"Tidak nyambung."}}],can_do_challenge:{statement:"Bisa menjelaskan jadwal operasional mesin sebelum/sesudah dan saat darurat gempa.",situation:"Ujian prosedur keselamatan kerja pabrik bersama instruktur.",promptTask:"Jelaskan tindakan sebelum menyalakan mesin dan tindakan saat terjadi gempa bumi!",modelAnswer:"機械【きかい】を 動【うご】かす 前【まえ】に 点検【てんけん】します。地震【じしん】の ときは、すぐ 止【と】めます。",modelAnswerId:"Sebelum mengoperasikan mesin saya lakukan inspeksi. Saat gempa bumi, segera saya hentikan.",culturalEtiquette:"Gunakan bentuk kamus untuk 前に dan partikel no untuk 地震のとき.",skillUnlocked:["Menguasai hubungan sekuensial mae ni dan ato de","Menguasai penanda waktu darurat no toki"]},pocket_summary:{keyFormula:"[V-Kamus] 前に (sebelum) / [V-ta] 後で (setelah) / [Nomina の] とき (saat)",coreWords:["まえに","あとで","とき","じしん"],coreWarning:'"前に" = Verba Kamus. "後で" = Verba Bentuk-Ta. Nomina + の + とき.',quickDialogue:"A: いつ 飲みますか。 → B: ごはんを 食べた 後で 飲みます。"}},"les-n5-u15-03":{pedagogical_framework:{what:{summary:"Pengandaian syarat [Verba-tara] (kalau/jika), kepastian alamiah [Verba Kamus] と (bila pasti), kemungkinan [Bentuk Biasa] かもしれません (mungkin), dugaan visual [Masu-stem] そうです (tampaknya), dan derajat berlebih [Masu-stem] すぎます (terlalu).",canDo:"Bisa memperkirakan cuaca, membuat kalimat pengandaian jika mesin error, dan melangkah mantap menuju kurikulum N4.",targetPatterns:["[Verba-tara] (jika / seandainya)","[Verba Kamus] と (bila)","[Bentuk Biasa] かもしれません (mungkin)","[Stem] そうです (kelihatan)","[Stem] すぎます (terlalu)"],coreVocabSample:["あめがふったら","ボタンをおすと","おくれるかもしれません","あつすぎます","おいしそう"]},sensei_context:{sceneIntro:"Pelajaran pamungkas N5! Budi, Sakura, Tanaka, dan Kenji merayakan kelulusan tahap dasar N5 di asrama. Mereka mendiskusikan target naik kelas ke level N4.",dailyMission:"Gunakan pengandaian 〜たら dan kemungkinan 〜かもしれません untuk merancang rencana masa depan di Jepang.",whyOrder:"Pola kondisional tara/to dan dugaan sou da / kamoshirenai adalah jembatan emas menuju tata bahasa tingkat menengah N4!"},cultural_notes:{title:"Gerbang Emas Menuju Level N4 & Percakapan Alami",etiquette:"Menguasai 〜たら (kondisional fleksibel) dan 〜かもしれません (kehati-hatian diplomatis) membuat bahasa Jepangmu terdengar dewasa dan matang.",taboos:"Jangan memakai [Verba Kamus] と jika kalimat belakangnya mengandung unsur perintah atau ajakan (Kamus + と hanya untuk kepastian alamiah/mesin)!"},pronunciation_tips:{title:"Intonasi Dugaan Lembut",moraNote:'Lafalkan "kamoshiremasen" secara halus tanpa jeda tersendat.',soundTip:'Katakan "oishisou!" saat melihat makanan lezat dengan nada kagum.'},common_pitfalls:[{title:'Memakai Kondisional "To" untuk Mengajak atau Memerintah',caseScenario:'Mengatakan: "Kalau ada waktu, ayo pergi" menggunakan to.',pitfallWarning:'"じかん が ある と、いこう。" (Salah Gramatikal)',rightSolution:'"じかん が あったら、行【い】こう。" (Benar - Wajib Tara)',explanation:"Pola [V-Kamus] と pantang diikuti kalimat ajakan/kehendak/perintah. Wajib gunakan 〜たら."},{title:'Salah Bentuk Sebelum "Sou desu" (Visual)',caseScenario:'Menempelkan bentuk kamus ke sou desu: "furu sou desu".',pitfallWarning:'"あめ が ふる そうです。" (Artinya jadi: katanya akan hujan - Laporan Kabar)',rightSolution:'"あめ が ふり そうです。" (Benar: Kelihatan mau hujan - Masu-stem)',explanation:"Dugaan visual (tampaknya) menuntut Masu-stem (furisou). Bentuk kamus berarti kabar burung (katanya)."}],who_and_when:{situational_context:"Prakiraan cuaca, troubleshooting masalah mesin pabrik, merencanakan target studi lanjutan N4.",social_relations:"Sangat lazim dan elegan dalam segala konteks sosial.",when_not_to_use:"Jangan gunakan sugiru untuk memuji hal positif (misal jangan bilang kireisugiru dalam situasi formal)."},scenario:{title:"Perayaan Penuntasan Kurikulum N5 dan Menatap Gerbang N4",setting:"Ruang santai asrama bersama Sakura, Kenji, dan Tanaka, pukul 18.30",narrative:"Budi berhasil menyelesaikan seluruh 15 Unit kurikulum N5. Mereka mendiskusikan kesiapan menghadapi tantangan N4."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"ブディさん、Ｎ５の 勉強【べんきょう】を 最後【さいご】まで やり遂【と】げましたね！おめでとう！",furigana:"ブディさん、Ｎ５の 勉強を 最後まで やり遂げましたね！おめでとう！",romaji:"Budi-san, N5 no benkyou o saigo made yaritogemashita ne! Omedetou!",idText:"Budi-san, kamu telah menuntaskan belajar N5 sampai akhir ya! Selamat!"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"田中【たなか】さん、みなさん、熱心【ねっしん】に 教【おし】えていただき 本当【ほんとう】に ありがとうございます！",furigana:"田中さん、みなさん、熱心に 教えていただき 本当に ありがとうございます！",romaji:"Tanaka-san, minasan, nesshin ni oshiete itadaki hontou ni arigatou gozaimasu!",idText:"Tanaka-san, teman-teman semuanya, terima kasih banyak telah mengajari saya dengan sungguh-sungguh!"},{id:"d3",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"ケーキを 買【か】って きましたよ。とても 美味【おい】しそうですね！",furigana:"ケーキを 買って きましたよ。とても 美味しそうですね！",romaji:"Ke-ki o katte kimashita yo. Totemo oishisou desu ne!",idText:"Saya belikan kue lho. Kelihatannya lezat sekali ya!"},{id:"d4",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"食【た】べすぎると 太【ふと】るかもしれないけど、今日【きょう】は お祝【いわ】いだから 食【た】べよう！",furigana:"食べすぎると 太るかもしれないけど、今日は お祝いだから 食べよう！",romaji:"Tabesugiru to futoru kamoshirenai kedo, kyou wa oiwai da kara tabeyou!",idText:"Kalau makan kebanyakan mungkin bisa gemuk sih, tapi karena hari ini perayaan, ayo makan!"},{id:"d5",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい！Ｎ４に 合格【ごうかく】したら、もっと 難【むずか】しい 仕事【しごと】にも 挑戦【ちょうせん】したいです。",furigana:"はい！Ｎ４に 合格したら、もっと 難しい 仕事にも 挑戦したいです。",romaji:"Hai! N4 ni goukaku shitara, motto muzukashii shigoto ni mo chousen shitai desu.",idText:"Iya! Kalau lulus N4, saya ingin menantang pekerjaan yang lebih mendalam lagi."},{id:"d6",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"その 意気【いき】ですよ。毎日【まいにち】続【つづ】けると、必【かなら】ず 力【ちから】が つきます。",furigana:"その 意気ですよ。毎日続けると、必ず 力が つきます。",romaji:"Sono iki desu yo. Mainichi tsuzukeru to, kanarazu chikara ga tsukimasu.",idText:"Itu baru semangat. Bila terus berlanjut setiap hari, pasti kemampuanmu akan bertambah kok."},{id:"d7",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"Ｎ４の レッスンも 一緒【いっしょ】に 頑張【がんば】りましょうね！",furigana:"Ｎ４の レッスンも 一緒に 頑張りましょうね！",romaji:"N4 no ressun mo issho ni gambarimashou ne!",idText:"Pelajaran N4 mari kita perjuangkan bersama-sama lagi ya!"},{id:"d8",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい！全力【ぜんりょく】で 頑張【がんば】ります。これからも よろしく お願【ねが】いします！",furigana:"はい！全力で 頑張ります。これからも よろしく お願いします！",romaji:"Hai! Zenryoku de gambarimasu. Kore kara mo yoroshiku onegaishimasu!",idText:"Baik! Saya akan berusaha sekuat tenaga. Mohon bimbingannya selalu mulai dari sekarang juga!"}],vocab_breakdown:[{id:"vg-n5-00557",word:"店",reading:"みせ",romaji:"mise",meaning:"toko",pos:"noun",nuance:"店 (みせ) = toko/warung. Lebih umum dari 店舗 (tentou = outlet resmi).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"あの店はいつも混んでいます。",furigana:"あの店はいつも混んでいます。",romaji:"",idText:"Toko itu selalu ramai."}},{id:"vg-n5-00558",word:"道",reading:"みち",romaji:"michi",meaning:"jalan",pos:"noun",nuance:"コンビニ = convenience store (7-Eleven, FamilyMart, dll). Fitur penting budaya Jepang.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"コンビニで弁当を買います。",furigana:"コンビニで弁当を買います。",romaji:"",idText:"Saya beli bento di konbini."}},{id:"vg-n5-00559",word:"門",reading:"もん",romaji:"mon",meaning:"gerbang",pos:"noun",nuance:"A physical gate, often large and structural, like a school or temple gate. Contrast with a simple door (ドア).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"学校の正門は朝八時に開きます。",furigana:"学校の正門は朝八時に開きます。",romaji:"",idText:"Pintu gerbang utama sekolah buka jam delapan pagi."}},{id:"vg-n5-00560",word:"専門",reading:"せんもん",romaji:"senmon",meaning:"bidang khusus, spesialisasi",pos:"noun",nuance:"Refers to a person's major in college or their professional area of expertise. Often used when asking about someone's field of study.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"大学での私の専門は日本文学です。",furigana:"大学での私の専門は日本文学です。",romaji:"",idText:"Spesialisasi saya di universitas adalah sastra Jepang."}},{id:"vg-n5-00561",word:"空気",reading:"くうき",romaji:"kuuki",meaning:"udara",pos:"noun",nuance:"The physical air we breathe. Also widely used metaphorically for the 'mood' or 'atmosphere' of a room (e.g., 'reading the air').",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"山の朝の空気はとてもきれいで涼しいです。",furigana:"山の朝の空気はとてもきれいで涼しいです。",romaji:"",idText:"Udara pagi di gunung sangat bersih dan sejuk."}},{id:"vg-n5-00562",word:"空港",reading:"くうこう",romaji:"kuukou",meaning:"bandara",pos:"noun",nuance:"電車 = kereta listrik (bukan shinkansen). 電車に乗る = naik kereta.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"毎日電車で通学しています。",furigana:"毎日電車で通学しています。",romaji:"",idText:"Saya naik kereta setiap hari untuk sekolah."}},{id:"vg-n5-00563",word:"空",reading:"そら",romaji:"sora",meaning:"langit",pos:"noun",nuance:"The sky above. Frequently combined with adjectives like blue (aozora) or starry (hoshizora), where the pronunciation changes to 'zora.'",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"青い空に白い雲が浮かんでいます。",furigana:"青い空に白い雲が浮かんでいます。",romaji:"",idText:"Awan putih terapung di langit yang biru."}},{id:"vg-n5-00564",word:"白",reading:"しろ",romaji:"shiro",meaning:"putih (kata benda)",pos:"noun",nuance:"The noun form of the color white. For the adjective form 'white,' you must add an 'i' (白い).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"白は清潔な感じがする色です。",furigana:"白は清潔な感じがする色です。",romaji:"",idText:"Putih adalah warna yang memberikan kesan bersih."}},{id:"vg-n5-00645",word:"いろ",reading:"いろ",romaji:"iro",meaning:"warna",pos:"noun",nuance:"A general term for color. It can also metaphorically refer to a lover or sensuality in older literature, though this is rare in N5 contexts.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"どんな色が好きですか。",furigana:"どんな色が好きですか。",romaji:"",idText:"Warna seperti apa yang Anda sukai?"}},{id:"vg-n5-00646",word:"あか",reading:"あか",romaji:"aka",meaning:"merah",pos:"noun",nuance:"Refers to the noun 'red'. To use it as an adjective modifying a noun (like 'red car'), you must add an 'i' to make it 'akai'.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"赤はとても目立つ色です。",furigana:"赤はとても目立つ色です。",romaji:"",idText:"Merah adalah warna yang sangat mencolok."}}],explanations:[{id:"exp-1",grammarId:"gn5-00069",title:"Pola: 〜でしょう",formula:"V/Adj plain / N + でしょう",meaning:"mungkin ... / sepertinya ... (perkiraan)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜でしょう",idText:"mungkin ... / sepertinya ... (perkiraan)"}],examples:[{jp:"あしたはあめでしょう。",romaji:"",idText:"Besok mungkin hujan."},{jp:"どこにいるんでしょうか。",romaji:"",idText:"Kira-kira ada di mana ya?"}]},{id:"exp-2",grammarId:"gn5-00070",title:"Pola: 〜そうです (様態)",formula:"V-ます語幹 / Adj-i語幹 / Adj-na + そうです",meaning:"sepertinya ... / kelihatannya ... (dari penglihatan)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜そうです (様態)",idText:"sepertinya ... / kelihatannya ... (dari penglihatan)"}],examples:[{jp:"このりょうりはおいしそうですね。",romaji:"",idText:"Masakan ini kelihatannya enak ya."},{jp:"あめがふりそうです。",romaji:"",idText:"Sepertinya mau hujan."}]},{id:"exp-3",grammarId:"gn5-00079",title:"Pola: 〜かもしれない",formula:"V/Adj plain / N + かもしれない",meaning:"mungkin ... / bisa jadi ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜かもしれない",idText:"mungkin ... / bisa jadi ..."}],examples:[{jp:"かれはもうかえったかもしれない。",romaji:"",idText:"Mungkin dia sudah pulang."},{jp:"あしたは雨かもしれません。",romaji:"",idText:"Besok mungkin hujan."}]},{id:"exp-4",grammarId:"gn5-00047",title:"Pola: 〜たら",formula:"Vた → Vたら / Adjかった → Adjかったら / N + だったら",meaning:"kalau / jika / setelah (kondisional)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜たら",idText:"kalau / jika / setelah (kondisional)"}],examples:[{jp:"うちにかえったら、でんわします。",romaji:"",idText:"Kalau sudah sampai rumah, saya akan menelepon."},{jp:"やすかったらかいます。",romaji:"",idText:"Kalau murah, saya beli."}]},{id:"exp-5",grammarId:"gn5-00048",title:"Pola: 〜と (kondisional)",formula:"V plain / Adj plain + と",meaning:"kalau / jika (kondisi alami/otomatis)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜と (kondisional)",idText:"kalau / jika (kondisi alami/otomatis)"}],examples:[{jp:"みぎにまがると、こうえんがあります。",romaji:"",idText:"Kalau belok kanan, ada taman."},{jp:"はるになると、さくらがさきます。",romaji:"",idText:"Kalau musim semi tiba, bunga sakura mekar."}]},{id:"exp-6",grammarId:"gn5-00049",title:"Pola: 〜ば",formula:"V → V-ba form (e.g. いく → いけば) / Adj → Adj-ければ",meaning:"kalau / jika (kondisional hipotetis)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜ば",idText:"kalau / jika (kondisional hipotetis)"}],examples:[{jp:"はやくおきれば、おくれません。",romaji:"",idText:"Kalau bangun cepat, tidak akan terlambat."},{jp:"やすければかいたいです。",romaji:"",idText:"Kalau murah, ingin beli."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Kata): Pilihlah arti kata "合格 (ごうかく)".',sentencePrompt:'Kata "合格する" bermakna:',options:["Lulus ujian","Gagal / Tidak lulus","Menunda ujian","Mendaftar les"],correctAnswer:"Lulus ujian",explanation:'"合格 (ごうかく)" berarti lulus ujian atau lolos seleksi.',diagnosticFeedback:{"Gagal / Tidak lulus":"Salah: Gagal adalah 不合格 (fugoukaku).","Menunda ujian":"Salah: Menunda adalah 延期 (enki).","Mendaftar les":"Salah: Mendaftar adalah 申し込む (moushikomu)."}},{id:"drill-2",type:"cloze",instruction:'Langkah 2 (Isian Pengandaian Tara): Pilihlah bentuk kondisional "kalau lulus N4".',sentencePrompt:"Ｎ４に 合格【ごうかく】し _____、仕事【しごと】を 頑張【がんば】ります。",options:["たら","ても","と","ば"],correctAnswer:"たら",explanation:"Pengandaian aksi masa depan fleksibel menggunakan [Verba Bentuk-Ta] + ら: 合格したら.",diagnosticFeedback:{ても:'Salah: ても berarti "walaupun lulus" (konsesi).',と:"Salah: と tidak bisa diikuti tekad subjektif pembicara.",ば:"Kurang tepat: Bentuk-ba untuk suru adalah sureba, bukan shitaba."}},{id:"drill-3",type:"reorder",instruction:'Langkah 3 (Susun Kalimat): Urutkan kalimat dugaan visual "kelihatannya lezat" berikut.',sentencePrompt:"Susunan kalimat yang tepat:",options:["この ケーキは とても 美味【おい】しそうです","とても 美味【おい】しそうです この ケーキは","美味しそうです この ケーキは とても","この ケーキは 美味【おい】しいそうです とても"],correctAnswer:"この ケーキは とても 美味【おい】しそうです",explanation:"Topik (このケーキは) + Adverbia (とても) + Dugaan visual Masu-stem (美味しそうです).",diagnosticFeedback:{"とても 美味【おい】しそうです この ケーキは":"Jebakan: Topik ditaruh di akhir kalimat.","美味しそうです この ケーキは とても":"Jebakan: Susunan kata acak.","この ケーキは 美味【おい】しいそうです とても":'Jebakan: "Oishii sou desu" dengan huruf i utuh berarti laporan kabar burung (katanya enak).'},tokens:["この","ケーキは","とても","美味【おい】しそうです"],correctOrder:["0","1","2","3"]},{id:"drill-4",type:"trap_detect",instruction:"Langkah 4 (Deteksi Jebakan): Manakah penggunaan pola derajat berlebih (sugiru) yang benar?",sentencePrompt:'Pilihlah kalimat yang menyatakan "terlalu banyak makan":',options:["ごはんを 食【た】べすぎました。","ごはんを 食【た】べるすぎました。","ごはんを 食【た】べたすぎました。","ごはんを 食【た】べないすぎました。"],correctAnswer:"ごはんを 食【た】べすぎました。",explanation:"Pola 〜すぎる didahului oleh Masu-stem (kata kerja bentuk masu tanpa masu): 食べ(ます) + すぎました.",diagnosticFeedback:{"ごはんを 食【た】べるすぎました。":"Jebakan Fatal: Bentuk kamus tidak boleh digabung dengan sugiru.","ごはんを 食【た】べたすぎました。":"Jebakan: Bentuk lampau salah digabung.","ごはんを 食【た】べないすぎました。":"Jebakan: Bentuk negatif salah digabung."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Saat rekan kerja memberi selamat "N5の勉強を最後までやり遂げましたね！おめでとう！", respon terbaik adalah:',sentencePrompt:"Pilihlah ungkapan rasa syukur dan menatap masa depan:",options:["ありがとうございます！Ｎ４も 全力【ぜんりょく】で 頑張【がんば】ります！","いいえ、だめでした。","日本語【にほんご】は さようなら。","勉強【べんきょう】は 嫌【きら】いです。"],correctAnswer:"ありがとうございます！Ｎ４も 全力【ぜんりょく】で 頑張【がんば】ります！",explanation:"Mengucapkan terima kasih dan menegaskan semangat melanjutkan ke level N4.",diagnosticFeedback:{"いいえ、だめでした。":"Pesimis dan tidak menghargai selamat dari rekan.","日本語【にほんご】は さようなら。":"Menyerah padahal baru lulus N5.","勉強【べんきょう】は 嫌【きら】いです。":"Kasar dan tidak pantas diucapkan."}}],can_do_challenge:{statement:"Bisa memperkirakan kemungkinan dan menyatakan pengandaian target belajar N4.",situation:"Perayaan kelulusan N5 dan penetapan target kelulusan N4.",promptTask:"Katakan bahwa kalau lulus N4, kamu ingin mencoba pekerjaan yang lebih menantang!",modelAnswer:"Ｎ４に 合格【ごうかく】したら、もっと 難【むずか】しい 仕事【しごと】に 挑戦【ちょうせん】したいです。",modelAnswerId:"Kalau lulus N4, saya ingin menantang pekerjaan yang lebih sulit.",culturalEtiquette:"Gunakan pengandaian 〜たら dan akhiran keinginan 〜たいです.",skillUnlocked:["Menguasai pengandaian tara dan keniscayaan to","Menguasai dugaan visual sou da dan derajat sugiru","Kesiapan mental 100% melangkah ke level N4"]},pocket_summary:{keyFormula:"[V-tara] (jika) / [V-Kamus] と (pasti bila) / [Stem] そうです (tampaknya) / すぎる (terlalu)",coreWords:["ごうかく","おいしそう","たべすぎました","かもしれない"],coreWarning:'Kondisional "to" tidak boleh diikuti ajakan/perintah. "Sou desu" visual memakai Masu-stem.',quickDialogue:"A: 合格したら どうしますか。 → B: もっと 勉強します！"}}};export{r as a,t as b,i as c,e as d,n as e,a as f,u};
